import type { BankQuestion } from "@/lib/bank";

/** Physical Geography of India (Geography): 214 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-physical-india-1","question":"The highest peak of the Western Ghats is:","options":["Doddabetta","Anamudi","Mahendragiri","Kalsubai"],"answer":1,"explanation":"Anamudi (2,695 m), in Kerala, is the highest peak in India south of the Himalaya.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"पश्चिमी घाट की सबसे ऊँची चोटी कौन-सी है?","optionsHi":["डोडाबेट्टा","अनामुडी","महेंद्रगिरि","कलसुबाई"],"explanationHi":"केरल में स्थित अनामुडी (2,695 मीटर) हिमालय के दक्षिण में भारत की सबसे ऊँची चोटी है।"},
  {"id":"geo-physical-india-2","question":"The southernmost point of the Indian Union is:","options":["Kanyakumari","Indira Point","Rameswaram","Point Calimere"],"answer":1,"explanation":"Indira Point on Great Nicobar is the southernmost point; Kanyakumari is the southern tip of the mainland.","difficulty":"easy","questionHi":"भारतीय संघ का सबसे दक्षिणी बिंदु कौन-सा है?","optionsHi":["कन्याकुमारी","इंदिरा प्वाइंट","रामेश्वरम","प्वाइंट कैलिमेर"],"explanationHi":"ग्रेट निकोबार का इंदिरा प्वाइंट सबसे दक्षिणी बिंदु है; कन्याकुमारी मुख्य भूमि का दक्षिणी सिरा है।"},
  {"id":"geo-physical-india-3","question":"Which strait separates India from Sri Lanka?","options":["Malacca Strait","Palk Strait","Bab-el-Mandeb","Hormuz Strait"],"answer":1,"explanation":"The narrow Palk Strait lies between Tamil Nadu and northern Sri Lanka.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"कौन-सी जलसंधि भारत को श्रीलंका से अलग करती है?","optionsHi":["मलक्का जलसंधि","पाक जलसंधि","बाब-एल-मंडेब","होर्मुज़ जलसंधि"],"explanationHi":"संकरी पाक जलसंधि तमिलनाडु और उत्तरी श्रीलंका के बीच स्थित है।"},
  {"id":"geo-physical-india-4","question":"Black (regur) soil is best suited to the cultivation of:","options":["Coffee","Cotton","Rice","Jute"],"answer":1,"explanation":"Moisture-retentive black soil of the Deccan lava plateau, rich in lime and potash, is ideal for cotton. Coffee needs well-drained red and laterite hill soils.","difficulty":"easy","questionHi":"काली (रेगुर) मृदा किसकी खेती के लिए सबसे उपयुक्त है?","optionsHi":["कॉफ़ी","कपास","चावल","जूट"],"explanationHi":"दक्कन के लावा पठार की नमी धारण करने वाली काली मृदा, जो चूने और पोटाश से समृद्ध है, कपास के लिए आदर्श है। कॉफ़ी को अच्छी जल निकासी वाली लाल और लेटराइट पहाड़ी मृदाएँ चाहिए।"},
  {"id":"geo-physical-india-5","question":"The outermost (southernmost) range of the Himalaya is the:","options":["Himadri","Himachal","Shiwalik","Karakoram"],"answer":2,"explanation":"The Shiwaliks (Outer Himalaya) are the southernmost, lowest and youngest range, made of unconsolidated river debris. The Himadri is the innermost Great Himalaya and the Himachal is the Lesser Himalaya between the two.","difficulty":"easy","questionHi":"हिमालय की सबसे बाहरी (सबसे दक्षिणी) श्रेणी कौन-सी है?","optionsHi":["हिमाद्रि","हिमाचल","शिवालिक","काराकोरम"],"explanationHi":"शिवालिक (बाह्य हिमालय) सबसे दक्षिणी, सबसे निचली और सबसे नई श्रेणी है, जो असंगठित नदी अवसादों से बनी है। हिमाद्रि सबसे भीतरी वृहत् हिमालय है और हिमाचल दोनों के बीच का लघु हिमालय है।"},
  {"id":"geo-physical-india-6","question":"The south-west monsoon usually first reaches the Indian mainland in:","options":["Kerala","West Bengal","Gujarat","Odisha"],"answer":0,"explanation":"The south-west monsoon sets in over the Kerala coast around 1 June, when its Arabian Sea branch strikes the Western Ghats. West Bengal is reached later, by the Bay of Bengal branch.","difficulty":"easy","questionHi":"दक्षिण-पश्चिम मानसून सामान्यतः भारतीय मुख्य भूमि पर सबसे पहले कहाँ पहुँचता है?","optionsHi":["केरल","पश्चिम बंगाल","गुजरात","ओडिशा"],"explanationHi":"दक्षिण-पश्चिम मानसून लगभग 1 जून को केरल तट पर आता है, जब इसकी अरब सागर शाखा पश्चिमी घाट से टकराती है। पश्चिम बंगाल में यह बाद में बंगाल की खाड़ी की शाखा से पहुँचता है।"},
  {"id":"geo-physical-india-7","question":"The Lesser Himalaya is also known as the:","options":["Himadri","Himachal","Shiwalik","Purvanchal"],"answer":1,"explanation":"Himadri is the Greater Himalaya and Shiwalik the Outer Himalaya; the middle range is Himachal.","difficulty":"moderate","questionHi":"लघु हिमालय को और किस नाम से जाना जाता है?","optionsHi":["हिमाद्रि","हिमाचल","शिवालिक","पूर्वांचल"],"explanationHi":"हिमाद्रि वृहत् हिमालय है और शिवालिक बाह्य हिमालय; बीच की श्रेणी हिमाचल है।"},
  {"id":"geo-physical-india-8","question":"Laterite soil develops mainly because of:","options":["Wind-borne dust settling in dry areas","Leaching under high heat and heavy rain","Glacial grinding of rocks on plateaus","Silt laid down by rivers during floods"],"answer":1,"explanation":"Heavy rain washes out silica and lime, leaving iron and aluminium oxides.","difficulty":"moderate","questionHi":"लेटराइट मृदा मुख्यतः किस कारण बनती है?","optionsHi":["शुष्क क्षेत्रों में पवन द्वारा उड़ाई गई धूल के जमने से","उच्च ताप और भारी वर्षा में निक्षालन से","पठारों पर हिमनदों द्वारा चट्टानों के घिसने से","बाढ़ के दौरान नदियों द्वारा जमा की गई गाद से"],"explanationHi":"भारी वर्षा सिलिका और चूने को बहा ले जाती है, जिससे लोहे और एल्युमिनियम के ऑक्साइड शेष रह जाते हैं।"},
  {"id":"geo-physical-india-9","question":"Mawsynram, one of the wettest places on Earth, is in:","options":["Assam","Meghalaya","Sikkim","Arunachal Pradesh"],"answer":1,"explanation":"Mawsynram lies on the southern slopes of the Khasi hills, Meghalaya.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मौसिनराम, जो पृथ्वी के सबसे अधिक वर्षा वाले स्थानों में से एक है, कहाँ स्थित है?","optionsHi":["असम","मेघालय","सिक्किम","अरुणाचल प्रदेश"],"explanationHi":"मौसिनराम मेघालय में खासी पहाड़ियों की दक्षिणी ढलानों पर स्थित है।"},
  {"id":"geo-physical-india-10","question":"The Ten Degree Channel separates:","options":["Andaman from Nicobar","Lakshadweep from Maldives","India from Sri Lanka","Minicoy from Lakshadweep"],"answer":0,"explanation":"It lies between Little Andaman and Car Nicobar; the Eight Degree Channel separates Minicoy from the Maldives.","difficulty":"moderate","questionHi":"टेन डिग्री चैनल किन्हें अलग करता है?","optionsHi":["अंडमान को निकोबार से","लक्षद्वीप को मालदीव से","भारत को श्रीलंका से","मिनिकॉय को लक्षद्वीप से"],"explanationHi":"यह लिटिल अंडमान और कार निकोबार के बीच है; एट डिग्री चैनल मिनिकॉय को मालदीव से अलग करता है।"},
  {"id":"geo-physical-india-11","question":"Nathu La pass connects Sikkim with:","options":["Nepal","Bhutan","Tibet","Myanmar"],"answer":2,"explanation":"Nathu La, on the old silk route, links Sikkim with the Chumbi valley of Tibet.","difficulty":"moderate","questionHi":"नाथू ला दर्रा सिक्किम को किससे जोड़ता है?","optionsHi":["नेपाल","भूटान","तिब्बत","म्यांमार"],"explanationHi":"प्राचीन रेशम मार्ग पर स्थित नाथू ला सिक्किम को तिब्बत की चुंबी घाटी से जोड़ता है।"},
  {"id":"geo-physical-india-12","question":"Zoji La pass links:","options":["Srinagar and Leh","Shimla and Kinnaur","Manali and Leh","Gangtok and Lhasa"],"answer":0,"explanation":"Zoji La connects the Kashmir valley with Ladakh on the Srinagar–Leh road.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"ज़ोजिला दर्रा किन्हें जोड़ता है?","optionsHi":["श्रीनगर और लेह","शिमला और किन्नौर","मनाली और लेह","गंगटोक और ल्हासा"],"explanationHi":"ज़ोजिला श्रीनगर-लेह मार्ग पर कश्मीर घाटी को लद्दाख से जोड़ता है।"},
  {"id":"geo-physical-india-13","question":"Which part of India is a cold desert?","options":["Thar","Rann of Kutch","Ladakh","Sundarbans"],"answer":2,"explanation":"Ladakh lies in the rain shadow of the Greater Himalaya and is very cold and dry.","difficulty":"moderate","questionHi":"भारत का कौन-सा भाग शीत मरुस्थल है?","optionsHi":["थार","कच्छ का रन","लद्दाख","सुंदरबन"],"explanationHi":"लद्दाख वृहत् हिमालय के वृष्टि छाया क्षेत्र में स्थित है और बहुत ठंडा तथा शुष्क है।"},
  {"id":"geo-physical-india-14","question":"Shipki La pass, through which the Sutlej enters India, is in:","options":["Jammu and Kashmir","Himachal Pradesh","Uttarakhand","Sikkim"],"answer":1,"explanation":"Shipki La lies in Kinnaur district of Himachal Pradesh, where the Sutlej enters from Tibet. Jammu and Kashmir is tempting because the Indus enters India in Ladakh, but that is a different river.","difficulty":"hard","questionHi":"शिपकी ला दर्रा, जिससे होकर सतलुज भारत में प्रवेश करती है, कहाँ स्थित है?","optionsHi":["जम्मू और कश्मीर","हिमाचल प्रदेश","उत्तराखंड","सिक्किम"],"explanationHi":"शिपकी ला हिमाचल प्रदेश के किन्नौर ज़िले में है, जहाँ सतलुज तिब्बत से आती है। जम्मू और कश्मीर भ्रम पैदा करता है क्योंकि सिंधु लद्दाख में भारत में प्रवेश करती है, पर वह अलग नदी है।"},
  {"id":"geo-physical-india-15","question":"The Garo, Khasi and Jaintia hills are in:","options":["Assam","Meghalaya","Nagaland","Manipur"],"answer":1,"explanation":"They form the Meghalaya plateau, a detached part of the peninsular block.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"गारो, खासी और जयंतिया पहाड़ियाँ कहाँ हैं?","optionsHi":["असम","मेघालय","नागालैंड","मणिपुर"],"explanationHi":"ये मिलकर मेघालय पठार बनाती हैं, जो प्रायद्वीपीय खंड का एक अलग हुआ भाग है।"},
  {"id":"geo-physical-india-16","question":"The Coromandel coast of Tamil Nadu gets most of its rainfall during:","options":["June–September","October–December","March–May","January–February"],"answer":1,"explanation":"It is in the rain shadow during the south-west monsoon and gets rain from the retreating / north-east monsoon.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"तमिलनाडु के कोरोमंडल तट पर अधिकांश वर्षा किस अवधि में होती है?","optionsHi":["जून-सितंबर","अक्टूबर-दिसंबर","मार्च-मई","जनवरी-फ़रवरी"],"explanationHi":"दक्षिण-पश्चिम मानसून के दौरान यह वृष्टि छाया में रहता है और लौटते / उत्तर-पूर्वी मानसून से वर्षा पाता है।"},
  {"id":"geo-physical-india-17","question":"“Kalbaisakhi”, violent evening thunderstorms of April–May, are typical of:","options":["Kerala","Uttar Pradesh","West Bengal","Rajasthan"],"answer":2,"explanation":"These nor’westers bring pre-monsoon showers to West Bengal and Assam.","difficulty":"hard","questionHi":"“कालबैसाखी”, अप्रैल-मई की तेज़ शाम की आँधी-तूफ़ान वाली वर्षा, किसकी विशेषता है?","optionsHi":["केरल","उत्तर प्रदेश","पश्चिम बंगाल","राजस्थान"],"explanationHi":"ये नॉरवेस्टर पश्चिम बंगाल और असम में मानसून-पूर्व वर्षा लाते हैं।"},
  {"id":"geo-physical-india-18","question":"The Sundarbans mangrove forest is named after the:","options":["Casuarina tree","Sundari tree","Teak tree","Deodar tree"],"answer":1,"explanation":"The Sundari (Heritiera fomes) is the characteristic mangrove tree of the Ganga–Brahmaputra delta. Casuarina is planted on sandy coasts as a shelter belt but is not a mangrove.","difficulty":"hard","questionHi":"सुंदरबन के मैंग्रोव वन का नाम किस वृक्ष के नाम पर पड़ा है?","optionsHi":["केज़ुराइना वृक्ष","सुंदरी वृक्ष","सागौन वृक्ष","देवदार वृक्ष"],"explanationHi":"सुंदरी (हेरिटिएरा फ़ोमीस) गंगा-ब्रह्मपुत्र डेल्टा का विशिष्ट मैंग्रोव वृक्ष है। केज़ुराइना रेतीले तटों पर आश्रय पट्टी के रूप में लगाया जाता है, पर वह मैंग्रोव नहीं है।"},
  {"id":"geo-physical-india-19","question":"The belt of pebbles and boulders at the foot of the Shiwaliks, where streams disappear underground, is called the:","options":["Terai","Bhabar","Bhangar","Khadar"],"answer":1,"explanation":"Streams sink into the porous Bhabar and re-emerge in the marshy Terai to its south.","difficulty":"hard","questionHi":"शिवालिक की तलहटी में कंकड़-पत्थरों की वह पट्टी, जहाँ धाराएँ भूमिगत हो जाती हैं, क्या कहलाती है?","optionsHi":["तराई","भाबर","भांगर","खादर"],"explanationHi":"धाराएँ सरंध्र भाबर में समा जाती हैं और उसके दक्षिण में दलदली तराई में पुनः प्रकट होती हैं।"},
  {"id":"geo-physical-india-20","question":"Through how many Indian states does the Tropic of Cancer pass?","options":["5","7","8","9"],"answer":2,"explanation":"It crosses 8 states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram. 7 forgets Tripura, 9 wrongly adds Odisha (which lies wholly south of 23.5° N), and 5 is the count for the 82.5° E standard meridian.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"कर्क रेखा भारत के कितने राज्यों से होकर गुज़रती है?","optionsHi":["5","7","8","9"],"explanationHi":"यह 8 राज्यों से गुज़रती है: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिज़ोरम। 7 में त्रिपुरा छूट जाता है, 9 में गलती से ओडिशा जुड़ जाता है (जो पूरी तरह 23.5° उ. के दक्षिण में है), और 5 की संख्या 82.5° पू. मानक याम्योत्तर की है।"},
  {"id":"geo-physical-india-21","question":"Arrange these Himalayan ranges from north to south: 1. Shiwalik 2. Himadri 3. Himachal 4. Karakoram","options":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","2, 3, 4, 1"],"answer":0,"explanation":"Karakoram (Trans-Himalaya), then the Greater (Himadri), Lesser (Himachal) and Outer (Shiwalik) ranges.","difficulty":"very-hard","questionHi":"इन हिमालयी श्रेणियों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए: 1. शिवालिक 2. हिमाद्रि 3. हिमाचल 4. काराकोरम","optionsHi":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","2, 3, 4, 1"],"explanationHi":"काराकोरम (ट्रांस-हिमालय), फिर वृहत् (हिमाद्रि), लघु (हिमाचल) और बाह्य (शिवालिक) श्रेणियाँ।"},
  {"id":"geo-physical-india-22","question":"Arrange these passes from west to east: 1. Nathu La 2. Shipki La 3. Zoji La 4. Lipulekh","options":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","3, 2, 1, 4"],"answer":0,"explanation":"Zoji La (J&K), Shipki La (Himachal), Lipulekh (Uttarakhand), Nathu La (Sikkim).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन दर्रों को पश्चिम से पूर्व के क्रम में व्यवस्थित कीजिए: 1. नाथू ला 2. शिपकी ला 3. ज़ोजिला 4. लिपुलेख","optionsHi":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","3, 2, 1, 4"],"explanationHi":"ज़ोजिला (J&K), शिपकी ला (हिमाचल), लिपुलेख (उत्तराखंड), नाथू ला (सिक्किम)।"},
  {"id":"geo-physical-india-23","question":"How many of these statements are correct? I. Alluvial soil is the most widespread soil in India. II. Black soil is rich in nitrogen. III. Red soil gets its colour from iron oxide.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"I and III are correct. Black soil is rich in lime, iron and magnesia but poor in nitrogen and phosphorus.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. जलोढ़ मृदा भारत की सबसे व्यापक मृदा है। II. काली मृदा नाइट्रोजन से समृद्ध होती है। III. लाल मृदा अपना रंग आयरन ऑक्साइड से पाती है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"I और III सही हैं। काली मृदा चूने, लोहे और मैग्नीशिया से समृद्ध है, पर नाइट्रोजन और फॉस्फोरस में कमज़ोर।"},
  {"id":"geo-physical-india-24","question":"Assertion (A): Tamil Nadu receives much of its annual rain between October and December. Reason (R): The north-east monsoon winds pick up moisture while crossing the Bay of Bengal.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The winds turn moist over the Bay of Bengal and shed it on the Coromandel coast.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): तमिलनाडु को अपनी वार्षिक वर्षा का बहुत-सा भाग अक्टूबर से दिसंबर के बीच मिलता है। कारण (R): उत्तर-पूर्वी मानसून की पवनें बंगाल की खाड़ी पार करते समय नमी ग्रहण करती हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पवनें बंगाल की खाड़ी के ऊपर नम हो जाती हैं और कोरोमंडल तट पर वर्षा करती हैं।"},
  {"id":"geo-physical-india-25","question":"Which pair of plateau and state is NOT correctly matched?","options":["Chota Nagpur – Jharkhand","Bundelkhand – Uttar Pradesh","Marwar upland – Rajasthan","Shillong plateau – Mizoram"],"answer":3,"explanation":"The Shillong plateau lies in Meghalaya as a detached block of the peninsular plateau; Mizoram has the young folded Mizo (Lushai) hills. Chota Nagpur, Bundelkhand and the Marwar upland are matched correctly.","difficulty":"very-hard","questionHi":"पठार और राज्य का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["छोटानागपुर – झारखंड","बुंदेलखंड – उत्तर प्रदेश","मारवाड़ उच्चभूमि – राजस्थान","शिलांग पठार – मिज़ोरम"],"explanationHi":"शिलांग पठार मेघालय में प्रायद्वीपीय पठार के एक अलग खंड के रूप में स्थित है; मिज़ोरम में नई वलित मिज़ो (लुशाई) पहाड़ियाँ हैं। छोटानागपुर, बुंदेलखंड और मारवाड़ उच्चभूमि सही सुमेलित हैं।"},
  {"id":"geo-physical-india-26","question":"Consider: 1. The Western Ghats are more continuous than the Eastern Ghats. 2. The Godavari, Krishna and Kaveri all rise in the Western Ghats. 3. The Eastern Ghats are higher on average than the Western Ghats. Which is/are correct?","options":["1 and 2 only","2 and 3 only","1 only","1, 2 and 3"],"answer":0,"explanation":"The Eastern Ghats are lower and broken by rivers, so statement 3 is wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित पर विचार कीजिए: 1. पश्चिमी घाट पूर्वी घाट की तुलना में अधिक सतत हैं। 2. गोदावरी, कृष्णा और कावेरी तीनों पश्चिमी घाट से निकलती हैं। 3. पूर्वी घाट औसतन पश्चिमी घाट से ऊँचे हैं। कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1","1, 2 और 3"],"explanationHi":"पूर्वी घाट निचले हैं और नदियों द्वारा कटे हुए हैं, इसलिए कथन 3 गलत है।"},
  {"id":"geo-physical-india-27","question":"How many of these statements are correct? I. The Aravalli is the oldest fold mountain range in India. II. The Deccan Trap was formed by fissure volcanic eruptions. III. The northern plains lie between the Shiwaliks and the peninsular plateau. IV. Khadar is older alluvium than Bhangar.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Bhangar is the older alluvium on higher ground; Khadar is the newer alluvium of the flood plains.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. अरावली भारत की सबसे पुरानी वलित पर्वत श्रेणी है। II. दक्कन ट्रैप का निर्माण दरारी ज्वालामुखी उद्गारों से हुआ। III. उत्तरी मैदान शिवालिक और प्रायद्वीपीय पठार के बीच स्थित हैं। IV. खादर, भांगर से पुराना जलोढ़ है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। भांगर ऊँची भूमि पर स्थित पुराना जलोढ़ है; खादर बाढ़ के मैदानों का नया जलोढ़ है।"},
  {"id":"geo-physical-india-28","question":"Which of these passes is NOT in Himachal Pradesh?","options":["Rohtang","Bara Lacha La","Shipki La","Lipulekh"],"answer":3,"explanation":"Lipulekh is in Uttarakhand, on the route to Kailash–Mansarovar. Rohtang and Bara Lacha La are in the Kullu–Lahaul region and Shipki La in Kinnaur.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सा दर्रा हिमाचल प्रदेश में नहीं है?","optionsHi":["रोहतांग","बारालाचा ला","शिपकी ला","लिपुलेख"],"explanationHi":"लिपुलेख उत्तराखंड में, कैलाश-मानसरोवर मार्ग पर है। रोहतांग और बारालाचा ला कुल्लू-लाहौल क्षेत्र में और शिपकी ला किन्नौर में हैं।"},
  {"id":"geo-physical-india-29","question":"Arrange these stretches of the western coast from north to south: 1. Malabar coast 2. Konkan coast 3. Kanara coast 4. Kathiawar coast","options":["4-2-3-1","2-4-3-1","4-3-2-1","4-2-1-3"],"answer":0,"explanation":"Kathiawar (Gujarat), Konkan (Maharashtra–Goa), Kanara (Karnataka), Malabar (Kerala).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"पश्चिमी तट के इन भागों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए: 1. मालाबार तट 2. कोंकण तट 3. कन्नड़ (कनारा) तट 4. काठियावाड़ तट","optionsHi":["4-2-3-1","2-4-3-1","4-3-2-1","4-2-1-3"],"explanationHi":"काठियावाड़ (गुजरात), कोंकण (महाराष्ट्र-गोवा), कनारा (कर्नाटक), मालाबार (केरल)।"},
  {"id":"geo-physical-india-30","question":"Assertion (A): Mumbai receives far more rainfall than Pune. Reason (R): Pune lies on the leeward side of the Western Ghats.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The Arabian Sea branch of the monsoon drops its rain on the windward slopes near Mumbai; Pune, in the rain shadow, gets much less.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): मुंबई में पुणे की तुलना में कहीं अधिक वर्षा होती है। कारण (R): पुणे पश्चिमी घाट के पवनविमुख ढाल की ओर स्थित है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"मानसून की अरब सागर शाखा मुंबई के निकट पवनमुखी ढालों पर वर्षा कर देती है; वृष्टि छाया में स्थित पुणे में बहुत कम वर्षा होती है।"},
  {"id":"geo-physical-india-31","question":"Kangchenjunga, the highest peak lying within India’s administered territory, is in the state of:","options":["Uttarakhand","Himachal Pradesh","Sikkim","Arunachal Pradesh"],"answer":2,"explanation":"Kangchenjunga (8,586 m) stands on the Sikkim–Nepal border; Nanda Devi (7,816 m) in Uttarakhand is the highest peak lying entirely inside India.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"कंचनजंघा, जो भारत के प्रशासित क्षेत्र में स्थित सबसे ऊँची चोटी है, किस राज्य में है?","optionsHi":["उत्तराखंड","हिमाचल प्रदेश","सिक्किम","अरुणाचल प्रदेश"],"explanationHi":"कंचनजंघा (8,586 मीटर) सिक्किम-नेपाल सीमा पर स्थित है; उत्तराखंड की नंदा देवी (7,816 मीटर) पूरी तरह भारत के भीतर स्थित सबसे ऊँची चोटी है।"},
  {"id":"geo-physical-india-32","question":"India’s standard meridian, 82°30′ E, passes close to:","options":["Mirzapur (Uttar Pradesh)","Nagpur (Maharashtra)","Bhopal (Madhya Pradesh)","Jabalpur (Madhya Pradesh)"],"answer":0,"explanation":"The 82°30′ E meridian passing through Mirzapur gives Indian Standard Time, 5 hours 30 minutes ahead of GMT; it also passes through Chhattisgarh, Odisha and Andhra Pradesh.","difficulty":"easy","source":"SSC CHSL · UPSSSC PET","questionHi":"भारत का मानक याम्योत्तर, 82°30′ पू., किसके निकट से गुज़रता है?","optionsHi":["मिर्ज़ापुर (उत्तर प्रदेश)","नागपुर (महाराष्ट्र)","भोपाल (मध्य प्रदेश)","जबलपुर (मध्य प्रदेश)"],"explanationHi":"मिर्ज़ापुर से गुज़रने वाला 82°30′ पू. याम्योत्तर भारतीय मानक समय देता है, जो GMT से 5 घंटे 30 मिनट आगे है; यह छत्तीसगढ़, ओडिशा और आंध्र प्रदेश से भी गुज़रता है।"},
  {"id":"geo-physical-india-33","question":"The Deccan plateau is bounded on the north by the:","options":["Aravalli range","Satpura range","Nilgiri hills","Eastern Ghats"],"answer":1,"explanation":"The Satpura range (with the Vindhya further north) marks the northern limit of the Deccan; the Western and Eastern Ghats form its western and eastern edges.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"दक्कन पठार की उत्तरी सीमा कौन बनाता है?","optionsHi":["अरावली श्रेणी","सतपुड़ा श्रेणी","नीलगिरि पहाड़ियाँ","पूर्वी घाट"],"explanationHi":"सतपुड़ा श्रेणी (उससे और उत्तर में विंध्य) दक्कन की उत्तरी सीमा बनाती है; पश्चिमी और पूर्वी घाट उसके पश्चिमी और पूर्वी किनारे बनाते हैं।"},
  {"id":"geo-physical-india-34","question":"Chilika, the largest brackish-water lagoon in India, lies in:","options":["Andhra Pradesh","Odisha","Tamil Nadu","Kerala"],"answer":1,"explanation":"Chilika in Odisha, separated from the Bay of Bengal by a sand spit, was one of India’s first two Ramsar sites (1981, along with Keoladeo); Pulicat in Andhra Pradesh–Tamil Nadu is the second largest such lagoon.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"चिल्का, भारत की सबसे बड़ी खारे पानी की लैगून, कहाँ स्थित है?","optionsHi":["आंध्र प्रदेश","ओडिशा","तमिलनाडु","केरल"],"explanationHi":"ओडिशा की चिल्का, जो रेत की पट्टी द्वारा बंगाल की खाड़ी से अलग है, भारत के पहले दो रामसर स्थलों में से एक थी (1981, केवलादेव के साथ); आंध्र प्रदेश-तमिलनाडु की पुलिकट दूसरी सबसे बड़ी ऐसी लैगून है।"},
  {"id":"geo-physical-india-35","question":"Wular, the largest freshwater lake in India, is in:","options":["Himachal Pradesh","Jammu and Kashmir","Arunachal Pradesh","Manipur"],"answer":1,"explanation":"Wular lake in the Kashmir valley is fed by the Jhelum; it is of tectonic origin. Loktak in Manipur is the largest freshwater lake of the north-east.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"वूलर, भारत की सबसे बड़ी मीठे पानी की झील, कहाँ स्थित है?","optionsHi":["हिमाचल प्रदेश","जम्मू और कश्मीर","अरुणाचल प्रदेश","मणिपुर"],"explanationHi":"कश्मीर घाटी की वूलर झील को झेलम से जल मिलता है; यह विवर्तनिक उत्पत्ति की है। मणिपुर की लोकटक पूर्वोत्तर की सबसे बड़ी मीठे पानी की झील है।"},
  {"id":"geo-physical-india-36","question":"Which of these hill ranges is NOT a part of the Purvanchal (eastern) hills?","options":["Patkai Bum","Naga hills","Mizo (Lushai) hills","Dhauladhar range"],"answer":3,"explanation":"The Purvanchal comprises the Patkai, Naga, Manipur and Mizo hills along the Myanmar border; the Dhauladhar is a Lesser Himalayan range in Himachal Pradesh.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कौन-सी पहाड़ी श्रेणी पूर्वांचल (पूर्वी) पहाड़ियों का भाग नहीं है?","optionsHi":["पटकाई बुम","नागा पहाड़ियाँ","मिज़ो (लुशाई) पहाड़ियाँ","धौलाधार श्रेणी"],"explanationHi":"पूर्वांचल में म्यांमार सीमा के साथ पटकाई, नागा, मणिपुर और मिज़ो पहाड़ियाँ आती हैं; धौलाधार हिमाचल प्रदेश की लघु हिमालय की श्रेणी है।"},
  {"id":"geo-physical-india-37","question":"Doddabetta, the highest peak of the Nilgiri hills, lies where the Western and Eastern Ghats meet. It is in the state of:","options":["Kerala","Karnataka","Tamil Nadu","Andhra Pradesh"],"answer":2,"explanation":"Doddabetta (2,637 m) near Ooty in Tamil Nadu is the highest point of the Nilgiris; Anamudi (2,695 m) in Kerala is the highest of the Western Ghats as a whole.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"डोडाबेट्टा, नीलगिरि पहाड़ियों की सबसे ऊँची चोटी, वहाँ स्थित है जहाँ पश्चिमी और पूर्वी घाट मिलते हैं। यह किस राज्य में है?","optionsHi":["केरल","कर्नाटक","तमिलनाडु","आंध्र प्रदेश"],"explanationHi":"ऊटी के निकट तमिलनाडु में स्थित डोडाबेट्टा (2,637 मीटर) नीलगिरि का सबसे ऊँचा बिंदु है; केरल की अनामुडी (2,695 मीटर) पूरे पश्चिमी घाट की सबसे ऊँची चोटी है।"},
  {"id":"geo-physical-india-38","question":"Guru Shikhar, the highest peak of the Aravalli range, is located on:","options":["Mount Abu","Ajmer hills","Alwar hills","Delhi ridge"],"answer":0,"explanation":"Guru Shikhar (1,722 m) on Mount Abu in Sirohi district, Rajasthan, crowns the Aravalli, one of the world’s oldest fold mountain systems.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"गुरु शिखर, अरावली श्रेणी की सबसे ऊँची चोटी, कहाँ स्थित है?","optionsHi":["माउंट आबू","अजमेर की पहाड़ियाँ","अलवर की पहाड़ियाँ","दिल्ली रिज"],"explanationHi":"राजस्थान के सिरोही ज़िले में माउंट आबू पर स्थित गुरु शिखर (1,722 मीटर) अरावली का शिखर है, जो विश्व की सबसे पुरानी वलित पर्वत प्रणालियों में से एक है।"},
  {"id":"geo-physical-india-39","question":"In the climatology of India, the “Loo” is:","options":["A cold wind of the Himalayan foothills in winter","A hot, dry summer wind of the north-west plains","A moist sea breeze blowing along the Konkan coast","A pre-monsoon evening thunderstorm of Bengal"],"answer":1,"explanation":"The Loo blows from the west over Punjab, Haryana, Delhi and western Uttar Pradesh in the afternoons of May–June and can cause sunstroke; Kalbaisakhi is the Bengal thunderstorm.","difficulty":"moderate","source":"SSC CGL · UPSSSC PET","questionHi":"भारत की जलवायु विज्ञान में “लू” क्या है?","optionsHi":["सर्दियों में हिमालय की तलहटी की ठंडी पवन","उत्तर-पश्चिमी मैदानों की गर्म, शुष्क ग्रीष्मकालीन पवन","कोंकण तट के साथ बहने वाली नम समुद्री समीर","बंगाल की मानसून-पूर्व शाम की आँधी-तूफ़ान वाली वर्षा"],"explanationHi":"लू मई-जून की दोपहरों में पंजाब, हरियाणा, दिल्ली और पश्चिमी उत्तर प्रदेश पर पश्चिम से बहती है और लू लगने का कारण बन सकती है; कालबैसाखी बंगाल की आँधी-तूफ़ान वाली वर्षा है।"},
  {"id":"geo-physical-india-40","question":"The pre-monsoon showers of April–May in Karnataka that help the coffee crop flower are locally called:","options":["Mango showers","Cherry blossoms","Blossom showers of Kerala","Kalbaisakhi"],"answer":1,"explanation":"In Karnataka the showers are called cherry blossoms (coffee blossom showers); in Kerala and coastal Karnataka similar showers that ripen mangoes are mango showers.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"कर्नाटक में अप्रैल-मई की मानसून-पूर्व वर्षा, जो कॉफ़ी की फसल में फूल आने में सहायक है, स्थानीय रूप से क्या कहलाती है?","optionsHi":["आम्र वर्षा (मैंगो शावर)","चेरी ब्लॉसम","केरल की पुष्प वर्षा (ब्लॉसम शावर)","कालबैसाखी"],"explanationHi":"कर्नाटक में इस वर्षा को चेरी ब्लॉसम (कॉफ़ी ब्लॉसम वर्षा) कहते हैं; केरल और तटीय कर्नाटक में आमों को पकाने वाली ऐसी ही वर्षा आम्र वर्षा कहलाती है।"},
  {"id":"geo-physical-india-41","question":"Which plateau is called the “Ruhr of India” because of its wealth of coal, iron and other minerals?","options":["Malwa plateau","Chota Nagpur plateau","Bundelkhand plateau","Dandakaranya plateau"],"answer":1,"explanation":"The Chhota Nagpur plateau of Jharkhand holds the Damodar coalfields and the Singhbhum iron belt, like Germany’s Ruhr industrial region.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"कोयले, लोहे और अन्य खनिजों की प्रचुरता के कारण किस पठार को “भारत की रूर” कहा जाता है?","optionsHi":["मालवा पठार","छोटानागपुर पठार","बुंदेलखंड पठार","दंडकारण्य पठार"],"explanationHi":"झारखंड के छोटानागपुर पठार में दामोदर कोयला क्षेत्र और सिंहभूम लौह पट्टी हैं, जैसे जर्मनी का रूर औद्योगिक क्षेत्र।"},
  {"id":"geo-physical-india-42","question":"The Bari Doab of Punjab lies between the rivers:","options":["Beas and Sutlej","Ravi and Chenab","Beas and Ravi","Chenab and Jhelum"],"answer":2,"explanation":"Bari Doab is between the Beas and the Ravi; Bist Doab lies between Beas and Sutlej, Rachna Doab between Ravi and Chenab, and Chaj Doab between Chenab and Jhelum.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"पंजाब का बारी दोआब किन नदियों के बीच स्थित है?","optionsHi":["ब्यास और सतलुज","रावी और चिनाब","ब्यास और रावी","चिनाब और झेलम"],"explanationHi":"बारी दोआब ब्यास और रावी के बीच है; बिस्त दोआब ब्यास और सतलुज के बीच, रचना दोआब रावी और चिनाब के बीच, और चाज दोआब चिनाब और झेलम के बीच है।"},
  {"id":"geo-physical-india-43","question":"The “Duars”, forested plains along the foot of the Himalaya in West Bengal and Assam, correspond to which belt of the northern plains?","options":["Khadar flood plains","Bhangar uplands","Bhabar and Terai","Delta plains"],"answer":2,"explanation":"The Duars (meaning doors, as passes to Bhutan) are the eastern equivalent of the Bhabar–Terai belt, with porous pebbly deposits and marshy jungle used for tea gardens.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"“दुआर”, पश्चिम बंगाल और असम में हिमालय की तलहटी के साथ वनाच्छादित मैदान, उत्तरी मैदानों की किस पट्टी के अनुरूप हैं?","optionsHi":["खादर बाढ़ के मैदान","भांगर उच्चभूमि","भाबर और तराई","डेल्टा के मैदान"],"explanationHi":"दुआर (अर्थात द्वार, क्योंकि ये भूटान के दर्रे हैं) भाबर-तराई पट्टी के पूर्वी समतुल्य हैं, जिनमें सरंध्र कंकड़ीले निक्षेप और दलदली जंगल हैं, जिनका उपयोग चाय बागानों के लिए होता है।"},
  {"id":"geo-physical-india-44","question":"Majuli, the large river island in the Brahmaputra, became India’s first island district in:","options":["2001","2010","2016","2019"],"answer":2,"explanation":"Majuli in Assam, the seat of the neo-Vaishnavite satras founded by Sankardeva, was carved out of Jorhat district as a separate district in September 2016.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"माजुली, ब्रह्मपुत्र का विशाल नदी द्वीप, किस वर्ष भारत का पहला द्वीप ज़िला बना?","optionsHi":["2001","2010","2016","2019"],"explanationHi":"असम का माजुली, जो शंकरदेव द्वारा स्थापित नव-वैष्णव सत्रों का केंद्र है, सितंबर 2016 में जोरहाट ज़िले से अलग कर स्वतंत्र ज़िला बनाया गया।"},
  {"id":"geo-physical-india-45","question":"India’s only confirmed active volcano is located on:","options":["Narcondam Island","Barren Island","Car Nicobar","Great Nicobar"],"answer":1,"explanation":"Barren Island in the Andaman Sea, about 140 km north-east of Port Blair, last erupted in 2017; Narcondam is a dormant volcano.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"भारत का एकमात्र पुष्ट सक्रिय ज्वालामुखी कहाँ स्थित है?","optionsHi":["नारकोंडम द्वीप","बैरन द्वीप","कार निकोबार","ग्रेट निकोबार"],"explanationHi":"अंडमान सागर में पोर्ट ब्लेयर से लगभग 140 किमी उत्तर-पूर्व में स्थित बैरन द्वीप में अंतिम बार 2017 में उद्गार हुआ; नारकोंडम सुप्त ज्वालामुखी है।"},
  {"id":"geo-physical-india-46","question":"The Narmada valley is flanked by two ranges. The range lying immediately SOUTH of the Narmada is the:","options":["Vindhya range","Satpura range","Aravalli range","Maikal range"],"answer":1,"explanation":"The Narmada flows in a rift between the Vindhya to the north and the Satpura to the south; the Maikal hills are the eastern part of the Satpura where Amarkantak lies.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"नर्मदा घाटी दो श्रेणियों से घिरी है। नर्मदा के ठीक दक्षिण में स्थित श्रेणी कौन-सी है?","optionsHi":["विंध्य श्रेणी","सतपुड़ा श्रेणी","अरावली श्रेणी","मैकल श्रेणी"],"explanationHi":"नर्मदा उत्तर में विंध्य और दक्षिण में सतपुड़ा के बीच एक भ्रंश घाटी में बहती है; मैकल पहाड़ियाँ सतपुड़ा का पूर्वी भाग हैं जहाँ अमरकंटक स्थित है।"},
  {"id":"geo-physical-india-47","question":"The “Karewas” of the Kashmir valley, famous for saffron cultivation, are:","options":["Glacial moraines of the Pir Panjal","Old lake-bed (lacustrine) deposits","Volcanic ash beds of the Tertiary","River terraces of the Jhelum"],"answer":1,"explanation":"Karewas are thick deposits laid down in a Pleistocene lake that once filled the Kashmir valley; they support saffron, almond and walnut orchards around Pampore.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कश्मीर घाटी के “करेवा”, जो केसर की खेती के लिए प्रसिद्ध हैं, क्या हैं?","optionsHi":["पीर पंजाल के हिमोढ़","प्राचीन झील-तल (झीलीय) निक्षेप","टर्शियरी काल की ज्वालामुखीय राख की परतें","झेलम की नदी वेदिकाएँ"],"explanationHi":"करेवा प्लायस्टोसीन काल की उस झील में जमा मोटे निक्षेप हैं जो कभी कश्मीर घाटी में भरी थी; ये पंपोर के आसपास केसर, बादाम और अखरोट के बागानों को आधार देते हैं।"},
  {"id":"geo-physical-india-48","question":"Western disturbances that bring winter rain to north-west India originate over the:","options":["Bay of Bengal","Arabian Sea","Mediterranean Sea","Siberian high-pressure area"],"answer":2,"explanation":"These extra-tropical cyclones form over the Mediterranean and travel east in the westerly jet stream, giving light winter rain to Punjab and Haryana that is vital for the rabi wheat crop and snow to the Himalaya.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"उत्तर-पश्चिम भारत में सर्दियों की वर्षा लाने वाले पश्चिमी विक्षोभ कहाँ उत्पन्न होते हैं?","optionsHi":["बंगाल की खाड़ी","अरब सागर","भूमध्य सागर","साइबेरियाई उच्च दाब क्षेत्र"],"explanationHi":"ये बाह्य-उष्णकटिबंधीय चक्रवात भूमध्य सागर पर बनते हैं और पछुआ जेट स्ट्रीम में पूर्व की ओर चलते हैं; ये पंजाब और हरियाणा में हल्की शीतकालीन वर्षा देते हैं जो रबी गेहूँ के लिए महत्वपूर्ण है, और हिमालय में हिमपात।"},
  {"id":"geo-physical-india-49","question":"How many of these statements about the Himalaya are correct? I. The Himadri has an average height of about 6,000 m and a core of Archaean granite. II. The Himachal includes the Pir Panjal, Dhauladhar and Mahabharat ranges. III. The Shiwaliks are made of unconsolidated sediments and contain longitudinal valleys called duns. IV. The Shiwaliks are the outermost range, lying between the Himachal and the plains.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Himadri is the lofty inner range, the Himachal (Lesser Himalaya) includes the Pir Panjal, Dhauladhar and Mahabharat, and the Shiwaliks form the outermost range of loose sediments with duns such as Dehra Dun.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"हिमालय के बारे में इनमें से कितने कथन सही हैं? I. हिमाद्रि की औसत ऊँचाई लगभग 6,000 मीटर है और इसका क्रोड आर्कियन ग्रेनाइट का है। II. हिमाचल में पीर पंजाल, धौलाधार और महाभारत श्रेणियाँ शामिल हैं। III. शिवालिक असंगठित अवसादों से बने हैं और उनमें दून कहलाने वाली अनुदैर्ध्य घाटियाँ हैं। IV. शिवालिक सबसे बाहरी श्रेणी है, जो हिमाचल और मैदानों के बीच स्थित है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। हिमाद्रि ऊँची भीतरी श्रेणी है, हिमाचल (लघु हिमालय) में पीर पंजाल, धौलाधार और महाभारत शामिल हैं, और शिवालिक ढीले अवसादों की सबसे बाहरी श्रेणी है जिसमें देहरादून जैसे दून हैं।"},
  {"id":"geo-physical-india-50","question":"Arrange these plateaus from west to east: 1. Chhota Nagpur plateau 2. Kachchh region 3. Meghalaya plateau 4. Malwa plateau","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"Kachchh (Gujarat), Malwa (Madhya Pradesh), Chhota Nagpur (Jharkhand) and the Meghalaya plateau in the north-east.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इन पठारों को पश्चिम से पूर्व के क्रम में व्यवस्थित कीजिए: 1. छोटानागपुर पठार 2. कच्छ क्षेत्र 3. मेघालय पठार 4. मालवा पठार","optionsHi":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"कच्छ (गुजरात), मालवा (मध्य प्रदेश), छोटानागपुर (झारखंड) और उत्तर-पूर्व में मेघालय पठार।"},
  {"id":"geo-physical-india-51","question":"Which pair of soil and region is NOT correctly matched?","options":["Red soil – Tamil Nadu","Laterite soil – Western Ghats and Meghalaya hills","Black soil – Maharashtra plateau","Saline soil – Himadri range"],"answer":3,"explanation":"Saline (usar) soils occur in arid and poorly drained areas such as western Gujarat, Rajasthan and parts of the Ganga plain, not on the high Himalaya where mountain soils occur.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"मृदा और क्षेत्र का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["लाल मृदा – तमिलनाडु","लेटराइट मृदा – पश्चिमी घाट और मेघालय की पहाड़ियाँ","काली मृदा – महाराष्ट्र पठार","लवणीय मृदा – हिमाद्रि श्रेणी"],"explanationHi":"लवणीय (ऊसर) मृदाएँ पश्चिमी गुजरात, राजस्थान और गंगा मैदान के कुछ भागों जैसे शुष्क और खराब जल निकासी वाले क्षेत्रों में पाई जाती हैं, ऊँचे हिमालय पर नहीं, जहाँ पर्वतीय मृदाएँ पाई जाती हैं।"},
  {"id":"geo-physical-india-52","question":"Assertion (A): Annual rainfall decreases from Kolkata to Delhi along the Ganga plain. Reason (R): The Bay of Bengal branch of the monsoon loses moisture as it moves westward up the valley.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Rainfall falls from about 160 cm at Kolkata to around 65 cm at Delhi because the moisture-laden winds deposit most of their rain in the east before reaching the north-west.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): गंगा के मैदान में कोलकाता से दिल्ली की ओर वार्षिक वर्षा घटती जाती है। कारण (R): मानसून की बंगाल की खाड़ी शाखा घाटी में पश्चिम की ओर बढ़ते हुए नमी खोती जाती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वर्षा कोलकाता में लगभग 160 सेमी से घटकर दिल्ली में लगभग 65 सेमी रह जाती है, क्योंकि नमी से लदी पवनें उत्तर-पश्चिम पहुँचने से पहले अपनी अधिकांश वर्षा पूर्व में ही कर देती हैं।"},
  {"id":"geo-physical-india-53","question":"How many of these statements about India’s coastal plains are correct? I. The western coastal plain is wider than the eastern. II. The eastern coastal plain has the deltas of the Mahanadi, Godavari, Krishna and Kaveri. III. The backwaters of Kerala are called kayals. IV. The Rann of Kachchh lies on the eastern coast.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct. The western coastal plain is narrower than the broad eastern plain, and the Rann of Kachchh is a salt marsh on the western coast of Gujarat, so I and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत के तटीय मैदानों के बारे में इनमें से कितने कथन सही हैं? I. पश्चिमी तटीय मैदान पूर्वी से अधिक चौड़ा है। II. पूर्वी तटीय मैदान में महानदी, गोदावरी, कृष्णा और कावेरी के डेल्टा हैं। III. केरल के पश्चजल (बैकवाटर) कयाल कहलाते हैं। IV. कच्छ का रन पूर्वी तट पर स्थित है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं। पश्चिमी तटीय मैदान चौड़े पूर्वी मैदान से संकरा है, और कच्छ का रन गुजरात के पश्चिमी तट पर एक लवणीय दलदल है, इसलिए I और IV गलत हैं।"},
  {"id":"geo-physical-india-54","question":"How many of these statements about India’s islands are correct? I. The Lakshadweep islands are of coral origin. II. Saddle Peak is the highest point of the Andaman and Nicobar islands. III. Agatti is the capital of Lakshadweep. IV. Great Nicobar lies north of Little Andaman.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Kavaratti is the capital of Lakshadweep (Agatti has its airstrip), and Great Nicobar is the southernmost island of the group, well south of Little Andaman, so III and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत के द्वीपों के बारे में इनमें से कितने कथन सही हैं? I. लक्षद्वीप द्वीप प्रवाल उत्पत्ति के हैं। II. सैडल पीक अंडमान और निकोबार द्वीप समूह का सबसे ऊँचा बिंदु है। III. अगत्ती लक्षद्वीप की राजधानी है। IV. ग्रेट निकोबार लिटिल अंडमान के उत्तर में स्थित है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। कवरत्ती लक्षद्वीप की राजधानी है (अगत्ती में हवाई पट्टी है), और ग्रेट निकोबार समूह का सबसे दक्षिणी द्वीप है, लिटिल अंडमान से काफ़ी दक्षिण में, इसलिए III और IV गलत हैं।"},
  {"id":"geo-physical-india-55","question":"Which of these peaks is NOT located in Uttarakhand?","options":["Nanda Devi","Kedarnath Dome","Trisul","Nanga Parbat"],"answer":3,"explanation":"Nanga Parbat (8,126 m) is at the western end of the Himalaya in Pakistan-administered Gilgit-Baltistan. Nanda Devi, Kedarnath Dome and Trisul all lie in the Garhwal–Kumaon Himalaya of Uttarakhand; do not confuse Nanga Parbat with Nanda Devi.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कौन-सी चोटी उत्तराखंड में स्थित नहीं है?","optionsHi":["नंदा देवी","केदारनाथ डोम","त्रिशूल","नंगा पर्वत"],"explanationHi":"नंगा पर्वत (8,126 मीटर) हिमालय के पश्चिमी छोर पर पाकिस्तान-प्रशासित गिलगित-बल्तिस्तान में है। नंदा देवी, केदारनाथ डोम और त्रिशूल सभी उत्तराखंड के गढ़वाल-कुमाऊँ हिमालय में हैं; नंगा पर्वत को नंदा देवी से भ्रमित न करें।"},
  {"id":"geo-physical-india-56","question":"How many of these statements about India’s climate are correct? I. The Loo is a hot wind of north-west India. II. Mawsynram receives the highest average annual rainfall in India. III. “Break in the monsoon” refers to rainless spells during the rainy season. IV. The retreating monsoon gives Punjab its heaviest rain of the year.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The retreating (north-east) monsoon brings rain mainly to Tamil Nadu and the Coromandel coast; Punjab’s rain comes from the south-west monsoon and western disturbances.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत की जलवायु के बारे में इनमें से कितने कथन सही हैं? I. लू उत्तर-पश्चिम भारत की गर्म पवन है। II. मौसिनराम में भारत की सर्वाधिक औसत वार्षिक वर्षा होती है। III. “मानसून में विराम” का अर्थ वर्षा ऋतु के दौरान वर्षा रहित अवधियों से है। IV. लौटता मानसून पंजाब को वर्ष की सबसे भारी वर्षा देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। लौटता (उत्तर-पूर्वी) मानसून मुख्यतः तमिलनाडु और कोरोमंडल तट पर वर्षा लाता है; पंजाब की वर्षा दक्षिण-पश्चिम मानसून और पश्चिमी विक्षोभों से आती है।"},
  {"id":"geo-physical-india-57","question":"Assertion (A): Peninsular rivers are not navigable over long stretches. Reason (R): They flow over a hard rocky plateau with a seasonal regime and have rapids and waterfalls along their courses.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Unlike the perennial, gentle-gradient Himalayan rivers, the peninsular rivers are rain-fed, shallow in summer and broken by falls like Jog and Dhuandhar, which prevents navigation.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): प्रायद्वीपीय नदियाँ लंबी दूरी तक नौगम्य नहीं हैं। कारण (R): वे कठोर चट्टानी पठार पर मौसमी प्रवाह के साथ बहती हैं और उनके मार्ग में जलप्रपात तथा तीव्र धाराएँ हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बारहमासी, मंद ढाल वाली हिमालयी नदियों के विपरीत, प्रायद्वीपीय नदियाँ वर्षा-पोषित हैं, गर्मियों में उथली रहती हैं और जोग तथा धुआँधार जैसे जलप्रपातों से टूटी हुई हैं, जो नौगम्यता को रोकते हैं।"},
  {"id":"geo-physical-india-58","question":"Which pair of mountain pass and state or Union Territory is NOT correctly matched?","options":["Bomdila – Arunachal Pradesh","Jelep La – Sikkim","Rohtang – Himachal Pradesh","Banihal – Uttarakhand"],"answer":3,"explanation":"Banihal pass, through which the Jammu–Srinagar road and the Jawahar tunnel run, is in Jammu and Kashmir, across the Pir Panjal range.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"पर्वतीय दर्रे और राज्य या केंद्रशासित प्रदेश का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["बोमडिला – अरुणाचल प्रदेश","जेलेप ला – सिक्किम","रोहतांग – हिमाचल प्रदेश","बनिहाल – उत्तराखंड"],"explanationHi":"बनिहाल दर्रा, जिससे होकर जम्मू-श्रीनगर सड़क और जवाहर सुरंग गुज़रती हैं, पीर पंजाल श्रेणी में जम्मू और कश्मीर में है।"},
  {"id":"geo-physical-india-59","question":"Arrange these physiographic units in order of their geological formation, oldest first: 1. Himalaya 2. Deccan Trap 3. Aravalli 4. Indo-Gangetic plain","options":["3, 2, 1, 4","3, 1, 2, 4","2, 3, 1, 4","3, 2, 4, 1"],"answer":0,"explanation":"The Aravalli is Precambrian; the Deccan Trap lavas erupted at the end of the Cretaceous (about 66 million years ago); the Himalaya rose in the Tertiary; and the plains were filled by Quaternary alluvium.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन भौतिक इकाइयों को उनके भूवैज्ञानिक निर्माण के क्रम में, सबसे पुरानी पहले, व्यवस्थित कीजिए: 1. हिमालय 2. दक्कन ट्रैप 3. अरावली 4. सिंधु-गंगा का मैदान","optionsHi":["3, 2, 1, 4","3, 1, 2, 4","2, 3, 1, 4","3, 2, 4, 1"],"explanationHi":"अरावली प्रीकैम्ब्रियन है; दक्कन ट्रैप के लावा क्रिटेशियस के अंत में (लगभग 6.6 करोड़ वर्ष पूर्व) निकले; हिमालय टर्शियरी में उठा; और मैदान क्वाटरनरी जलोढ़ से भरे।"},
  {"id":"geo-physical-india-60","question":"How many of these statements about the peninsular plateau are correct? I. The Malwa plateau lies between the Aravalli and the Vindhya. II. The Chhota Nagpur plateau is drained by the Damodar. III. The Deccan Trap covers most of Maharashtra and parts of Gujarat and Madhya Pradesh. IV. The Meghalaya plateau is a detached part of the peninsular block, separated by the Garo–Rajmahal gap.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The Rajmahal–Garo gap, filled with Ganga–Brahmaputra alluvium, separates the Shillong plateau from the main peninsular block.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"प्रायद्वीपीय पठार के बारे में इनमें से कितने कथन सही हैं? I. मालवा पठार अरावली और विंध्य के बीच स्थित है। II. छोटानागपुर पठार का अपवाह दामोदर से होता है। III. दक्कन ट्रैप महाराष्ट्र के अधिकांश भाग तथा गुजरात और मध्य प्रदेश के कुछ भागों में फैला है। IV. मेघालय पठार प्रायद्वीपीय खंड का एक अलग हुआ भाग है, जो गारो-राजमहल गैप द्वारा पृथक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। गंगा-ब्रह्मपुत्र जलोढ़ से भरा राजमहल-गारो गैप शिलांग पठार को मुख्य प्रायद्वीपीय खंड से अलग करता है।"},
  {"id":"geo-physical-india-61","question":"Which is the largest state of India by area?","options":["Madhya Pradesh","Maharashtra","Rajasthan","Uttar Pradesh"],"answer":2,"explanation":"Rajasthan, at about 3.42 lakh km², is the largest state, followed by Madhya Pradesh and Maharashtra.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"क्षेत्रफल की दृष्टि से भारत का सबसे बड़ा राज्य कौन-सा है?","optionsHi":["मध्य प्रदेश","महाराष्ट्र","राजस्थान","उत्तर प्रदेश"],"explanationHi":"राजस्थान, लगभग 3.42 लाख वर्ग किमी के साथ, सबसे बड़ा राज्य है, उसके बाद मध्य प्रदेश और महाराष्ट्र आते हैं।"},
  {"id":"geo-physical-india-62","question":"“Sahyadri” is another name for the:","options":["Western Ghats","Eastern Ghats","Satpura range","Aravalli range"],"answer":0,"explanation":"The Western Ghats are called the Sahyadri, especially in Maharashtra and Karnataka.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"“सह्याद्रि” किसका दूसरा नाम है?","optionsHi":["पश्चिमी घाट","पूर्वी घाट","सतपुड़ा श्रेणी","अरावली श्रेणी"],"explanationHi":"पश्चिमी घाट को, विशेषकर महाराष्ट्र और कर्नाटक में, सह्याद्रि कहा जाता है।"},
  {"id":"geo-physical-india-63","question":"The Palghat (Palakkad) gap, a major break in the Western Ghats, links:","options":["Goa and Karnataka","Kerala and Tamil Nadu","Maharashtra and Karnataka","Karnataka and Tamil Nadu"],"answer":1,"explanation":"The Palakkad gap, between the Nilgiris and the Anaimalai hills, carries the road and rail link between Kerala and Tamil Nadu and lets moist winds pass inland.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"पालघाट (पालक्काड) दर्रा, पश्चिमी घाट में एक प्रमुख अंतराल, किन्हें जोड़ता है?","optionsHi":["गोवा और कर्नाटक","केरल और तमिलनाडु","महाराष्ट्र और कर्नाटक","कर्नाटक और तमिलनाडु"],"explanationHi":"नीलगिरि और अनाईमलाई पहाड़ियों के बीच का पालक्काड दर्रा केरल और तमिलनाडु के बीच सड़क और रेल संपर्क देता है और नम पवनों को अंदर आने देता है।"},
  {"id":"geo-physical-india-64","question":"Loktak lake, known for its floating masses of vegetation called phumdis, is in:","options":["Assam","Mizoram","Tripura","Manipur"],"answer":3,"explanation":"Loktak in Manipur has phumdis; the largest, Keibul Lamjao, is the world’s only floating national park and home of the sangai deer.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"लोकटक झील, जो फुमदी कहलाने वाली तैरती वनस्पति की परतों के लिए जानी जाती है, कहाँ स्थित है?","optionsHi":["असम","मिज़ोरम","त्रिपुरा","मणिपुर"],"explanationHi":"मणिपुर की लोकटक में फुमदी हैं; सबसे बड़ी, केइबुल लामजाओ, विश्व का एकमात्र तैरता राष्ट्रीय उद्यान है और संगाई हिरण का घर है।"},
  {"id":"geo-physical-india-65","question":"The Duncan Passage separates:","options":["South Andaman from Little Andaman","Little Andaman from Car Nicobar","Great Nicobar from Little Nicobar","Lakshadweep from Minicoy"],"answer":0,"explanation":"Duncan Passage lies between South Andaman and Little Andaman. The Ten Degree Channel separates Little Andaman from Car Nicobar and the Sombrero Channel lies between Little and Great Nicobar.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"डंकन पैसेज किन्हें अलग करता है?","optionsHi":["दक्षिण अंडमान को लिटिल अंडमान से","लिटिल अंडमान को कार निकोबार से","ग्रेट निकोबार को लिटिल निकोबार से","लक्षद्वीप को मिनिकॉय से"],"explanationHi":"डंकन पैसेज दक्षिण अंडमान और लिटिल अंडमान के बीच है। टेन डिग्री चैनल लिटिल अंडमान को कार निकोबार से अलग करता है और सोम्ब्रेरो चैनल लिटिल और ग्रेट निकोबार के बीच है।"},
  {"id":"geo-physical-india-66","question":"The Cardamom Hills, at the southern end of the Western Ghats, lie mainly in:","options":["Karnataka","Kerala","Goa","Andhra Pradesh"],"answer":1,"explanation":"The Cardamom Hills lie in Kerala along its border with Tamil Nadu, south of the Anaimalai hills; they are named after the spice grown there.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कार्डमम (इलायची) पहाड़ियाँ, जो पश्चिमी घाट के दक्षिणी छोर पर हैं, मुख्यतः कहाँ स्थित हैं?","optionsHi":["कर्नाटक","केरल","गोवा","आंध्र प्रदेश"],"explanationHi":"इलायची की पहाड़ियाँ केरल में तमिलनाडु सीमा के साथ, अनाईमलाई पहाड़ियों के दक्षिण में हैं; इनका नाम वहाँ उगने वाले मसाले पर पड़ा है।"},
  {"id":"geo-physical-india-67","question":"The pre-monsoon showers in Kerala and coastal Karnataka that help the early ripening of mangoes are called:","options":["Kalbaisakhi","Loo","Mango showers","Cherry blossoms"],"answer":2,"explanation":"Mango showers fall in April–May in Kerala and coastal Karnataka. Cherry blossoms aid coffee in Karnataka; Kalbaisakhi are Bengal’s nor’westers.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"केरल और तटीय कर्नाटक की मानसून-पूर्व वर्षा, जो आमों के जल्दी पकने में सहायक है, क्या कहलाती है?","optionsHi":["कालबैसाखी","लू","आम्र वर्षा (मैंगो शावर)","चेरी ब्लॉसम"],"explanationHi":"आम्र वर्षा केरल और तटीय कर्नाटक में अप्रैल-मई में होती है। चेरी ब्लॉसम कर्नाटक में कॉफ़ी की सहायक है; कालबैसाखी बंगाल की नॉरवेस्टर आँधियाँ हैं।"},
  {"id":"geo-physical-india-68","question":"The violent evening thunderstorms of the pre-monsoon season are called “Bardoli Chheerha” in:","options":["Assam","Odisha","Gujarat","Bihar"],"answer":0,"explanation":"In Assam the nor’westers are known as Bardoli Chheerha and help tea cultivation. In West Bengal they are Kalbaisakhi.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"मानसून-पूर्व ऋतु की तेज़ शाम की आँधी-तूफ़ान वाली वर्षा किस राज्य में “बारदोलि छीड़ा” कहलाती है?","optionsHi":["असम","ओडिशा","गुजरात","बिहार"],"explanationHi":"असम में नॉरवेस्टर को बारदोलि छीड़ा कहा जाता है और ये चाय की खेती में सहायक हैं। पश्चिम बंगाल में इन्हें कालबैसाखी कहते हैं।"},
  {"id":"geo-physical-india-69","question":"The stunted evergreen “shola” forests, surrounded by grasslands, are found at high altitudes in the:","options":["Aravalli range of Rajasthan","Shiwalik hills of Himachal","Satpura and Maikal ranges","Nilgiri and Anaimalai hills"],"answer":3,"explanation":"Sholas are montane evergreen forests of the southern Western Ghats above about 1,500 m, alternating with grasslands.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"बौने सदाबहार “शोला” वन, जो घास के मैदानों से घिरे होते हैं, कहाँ ऊँचाई पर पाए जाते हैं?","optionsHi":["राजस्थान की अरावली श्रेणी","हिमाचल की शिवालिक पहाड़ियाँ","सतपुड़ा और मैकल श्रेणियाँ","नीलगिरि और अनाईमलाई पहाड़ियाँ"],"explanationHi":"शोला दक्षिणी पश्चिमी घाट में लगभग 1,500 मीटर से ऊपर के पर्वतीय सदाबहार वन हैं, जो घास के मैदानों के साथ बारी-बारी से मिलते हैं।"},
  {"id":"geo-physical-india-70","question":"Dhupgarh, near Pachmarhi, is the highest peak of the:","options":["Vindhya range","Satpura range","Maikal range","Aravalli range"],"answer":1,"explanation":"Dhupgarh (about 1,350 m) in the Mahadeo hills of Madhya Pradesh is the highest point of the Satpura range.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पचमढ़ी के निकट धूपगढ़ किस श्रेणी की सबसे ऊँची चोटी है?","optionsHi":["विंध्य श्रेणी","सतपुड़ा श्रेणी","मैकल श्रेणी","अरावली श्रेणी"],"explanationHi":"मध्य प्रदेश की महादेव पहाड़ियों में स्थित धूपगढ़ (लगभग 1,350 मीटर) सतपुड़ा श्रेणी का सबसे ऊँचा बिंदु है।"},
  {"id":"geo-physical-india-71","question":"Narcondam, an island in the Andaman Sea classified as a dormant volcano, lies:","options":["North-east of the Andaman islands","South of Great Nicobar in the open sea","Near Lakshadweep in the Arabian Sea","In the Gulf of Mannar off Tamil Nadu"],"answer":0,"explanation":"Narcondam lies north-east of the Andamans; Barren Island to its south is India’s only active volcano.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"नारकोंडम, अंडमान सागर का एक द्वीप जिसे सुप्त ज्वालामुखी के रूप में वर्गीकृत किया गया है, कहाँ स्थित है?","optionsHi":["अंडमान द्वीप समूह के उत्तर-पूर्व में","खुले समुद्र में ग्रेट निकोबार के दक्षिण में","अरब सागर में लक्षद्वीप के निकट","तमिलनाडु के तट के पास मन्नार की खाड़ी में"],"explanationHi":"नारकोंडम अंडमान के उत्तर-पूर्व में है; उसके दक्षिण में बैरन द्वीप भारत का एकमात्र सक्रिय ज्वालामुखी है।"},
  {"id":"geo-physical-india-72","question":"The Siachen glacier lies in which mountain range?","options":["Pir Panjal","Zaskar","Ladakh","Karakoram"],"answer":3,"explanation":"Siachen lies in the eastern Karakoram, between the Saltoro ridge and the main Karakoram ridge; it is one of the longest non-polar glaciers.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सियाचिन हिमनद किस पर्वत श्रेणी में स्थित है?","optionsHi":["पीर पंजाल","ज़ास्कर","लद्दाख","काराकोरम"],"explanationHi":"सियाचिन पूर्वी काराकोरम में, सालतोरो कटक और मुख्य काराकोरम कटक के बीच स्थित है; यह सबसे लंबे गैर-ध्रुवीय हिमनदों में से एक है।"},
  {"id":"geo-physical-india-73","question":"Most of India’s coal reserves occur in rocks of the:","options":["Dharwar system","Gondwana system","Cuddapah system","Tertiary system"],"answer":1,"explanation":"About 98% of Indian coal is in Gondwana rocks of the Damodar, Mahanadi, Godavari and Son valleys. Tertiary coal (lignite) is found in the north-east, Tamil Nadu and Rajasthan.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत के कोयले के अधिकांश भंडार किन चट्टानों में पाए जाते हैं?","optionsHi":["धारवाड़ क्रम","गोंडवाना क्रम","कुड्डापा क्रम","टर्शियरी क्रम"],"explanationHi":"भारतीय कोयले का लगभग 98% दामोदर, महानदी, गोदावरी और सोन घाटियों की गोंडवाना चट्टानों में है। टर्शियरी कोयला (लिग्नाइट) उत्तर-पूर्व, तमिलनाडु और राजस्थान में मिलता है।"},
  {"id":"geo-physical-india-74","question":"The Nine Degree Channel separates:","options":["Andaman from the Nicobar islands","Minicoy from the Maldives","Lakshadweep group from Minicoy","Mainland India from Sri Lanka"],"answer":2,"explanation":"The Nine Degree Channel lies between the main Lakshadweep group and Minicoy; the Eight Degree Channel separates Minicoy from the Maldives.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"नाइन डिग्री चैनल किन्हें अलग करता है?","optionsHi":["अंडमान को निकोबार द्वीप समूह से","मिनिकॉय को मालदीव से","लक्षद्वीप समूह को मिनिकॉय से","मुख्य भूमि भारत को श्रीलंका से"],"explanationHi":"नाइन डिग्री चैनल मुख्य लक्षद्वीप समूह और मिनिकॉय के बीच है; एट डिग्री चैनल मिनिकॉय को मालदीव से अलग करता है।"},
  {"id":"geo-physical-india-75","question":"How many of these statements about India’s location are correct? I. The mainland extends from about 8°4′ N to 37°6′ N. II. The Tropic of Cancer divides the country into two roughly equal halves. III. The east–west extent of about 30° of longitude gives a time difference of about two hours between Arunachal Pradesh and Gujarat. IV. Indira Point lies at about 6°45′ N.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Each degree of longitude equals 4 minutes of time, so 30° gives about 2 hours, which is why a single standard meridian (82°30′ E) is used.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत की अवस्थिति के बारे में इनमें से कितने कथन सही हैं? I. मुख्य भूमि लगभग 8°4′ उ. से 37°6′ उ. तक फैली है। II. कर्क रेखा देश को लगभग दो बराबर भागों में बाँटती है। III. लगभग 30° देशांतर के पूर्व-पश्चिम विस्तार से अरुणाचल प्रदेश और गुजरात के बीच लगभग दो घंटे का समय अंतर आता है। IV. इंदिरा प्वाइंट लगभग 6°45′ उ. पर स्थित है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। प्रत्येक देशांतर अंश 4 मिनट के समय के बराबर है, इसलिए 30° से लगभग 2 घंटे बनते हैं, इसी कारण एकल मानक याम्योत्तर (82°30′ पू.) का उपयोग किया जाता है।"},
  {"id":"geo-physical-india-76","question":"Match the pass with its State: A. Bomdi La B. Jelep La C. Rohtang D. Mana. 1. Uttarakhand 2. Himachal Pradesh 3. Sikkim 4. Arunachal Pradesh","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Bomdi La is in Arunachal Pradesh, Jelep La in Sikkim (to the Chumbi valley), Rohtang in Himachal Pradesh (Kullu–Lahaul) and Mana in Uttarakhand (to Tibet).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"दर्रे का मिलान उसके राज्य से कीजिए: A. बोमडी ला B. जेलेप ला C. रोहतांग D. माणा। 1. उत्तराखंड 2. हिमाचल प्रदेश 3. सिक्किम 4. अरुणाचल प्रदेश","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"बोमडी ला अरुणाचल प्रदेश में, जेलेप ला सिक्किम में (चुंबी घाटी की ओर), रोहतांग हिमाचल प्रदेश में (कुल्लू-लाहौल) और माणा उत्तराखंड में (तिब्बत की ओर) है।"},
  {"id":"geo-physical-india-77","question":"Arrange these peaks in descending order of height: 1. Nanda Devi 2. Kangchenjunga 3. Kamet 4. K2","options":["2, 4, 1, 3","4, 2, 3, 1","4, 2, 1, 3","4, 1, 2, 3"],"answer":2,"explanation":"K2 (8,611 m), Kangchenjunga (8,586 m), Nanda Devi (7,816 m), Kamet (7,756 m).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन चोटियों को ऊँचाई के घटते क्रम में व्यवस्थित कीजिए: 1. नंदा देवी 2. कंचनजंघा 3. कामेट 4. K2","optionsHi":["2, 4, 1, 3","4, 2, 3, 1","4, 2, 1, 3","4, 1, 2, 3"],"explanationHi":"K2 (8,611 मीटर), कंचनजंघा (8,586 मीटर), नंदा देवी (7,816 मीटर), कामेट (7,756 मीटर)।"},
  {"id":"geo-physical-india-78","question":"Assertion (A): The Thar region receives very little rain from the Arabian Sea branch of the south-west monsoon. Reason (R): The Aravalli range lies parallel to the direction of these winds and so fails to obstruct and lift them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Because the Aravallis run south-west to north-east, the moist winds pass along them without forced ascent, leaving western Rajasthan dry.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): थार क्षेत्र को दक्षिण-पश्चिम मानसून की अरब सागर शाखा से बहुत कम वर्षा मिलती है। कारण (R): अरावली श्रेणी इन पवनों की दिशा के समानांतर स्थित है, इसलिए उन्हें रोकने और ऊपर उठाने में विफल रहती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। चूँकि अरावली दक्षिण-पश्चिम से उत्तर-पूर्व की ओर फैली है, नम पवनें उसके साथ-साथ बिना बलपूर्वक ऊपर उठे निकल जाती हैं, जिससे पश्चिमी राजस्थान शुष्क रह जाता है।"},
  {"id":"geo-physical-india-79","question":"How many of these statements about India’s natural vegetation are correct? I. Tropical evergreen forests occur in the Western Ghats and the north-east. II. Tropical evergreen forests are the most widespread forests of India. III. Mangroves grow in the deltas of the east coast and in the Sundarbans. IV. Thorn forests are typical of the plains of Kerala.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. The tropical deciduous (monsoon) forests, not the evergreen ones, are the most widespread in India, and thorn forests grow in dry areas such as Rajasthan and Gujarat, not rainy Kerala.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत की प्राकृतिक वनस्पति के बारे में इनमें से कितने कथन सही हैं? I. उष्णकटिबंधीय सदाबहार वन पश्चिमी घाट और उत्तर-पूर्व में पाए जाते हैं। II. उष्णकटिबंधीय सदाबहार वन भारत के सबसे व्यापक वन हैं। III. मैंग्रोव पूर्वी तट के डेल्टाओं और सुंदरबन में उगते हैं। IV. कँटीले वन केरल के मैदानों की विशेषता हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। भारत में सबसे व्यापक वन उष्णकटिबंधीय पर्णपाती (मानसूनी) वन हैं, सदाबहार नहीं, और कँटीले वन राजस्थान और गुजरात जैसे शुष्क क्षेत्रों में उगते हैं, वर्षा वाले केरल में नहीं।"},
  {"id":"geo-physical-india-80","question":"Arrange these lakes from north to south: 1. Chilika 2. Vembanad 3. Sambhar 4. Wular","options":["4, 3, 2, 1","3, 4, 1, 2","4, 1, 3, 2","4, 3, 1, 2"],"answer":3,"explanation":"Wular (Kashmir, about 34° N), Sambhar (Rajasthan, about 27° N), Chilika (Odisha, about 19.7° N), Vembanad (Kerala, about 9.6° N).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इन झीलों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए: 1. चिल्का 2. वेम्बनाड 3. सांभर 4. वूलर","optionsHi":["4, 3, 2, 1","3, 4, 1, 2","4, 1, 3, 2","4, 3, 1, 2"],"explanationHi":"वूलर (कश्मीर, लगभग 34° उ.), सांभर (राजस्थान, लगभग 27° उ.), चिल्का (ओडिशा, लगभग 19.7° उ.), वेम्बनाड (केरल, लगभग 9.6° उ.)।"},
  {"id":"geo-physical-india-81","question":"Which of these ranges is NOT part of the Trans-Himalaya?","options":["Karakoram","Ladakh","Kailash","Pir Panjal"],"answer":3,"explanation":"The Pir Panjal belongs to the Lesser Himalaya (Himachal). The Karakoram, Ladakh and Kailash ranges lie north of the Great Himalaya and form the Trans-Himalaya.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सी श्रेणी ट्रांस-हिमालय का भाग नहीं है?","optionsHi":["काराकोरम","लद्दाख","कैलाश","पीर पंजाल"],"explanationHi":"पीर पंजाल लघु हिमालय (हिमाचल) का भाग है। काराकोरम, लद्दाख और कैलाश श्रेणियाँ वृहत् हिमालय के उत्तर में हैं और ट्रांस-हिमालय बनाती हैं।"},
  {"id":"geo-physical-india-82","question":"How many of these statements about the Indian monsoon are correct? I. The northward shift of the ITCZ in summer helps draw in the south-west monsoon. II. Intense summer heating of the Tibetan plateau strengthens the monsoon circulation. III. The Somali jet off East Africa strengthens the monsoon flow. IV. An El Niño year is often associated with below-normal monsoon rainfall in India.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The shifting ITCZ, the heated Tibetan plateau and the Somali jet all aid the south-west monsoon, while El Niño (warming of the eastern Pacific) is usually linked to weak monsoons and droughts in India.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारतीय मानसून के बारे में इनमें से कितने कथन सही हैं? I. गर्मियों में ITCZ का उत्तर की ओर खिसकना दक्षिण-पश्चिम मानसून को खींचने में सहायक है। II. तिब्बत के पठार का ग्रीष्मकालीन तीव्र तापन मानसून परिसंचरण को सुदृढ़ करता है। III. पूर्वी अफ़्रीका के तट पर सोमाली जेट मानसूनी प्रवाह को सुदृढ़ करती है। IV. एल निनो वर्ष प्रायः भारत में सामान्य से कम मानसूनी वर्षा से जुड़ा होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। खिसकता ITCZ, तपता तिब्बती पठार और सोमाली जेट सभी दक्षिण-पश्चिम मानसून की सहायता करते हैं, जबकि एल निनो (पूर्वी प्रशांत का गर्म होना) प्रायः भारत में कमज़ोर मानसून और सूखे से जुड़ा होता है।"},
  {"id":"geo-physical-india-83","question":"Match the term with its description: A. Bhabar B. Terai C. Bhangar D. Khadar. 1. Older alluvium lying above flood level 2. Newer alluvium of the flood plains, renewed each year 3. Porous belt of pebbles where streams sink underground 4. Marshy, forested zone where streams re-emerge","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"answer":2,"explanation":"Bhabar is the pebble belt at the foot of the Shiwaliks; the Terai lies south of it where water re-emerges; Bhangar is older alluvium with kankar; Khadar is the fertile new alluvium of flood plains.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"शब्द का मिलान उसके विवरण से कीजिए: A. भाबर B. तराई C. भांगर D. खादर। 1. बाढ़ स्तर से ऊपर स्थित पुराना जलोढ़ 2. बाढ़ के मैदानों का नया जलोढ़, जो हर वर्ष नवीनीकृत होता है 3. कंकड़ों की सरंध्र पट्टी जहाँ धाराएँ भूमिगत हो जाती हैं 4. दलदली, वनाच्छादित क्षेत्र जहाँ धाराएँ पुनः प्रकट होती हैं","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"explanationHi":"भाबर शिवालिक की तलहटी की कंकड़ पट्टी है; तराई उसके दक्षिण में है जहाँ जल पुनः प्रकट होता है; भांगर कंकड़ युक्त पुराना जलोढ़ है; खादर बाढ़ के मैदानों का उपजाऊ नया जलोढ़ है।"},
  {"id":"geo-physical-india-84","question":"Assertion (A): Leh receives very little rainfall during the south-west monsoon. Reason (R): It lies in the rain shadow of the Great Himalaya, which block the moist monsoon winds.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. The Great Himalaya wring out the monsoon moisture on their southern slopes, leaving Ladakh a cold desert.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): दक्षिण-पश्चिम मानसून के दौरान लेह में बहुत कम वर्षा होती है। कारण (R): यह वृहत् हिमालय के वृष्टि छाया क्षेत्र में स्थित है, जो नम मानसूनी पवनों को रोकता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। वृहत् हिमालय मानसून की नमी अपनी दक्षिणी ढलानों पर निचोड़ लेता है, जिससे लद्दाख शीत मरुस्थल बन जाता है।"},
  {"id":"geo-physical-india-85","question":"How many of these statements are correct? I. Among the States, Gujarat has the longest coastline. II. India’s longest land boundary is with Bangladesh. III. India’s shortest land boundary is with Afghanistan. IV. Sikkim shares borders with Nepal, Bhutan and China.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The India–Bangladesh border is about 4,096 km; the boundary with Afghanistan, about 106 km, runs through the Pakistan-occupied part of Jammu and Kashmir.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. राज्यों में गुजरात की तटरेखा सबसे लंबी है। II. भारत की सबसे लंबी भू-सीमा बांग्लादेश के साथ है। III. भारत की सबसे छोटी भू-सीमा अफ़ग़ानिस्तान के साथ है। IV. सिक्किम की सीमाएँ नेपाल, भूटान और चीन से लगती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। भारत-बांग्लादेश सीमा लगभग 4,096 किमी है; अफ़ग़ानिस्तान के साथ लगभग 106 किमी की सीमा जम्मू और कश्मीर के पाकिस्तान-अधिकृत भाग से होकर जाती है।"},
  {"id":"geo-physical-india-86","question":"By area, India ranks in the world as the:","options":["5th largest country","7th largest country","6th largest country","9th largest country"],"answer":1,"explanation":"With about 3.28 million sq km, roughly 2.4% of the world's land area, India is the seventh largest country, after Russia, Canada, the USA, China, Brazil and Australia.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"क्षेत्रफल के अनुसार विश्व में भारत का स्थान क्या है?","optionsHi":["5वाँ सबसे बड़ा देश","7वाँ सबसे बड़ा देश","छठा सबसे बड़ा देश","9वाँ सबसे बड़ा देश"],"explanationHi":"लगभग 32.8 लाख वर्ग किमी के साथ, जो विश्व के भूभाग का लगभग 2.4% है, भारत रूस, कनाडा, अमेरिका, चीन, ब्राज़ील और ऑस्ट्रेलिया के बाद सातवाँ सबसे बड़ा देश है।"},
  {"id":"geo-physical-india-87","question":"The Rann of Kachchh, a vast salt marsh, lies in the State of:","options":["Rajasthan","Maharashtra","Haryana","Gujarat"],"answer":3,"explanation":"The Great and Little Rann of Kachchh are in Gujarat. They flood in the monsoon and dry into salt flats, and they are home to the Indian wild ass.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कच्छ का रन, एक विशाल लवणीय दलदल, किस राज्य में स्थित है?","optionsHi":["राजस्थान","महाराष्ट्र","हरियाणा","गुजरात"],"explanationHi":"कच्छ का बड़ा और छोटा रन गुजरात में हैं। मानसून में ये जलमग्न हो जाते हैं और सूखकर नमक के मैदान बन जाते हैं, तथा भारतीय जंगली गधे का आवास हैं।"},
  {"id":"geo-physical-india-88","question":"The Deccan Traps are made up mainly of:","options":["Granite","Basalt","Sandstone","Limestone"],"answer":1,"explanation":"The Deccan Traps formed from fissure eruptions of lava at the end of the Cretaceous period. As the basalt weathers it gives the black (regur) soil of the Deccan.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"दक्कन ट्रैप मुख्यतः किससे बने हैं?","optionsHi":["ग्रेनाइट","बेसाल्ट","बलुआ पत्थर","चूना पत्थर"],"explanationHi":"दक्कन ट्रैप क्रिटेशियस काल के अंत में लावा के दरारी उद्गारों से बने। बेसाल्ट के अपक्षय से दक्कन की काली (रेगुर) मृदा बनती है।"},
  {"id":"geo-physical-india-89","question":"Saramati, the highest peak of the Naga hills, lies in which State?","options":["Manipur","Nagaland","Mizoram","Arunachal Pradesh"],"answer":1,"explanation":"Saramati (about 3,826 m) is on the Nagaland–Myanmar border. Phawngpui (Blue Mountain) is the highest peak of Mizoram.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"सारामती, नागा पहाड़ियों की सबसे ऊँची चोटी, किस राज्य में स्थित है?","optionsHi":["मणिपुर","नागालैंड","मिज़ोरम","अरुणाचल प्रदेश"],"explanationHi":"सारामती (लगभग 3,826 मीटर) नागालैंड-म्यांमार सीमा पर है। फौंगपुई (ब्लू माउंटेन) मिज़ोरम की सबसे ऊँची चोटी है।"},
  {"id":"geo-physical-india-90","question":"Mullayanagiri, in the Baba Budan hills of Chikkamagaluru, is the highest peak of:","options":["Karnataka","Kerala","Goa","Tamil Nadu"],"answer":0,"explanation":"Mullayanagiri (about 1,930 m) is Karnataka's highest peak. Kerala's is Anamudi, Tamil Nadu's Doddabetta, and Maharashtra's Kalsubai.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"चिक्कमगलूरु की बाबा बूदन पहाड़ियों में स्थित मुल्लयनगिरि किसकी सबसे ऊँची चोटी है?","optionsHi":["कर्नाटक","केरल","गोवा","तमिलनाडु"],"explanationHi":"मुल्लयनगिरि (लगभग 1,930 मीटर) कर्नाटक की सबसे ऊँची चोटी है। केरल की अनामुडी, तमिलनाडु की डोडाबेट्टा और महाराष्ट्र की कलसुबाई है।"},
  {"id":"geo-physical-india-91","question":"The Kaimur hills, in Madhya Pradesh, Uttar Pradesh and Bihar, are the eastern extension of the:","options":["Satpura range","Aravalli range","Maikal range","Vindhya range"],"answer":3,"explanation":"The Vindhyas continue east as the Kaimur hills, which overlook the Son valley. The Satpura's eastern end is the Maikal range around Amarkantak.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"मध्य प्रदेश, उत्तर प्रदेश और बिहार में फैली कैमूर पहाड़ियाँ किसका पूर्वी विस्तार हैं?","optionsHi":["सतपुड़ा श्रेणी","अरावली श्रेणी","मैकल श्रेणी","विंध्य श्रेणी"],"explanationHi":"विंध्य पूर्व में कैमूर पहाड़ियों के रूप में जारी रहता है, जो सोन घाटी के ऊपर स्थित हैं। सतपुड़ा का पूर्वी छोर अमरकंटक के आसपास की मैकल श्रेणी है।"},
  {"id":"geo-physical-india-92","question":"The \"Northern Circars\" is the name given to the:","options":["Northern part of the eastern coastal plain","Coastal plain of Gujarat and Kathiawar","Northern part of the western coastal plain","Alluvial plains of north Bihar"],"answer":0,"explanation":"The eastern coastal plain is divided into the Northern Circars (Odisha and Andhra coast) in the north and the Coromandel coast (Tamil Nadu) in the south. On the west coast the divisions are Kachchh–Kathiawar, Konkan, Kanara and Malabar.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"“उत्तरी सरकार” किसे दिया गया नाम है?","optionsHi":["पूर्वी तटीय मैदान का उत्तरी भाग","गुजरात और काठियावाड़ का तटीय मैदान","पश्चिमी तटीय मैदान का उत्तरी भाग","उत्तरी बिहार के जलोढ़ मैदान"],"explanationHi":"पूर्वी तटीय मैदान उत्तर में उत्तरी सरकार (ओडिशा और आंध्र तट) और दक्षिण में कोरोमंडल तट (तमिलनाडु) में विभाजित है। पश्चिमी तट पर विभाजन कच्छ-काठियावाड़, कोंकण, कनारा और मालाबार हैं।"},
  {"id":"geo-physical-india-93","question":"Khardung La, one of the highest motorable passes, connects Leh with the Nubra and Shyok valleys. It lies in:","options":["Himachal Pradesh","Ladakh","Sikkim","Uttarakhand"],"answer":1,"explanation":"Khardung La (about 5,359 m) is in the Ladakh range north of Leh. It is the route to the Nubra valley and on to the Siachen region.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"खारदुंग ला, सबसे ऊँचे मोटर-योग्य दर्रों में से एक, लेह को नुब्रा और श्योक घाटियों से जोड़ता है। यह कहाँ स्थित है?","optionsHi":["हिमाचल प्रदेश","लद्दाख","सिक्किम","उत्तराखंड"],"explanationHi":"खारदुंग ला (लगभग 5,359 मीटर) लेह के उत्तर में लद्दाख श्रेणी में है। यह नुब्रा घाटी और आगे सियाचिन क्षेत्र का मार्ग है।"},
  {"id":"geo-physical-india-94","question":"Pangong Tso, a long high-altitude lake shared by India and China, lies in:","options":["Sikkim","Arunachal Pradesh","Himachal Pradesh","Ladakh"],"answer":3,"explanation":"Pangong Tso is a brackish lake in eastern Ladakh, and most of its length lies in Tibet. Tso Moriri is another Ladakh lake; Gurudongmar and Tsomgo are in Sikkim.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"पैंगोंग त्सो, भारत और चीन के बीच साझा एक लंबी, ऊँचाई पर स्थित झील, कहाँ स्थित है?","optionsHi":["सिक्किम","अरुणाचल प्रदेश","हिमाचल प्रदेश","लद्दाख"],"explanationHi":"पैंगोंग त्सो पूर्वी लद्दाख की खारे पानी की झील है, और इसकी अधिकांश लंबाई तिब्बत में है। त्सो मोरिरी लद्दाख की एक अन्य झील है; गुरुडोंगमार और सोम्गो सिक्किम में हैं।"},
  {"id":"geo-physical-india-95","question":"Mahendragiri, one of the higher peaks of the Eastern Ghats, is located in:","options":["Tamil Nadu","Andhra Pradesh","Odisha","Karnataka"],"answer":2,"explanation":"Mahendragiri (about 1,500 m) is in Gajapati district of Odisha. The Eastern Ghats are broken into separate hill groups by the Mahanadi, Godavari, Krishna and Kaveri.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"महेंद्रगिरि, पूर्वी घाट की ऊँची चोटियों में से एक, कहाँ स्थित है?","optionsHi":["तमिलनाडु","आंध्र प्रदेश","ओडिशा","कर्नाटक"],"explanationHi":"महेंद्रगिरि (लगभग 1,500 मीटर) ओडिशा के गजपति ज़िले में है। पूर्वी घाट महानदी, गोदावरी, कृष्णा और कावेरी द्वारा अलग-अलग पहाड़ी समूहों में टूटे हुए हैं।"},
  {"id":"geo-physical-india-96","question":"The Karbi Anglong plateau and the North Cachar hills in Assam are best described as:","options":["Part of the Shiwalik foothill range","Volcanic plateaus of the Tertiary era","An outlier of the peninsular plateau","Parts of the Purvanchal fold mountains"],"answer":2,"explanation":"Like the Meghalaya plateau, the Karbi Anglong plateau is a detached part of the old peninsular block, separated from it by the Garo–Rajmahal gap. It is not part of the young folded Purvanchal hills.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"असम का कार्बी आंगलोंग पठार और उत्तरी कछार पहाड़ियाँ सबसे उपयुक्त रूप से किस रूप में वर्णित हैं?","optionsHi":["शिवालिक तलहटी श्रेणी का भाग","टर्शियरी युग के ज्वालामुखीय पठार","प्रायद्वीपीय पठार का एक बहिर्वेधी भाग","पूर्वांचल वलित पर्वतों के भाग"],"explanationHi":"मेघालय पठार की तरह कार्बी आंगलोंग पठार प्राचीन प्रायद्वीपीय खंड का एक अलग हुआ भाग है, जो गारो-राजमहल गैप द्वारा उससे पृथक है। यह नई वलित पूर्वांचल पहाड़ियों का भाग नहीं है।"},
  {"id":"geo-physical-india-97","question":"Rameswaram, the pilgrim town at the start of the chain of shoals towards Sri Lanka, stands on:","options":["Elephanta Island","Sriharikota Island","Majuli Island","Pamban Island"],"answer":3,"explanation":"Rameswaram is on Pamban Island in the Gulf of Mannar, linked to the mainland by the Pamban rail and road bridges. Adam's Bridge (Ram Setu) runs from there towards Mannar in Sri Lanka.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"रामेश्वरम, श्रीलंका की ओर जाने वाली उथली चट्टानों की शृंखला के आरंभ पर स्थित तीर्थ नगर, किस द्वीप पर है?","optionsHi":["एलिफेंटा द्वीप","श्रीहरिकोटा द्वीप","माजुली द्वीप","पंबन द्वीप"],"explanationHi":"रामेश्वरम मन्नार की खाड़ी में पंबन द्वीप पर है, जो पंबन रेल और सड़क पुलों से मुख्य भूमि से जुड़ा है। आदम का पुल (राम सेतु) वहाँ से श्रीलंका के मन्नार की ओर जाता है।"},
  {"id":"geo-physical-india-98","question":"The island off the Odisha coast from which India test-fires missiles, renamed in 2015 after a former President, is:","options":["Wheeler Island (APJ Abdul Kalam Island)","Sriharikota","Havelock Island (Swaraj Dweep)","Ross Island (Netaji Subhas Chandra Bose Dweep)"],"answer":0,"explanation":"Wheeler Island in Bhadrak district was renamed APJ Abdul Kalam Island in 2015. Sriharikota, in Andhra Pradesh, is ISRO's launch site, and Havelock and Ross are in the Andamans.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"ओडिशा तट के पास वह द्वीप कौन-सा है जहाँ से भारत मिसाइलों का परीक्षण करता है और जिसका नाम 2015 में एक पूर्व राष्ट्रपति के नाम पर रखा गया?","optionsHi":["व्हीलर द्वीप (APJ अब्दुल कलाम द्वीप)","श्रीहरिकोटा","हैवलॉक द्वीप (स्वराज द्वीप)","रॉस द्वीप (नेताजी सुभाष चंद्र बोस द्वीप)"],"explanationHi":"भद्रक ज़िले के व्हीलर द्वीप का नाम 2015 में APJ अब्दुल कलाम द्वीप रखा गया। आंध्र प्रदेश का श्रीहरिकोटा ISRO का प्रक्षेपण स्थल है, और हैवलॉक तथा रॉस अंडमान में हैं।"},
  {"id":"geo-physical-india-99","question":"Sriharikota, home of the Satish Dhawan Space Centre, is a barrier island that separates the Bay of Bengal from:","options":["Chilika lake","Pulicat lake","Kolleru lake","Vembanad lake"],"answer":1,"explanation":"Sriharikota lies between Pulicat lake and the sea in Andhra Pradesh, near the Tamil Nadu border. Kolleru is a freshwater lake in the Godavari–Krishna delta region.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"श्रीहरिकोटा, सतीश धवन अंतरिक्ष केंद्र का स्थल, एक रोधी द्वीप है जो बंगाल की खाड़ी को किससे अलग करता है?","optionsHi":["चिल्का झील","पुलिकट झील","कोल्लेरू झील","वेम्बनाड झील"],"explanationHi":"श्रीहरिकोटा आंध्र प्रदेश में तमिलनाडु सीमा के निकट पुलिकट झील और समुद्र के बीच स्थित है। कोल्लेरू गोदावरी-कृष्णा डेल्टा क्षेत्र की मीठे पानी की झील है।"},
  {"id":"geo-physical-india-100","question":"India's coastline, long quoted as 7,516.6 km, was re-measured with a finer method and officially revised in 2024–25 to about:","options":["8,200 km","9,500 km","13,500 km","11,099 km"],"answer":3,"explanation":"Re-measurement at a larger scale, counting more of the indentations and islands, put the coastline at about 11,098.8 km. Gujarat still has the longest coastline of any State.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत की तटरेखा, जिसे लंबे समय से 7,516.6 किमी बताया जाता था, को अधिक सूक्ष्म विधि से पुनः मापा गया और 2024-25 में आधिकारिक रूप से संशोधित कर लगभग कितना किया गया?","optionsHi":["8,200 किमी","9,500 किमी","13,500 किमी","11,099 किमी"],"explanationHi":"बड़े पैमाने पर पुनः मापन में, जिसमें अधिक कटाव और द्वीप गिने गए, तटरेखा लगभग 11,098.8 किमी निकली। राज्यों में गुजरात की तटरेखा अब भी सबसे लंबी है।"},
  {"id":"geo-physical-india-101","question":"\"Bagar\" in Rajasthan refers to:","options":["The salt-lake basins such as Sambhar","The salt marsh of the Rann of Kachchh","Semi-arid tract east of the Marusthali","The Hadoti plateau around Kota and Bundi"],"answer":2,"explanation":"The Thar is divided into the true desert (Marusthali) in the west and the semi-arid Bagar to the east, towards the Aravalli. The Bagar has a thin cover of sand and is drained by short seasonal streams that rise in the Aravalli.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"राजस्थान में “बागर” से क्या तात्पर्य है?","optionsHi":["सांभर जैसे खारे झील बेसिन","कच्छ के रन का लवणीय दलदल","मरुस्थली के पूर्व का अर्ध-शुष्क क्षेत्र","कोटा और बूंदी के आसपास का हाड़ौती पठार"],"explanationHi":"थार पश्चिम में वास्तविक मरुस्थल (मरुस्थली) और पूर्व में अरावली की ओर अर्ध-शुष्क बागर में बँटा है। बागर पर रेत की पतली परत है और इसका अपवाह अरावली से निकलने वाली छोटी मौसमी धाराओं द्वारा होता है।"},
  {"id":"geo-physical-india-102","question":"Kolleru, one of India's largest freshwater lakes, lies:","options":["In the Mahanadi delta in Odisha","Between the Godavari and Krishna deltas","In the Kaveri delta in Tamil Nadu","Behind the sand bars of the Kerala coast"],"answer":1,"explanation":"Kolleru, between the Godavari and Krishna deltas, acts as a natural flood-balancing reservoir and is a bird sanctuary and Ramsar site. Chilika (Odisha) and Pulicat are brackish lagoons.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"कोल्लेरू, भारत की सबसे बड़ी मीठे पानी की झीलों में से एक, कहाँ स्थित है?","optionsHi":["ओडिशा में महानदी डेल्टा में","गोदावरी और कृष्णा डेल्टाओं के बीच","तमिलनाडु में कावेरी डेल्टा में","केरल तट की रेतीली रोधिकाओं के पीछे"],"explanationHi":"गोदावरी और कृष्णा डेल्टाओं के बीच स्थित कोल्लेरू प्राकृतिक बाढ़-संतुलक जलाशय का कार्य करती है और पक्षी अभयारण्य तथा रामसर स्थल है। चिल्का (ओडिशा) और पुलिकट खारे पानी की लैगून हैं।"},
  {"id":"geo-physical-india-103","question":"Lonar lake in Buldhana district, Maharashtra, is notable because it:","options":["Was formed by a meteorite impact in basalt","Is the largest artificial lake of the Deccan","Was formed by a landslide that blocked a river","Is a coastal lagoon cut off by a sand bar"],"answer":0,"explanation":"Lonar is a saline, alkaline crater lake formed by a meteorite impact in the Deccan basalts. It was declared a Ramsar site in 2020.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"महाराष्ट्र के बुलढाणा ज़िले की लोनार झील किस कारण उल्लेखनीय है?","optionsHi":["यह बेसाल्ट में उल्कापिंड के टकराव से बनी","यह दक्कन की सबसे बड़ी कृत्रिम झील है","यह भूस्खलन से नदी के अवरुद्ध होने से बनी","यह रेत की रोधिका से कटी हुई तटीय लैगून है"],"explanationHi":"लोनार दक्कन के बेसाल्ट में उल्कापिंड के टकराव से बनी खारी, क्षारीय क्रेटर झील है। इसे 2020 में रामसर स्थल घोषित किया गया।"},
  {"id":"geo-physical-india-104","question":"Match the regional division of the Himalaya with the rivers that bound it: A. Punjab Himalaya B. Kumaon Himalaya C. Nepal Himalaya D. Assam Himalaya. 1. Tista and Dihang 2. Kali and Tista 3. Sutlej and Kali 4. Indus and Sutlej","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"From west to east: Punjab Himalaya (Indus to Sutlej), Kumaon Himalaya (Sutlej to Kali), Nepal Himalaya (Kali to Tista, the highest section) and Assam Himalaya (Tista to Dihang).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"हिमालय के क्षेत्रीय विभाजन का मिलान उन नदियों से कीजिए जो उसकी सीमा बनाती हैं: A. पंजाब हिमालय B. कुमाऊँ हिमालय C. नेपाल हिमालय D. असम हिमालय। 1. तीस्ता और दिहांग 2. काली और तीस्ता 3. सतलुज और काली 4. सिंधु और सतलुज","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"पश्चिम से पूर्व: पंजाब हिमालय (सिंधु से सतलुज), कुमाऊँ हिमालय (सतलुज से काली), नेपाल हिमालय (काली से तीस्ता, सबसे ऊँचा भाग) और असम हिमालय (तीस्ता से दिहांग)।"},
  {"id":"geo-physical-india-105","question":"Match the rock system with the resource it is known for: A. Dharwar B. Vindhyan C. Gondwana D. Tertiary. 1. Petroleum of Assam 2. Coal of the Damodar valley 3. Red sandstone and the diamonds of Panna 4. Gold of Kolar and rich iron ore","options":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":2,"explanation":"The ancient Dharwar rocks hold the Kolar gold and much of the iron ore. The Vindhyan rocks give building sandstone and Panna's diamonds. About 98% of the coal is in Gondwana rocks, and Assam's oil is in Tertiary rocks.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"चट्टान क्रम का मिलान उस संसाधन से कीजिए जिसके लिए वह जाना जाता है: A. धारवाड़ B. विंध्यन C. गोंडवाना D. टर्शियरी। 1. असम का पेट्रोलियम 2. दामोदर घाटी का कोयला 3. लाल बलुआ पत्थर और पन्ना के हीरे 4. कोलार का सोना और समृद्ध लौह अयस्क","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"प्राचीन धारवाड़ चट्टानों में कोलार का सोना और अधिकांश लौह अयस्क है। विंध्यन चट्टानों से भवन निर्माण का बलुआ पत्थर और पन्ना के हीरे मिलते हैं। लगभग 98% कोयला गोंडवाना चट्टानों में है, और असम का तेल टर्शियरी चट्टानों में है।"},
  {"id":"geo-physical-india-106","question":"Match the pass with the route it serves: A. Thal Ghat B. Bhor Ghat C. Shencottah gap D. Bara-lacha La. 1. Lahaul in Himachal Pradesh to Ladakh 2. Kerala to Tamil Nadu (Kollam–Tenkasi) 3. Mumbai to Pune 4. Mumbai to Nashik","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Thal (Kasara) Ghat carries the Mumbai–Nashik route and Bhor Ghat the Mumbai–Pune route across the Sahyadri. The Shencottah gap breaks the southern Western Ghats, and Bara-lacha La is on the Manali–Leh highway.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"दर्रे का मिलान उस मार्ग से कीजिए जिसकी वह सेवा करता है: A. थाल घाट B. भोर घाट C. शेनकोट्टा दर्रा D. बारालाचा ला। 1. हिमाचल प्रदेश के लाहौल से लद्दाख 2. केरल से तमिलनाडु (कोल्लम-तेनकासी) 3. मुंबई से पुणे 4. मुंबई से नासिक","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"थाल (कसारा) घाट मुंबई-नासिक मार्ग और भोर घाट मुंबई-पुणे मार्ग को सह्याद्रि के पार ले जाता है। शेनकोट्टा दर्रा दक्षिणी पश्चिमी घाट को तोड़ता है, और बारालाचा ला मनाली-लेह राजमार्ग पर है।"},
  {"id":"geo-physical-india-107","question":"Arrange these peaks in descending order of height: 1. Guru Shikhar 2. Kalsubai 3. Anamudi 4. Dhupgarh","options":["3, 1, 2, 4","3, 2, 1, 4","1, 3, 2, 4","3, 1, 4, 2"],"answer":0,"explanation":"Anamudi (about 2,695 m) → Guru Shikhar (about 1,722 m, Aravalli) → Kalsubai (about 1,646 m, Sahyadri) → Dhupgarh (about 1,350 m, Satpura).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन चोटियों को ऊँचाई के घटते क्रम में व्यवस्थित कीजिए: 1. गुरु शिखर 2. कलसुबाई 3. अनामुडी 4. धूपगढ़","optionsHi":["3, 1, 2, 4","3, 2, 1, 4","1, 3, 2, 4","3, 1, 4, 2"],"explanationHi":"अनामुडी (लगभग 2,695 मीटर) → गुरु शिखर (लगभग 1,722 मीटर, अरावली) → कलसुबाई (लगभग 1,646 मीटर, सह्याद्रि) → धूपगढ़ (लगभग 1,350 मीटर, सतपुड़ा)।"},
  {"id":"geo-physical-india-108","question":"Assertion (A): Indian Standard Time is 5 hours 30 minutes ahead of Greenwich Mean Time. Reason (R): India's standard meridian is 82°30′ E, and time changes by 4 minutes for every degree of longitude.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"82.5° × 4 minutes = 330 minutes = 5 hours 30 minutes. With India spanning about 30° of longitude, local time in Arunachal Pradesh is about 2 hours ahead of local time in Gujarat.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): भारतीय मानक समय ग्रीनविच मीन टाइम से 5 घंटे 30 मिनट आगे है। कारण (R): भारत का मानक याम्योत्तर 82°30′ पू. है, और प्रत्येक देशांतर अंश पर समय 4 मिनट बदलता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"82.5° × 4 मिनट = 330 मिनट = 5 घंटे 30 मिनट। भारत के लगभग 30° देशांतर में फैले होने के कारण अरुणाचल प्रदेश का स्थानीय समय गुजरात के स्थानीय समय से लगभग 2 घंटे आगे है।"},
  {"id":"geo-physical-india-109","question":"How many of these statements about India's size and location are correct? I. India has about 2.4% of the world's land area. II. It holds over 17% of the world's population. III. It shares land borders with seven countries. IV. The standard meridian passes through five States.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The neighbours are Pakistan, Afghanistan, China, Nepal, Bhutan, Bangladesh and Myanmar. The 82°30′ E meridian crosses Uttar Pradesh, Madhya Pradesh, Chhattisgarh, Odisha and Andhra Pradesh.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत के आकार और अवस्थिति के बारे में इनमें से कितने कथन सही हैं? I. भारत के पास विश्व के भूभाग का लगभग 2.4% है। II. इसमें विश्व की 17% से अधिक जनसंख्या रहती है। III. इसकी भू-सीमाएँ सात देशों से लगती हैं। IV. मानक याम्योत्तर पाँच राज्यों से होकर गुज़रता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। पड़ोसी देश पाकिस्तान, अफ़ग़ानिस्तान, चीन, नेपाल, भूटान, बांग्लादेश और म्यांमार हैं। 82°30′ पू. याम्योत्तर उत्तर प्रदेश, मध्य प्रदेश, छत्तीसगढ़, ओडिशा और आंध्र प्रदेश को पार करता है।"},
  {"id":"geo-physical-india-110","question":"How many of these statements are correct? I. Sir Creek is a disputed tidal estuary between Gujarat and Sindh. II. Indira Col in the Siachen area is given as India's northernmost point. III. Kanyakumari is the southernmost point of the mainland. IV. Indira Point lies on Little Andaman.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Indira Point, the southernmost point of the country, is at the southern tip of Great Nicobar, not Little Andaman.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. सर क्रीक गुजरात और सिंध के बीच एक विवादित ज्वारीय ज्वारनदमुख है। II. सियाचिन क्षेत्र का इंदिरा कोल भारत का उत्तरतम बिंदु बताया जाता है। III. कन्याकुमारी मुख्य भूमि का दक्षिणतम बिंदु है। IV. इंदिरा प्वाइंट लिटिल अंडमान पर स्थित है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। इंदिरा प्वाइंट, देश का दक्षिणतम बिंदु, ग्रेट निकोबार के दक्षिणी सिरे पर है, लिटिल अंडमान पर नहीं।"},
  {"id":"geo-physical-india-111","question":"How many of these statements about the Purvanchal hills are correct? I. The Patkai Bum runs along the border of Arunachal Pradesh and Myanmar. II. The highest peak of the Mizo hills is Saramati. III. The Naga hills form a watershed between India and Bangladesh. IV. The Purvanchal hills are part of the old peninsular plateau.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Saramati is the highest peak of the Naga hills (the Mizo hills peak at Phawngpui), the Naga hills form a watershed between India and Myanmar, not Bangladesh, and the Purvanchal are young fold mountains, not part of the old peninsular block.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"पूर्वांचल पहाड़ियों के बारे में इनमें से कितने कथन सही हैं? I. पटकाई बुम अरुणाचल प्रदेश और म्यांमार की सीमा के साथ फैली है। II. मिज़ो पहाड़ियों की सबसे ऊँची चोटी सारामती है। III. नागा पहाड़ियाँ भारत और बांग्लादेश के बीच जलविभाजक बनाती हैं। IV. पूर्वांचल पहाड़ियाँ प्राचीन प्रायद्वीपीय पठार का भाग हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। सारामती नागा पहाड़ियों की सबसे ऊँची चोटी है (मिज़ो पहाड़ियों की चोटी फौंगपुई है), नागा पहाड़ियाँ भारत और म्यांमार के बीच जलविभाजक बनाती हैं, बांग्लादेश के नहीं, और पूर्वांचल नए वलित पर्वत हैं, प्राचीन प्रायद्वीपीय खंड का भाग नहीं।"},
  {"id":"geo-physical-india-112","question":"Which of these hill ranges is NOT part of the Eastern Ghats?","options":["Javadi hills","Shevaroy hills","Nallamala hills","Cardamom hills"],"answer":3,"explanation":"The Cardamom hills are at the southern end of the Western Ghats, in Kerala and Tamil Nadu. The Javadi and Shevaroy (Yercaud) hills in Tamil Nadu and the Nallamala in Andhra Pradesh belong to the Eastern Ghats.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सी पहाड़ी श्रेणी पूर्वी घाट का भाग नहीं है?","optionsHi":["जवादी पहाड़ियाँ","शेवरॉय पहाड़ियाँ","नल्लामलाई पहाड़ियाँ","इलायची (कार्डमम) पहाड़ियाँ"],"explanationHi":"इलायची पहाड़ियाँ केरल और तमिलनाडु में पश्चिमी घाट के दक्षिणी छोर पर हैं। तमिलनाडु की जवादी और शेवरॉय (यरकौड) पहाड़ियाँ तथा आंध्र प्रदेश की नल्लामलाई पूर्वी घाट की हैं।"},
  {"id":"geo-physical-india-113","question":"Assertion (A): The peninsular plateau is one of the most stable parts of the Indian landmass. Reason (R): It is a block of ancient crystalline rocks that formed part of Gondwana land and has escaped the folding that built the Himalaya.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The plateau is a rigid shield of Archaean and later rocks from Gondwana land, which is why it is relatively stable. Stable does not mean free of earthquakes: Koyna (1967) and Latur (1993) occurred there.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): प्रायद्वीपीय पठार भारतीय भूभाग के सबसे स्थिर भागों में से एक है। कारण (R): यह प्राचीन क्रिस्टलीय चट्टानों का खंड है जो गोंडवाना भूमि का भाग था और हिमालय बनाने वाले वलन से बचा रहा।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"यह पठार गोंडवाना भूमि की आर्कियन और बाद की चट्टानों की कठोर ढाल है, इसीलिए अपेक्षाकृत स्थिर है। स्थिर का अर्थ भूकंप-मुक्त होना नहीं है: कोयना (1967) और लातूर (1993) वहीं आए थे।"},
  {"id":"geo-physical-india-114","question":"How many of these statements about India's islands are correct? I. The Andaman and Nicobar group has over 500 islands. II. The Lakshadweep group has 36 islands. III. Ritchie's Archipelago is part of the Andaman islands. IV. Minicoy is the northernmost island of the Lakshadweep group.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Minicoy is the southernmost island of the Lakshadweep group, separated from the rest by the Nine Degree Channel.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत के द्वीपों के बारे में इनमें से कितने कथन सही हैं? I. अंडमान और निकोबार समूह में 500 से अधिक द्वीप हैं। II. लक्षद्वीप समूह में 36 द्वीप हैं। III. रिची द्वीपसमूह अंडमान द्वीपों का भाग है। IV. मिनिकॉय लक्षद्वीप समूह का उत्तरतम द्वीप है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। मिनिकॉय लक्षद्वीप समूह का दक्षिणतम द्वीप है, जो नाइन डिग्री चैनल द्वारा शेष समूह से अलग है।"},
  {"id":"geo-physical-india-115","question":"Arrange these hill ranges from west to east: 1. Jaintia hills 2. Garo hills 3. Patkai Bum 4. Khasi hills","options":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"answer":0,"explanation":"On the Meghalaya plateau the Garo hills are in the west, the Khasi hills in the middle and the Jaintia hills in the east. The Patkai Bum lies further north-east, on the Arunachal–Myanmar border.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन पहाड़ियों को पश्चिम से पूर्व के क्रम में व्यवस्थित कीजिए: 1. जयंतिया पहाड़ियाँ 2. गारो पहाड़ियाँ 3. पटकाई बुम 4. खासी पहाड़ियाँ","optionsHi":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"explanationHi":"मेघालय पठार पर गारो पहाड़ियाँ पश्चिम में, खासी पहाड़ियाँ मध्य में और जयंतिया पहाड़ियाँ पूर्व में हैं। पटकाई बुम और आगे उत्तर-पूर्व में, अरुणाचल-म्यांमार सीमा पर है।"},
  {"id":"geo-physical-india-116","question":"The Andaman and Nicobar Islands lie in the:","options":["Arabian Sea","Bay of Bengal","Gulf of Mannar","Red Sea"],"answer":1,"explanation":"The Andaman and Nicobar group lies in the south-east Bay of Bengal, separating it from the Andaman Sea. The coral Lakshadweep islands are in the Arabian Sea.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"अंडमान और निकोबार द्वीप समूह कहाँ स्थित हैं?","optionsHi":["अरब सागर","बंगाल की खाड़ी","मन्नार की खाड़ी","लाल सागर"],"explanationHi":"अंडमान और निकोबार समूह बंगाल की खाड़ी के दक्षिण-पूर्व में स्थित है और उसे अंडमान सागर से अलग करता है। प्रवाल लक्षद्वीप द्वीप अरब सागर में हैं।"},
  {"id":"geo-physical-india-117","question":"Most of the Thar (Great Indian) Desert lies in the state of:","options":["Rajasthan","Madhya Pradesh","Maharashtra","Uttar Pradesh"],"answer":0,"explanation":"The Thar covers western Rajasthan and extends into Gujarat, Haryana and Punjab and across the border into Pakistan.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"थार (वृहत् भारतीय) मरुस्थल का अधिकांश भाग किस राज्य में है?","optionsHi":["राजस्थान","मध्य प्रदेश","महाराष्ट्र","उत्तर प्रदेश"],"explanationHi":"थार पश्चिमी राजस्थान में फैला है और गुजरात, हरियाणा और पंजाब तथा सीमा पार पाकिस्तान तक विस्तृत है।"},
  {"id":"geo-physical-india-118","question":"At Kanyakumari, the southern tip of mainland India, which three water bodies meet?","options":["Arabian Sea, Red Sea and Indian Ocean","Bay of Bengal, Andaman Sea and Indian Ocean","Arabian Sea, Bay of Bengal and Indian Ocean","Palk Bay, Gulf of Mannar and Arabian Sea"],"answer":2,"explanation":"Kanyakumari is where the Arabian Sea, the Bay of Bengal and the Indian Ocean meet. The southernmost point of the whole country is Indira Point on Great Nicobar.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कन्याकुमारी, मुख्य भूमि भारत के दक्षिणी सिरे, पर कौन-से तीन जलाशय मिलते हैं?","optionsHi":["अरब सागर, लाल सागर और हिंद महासागर","बंगाल की खाड़ी, अंडमान सागर और हिंद महासागर","अरब सागर, बंगाल की खाड़ी और हिंद महासागर","पाक खाड़ी, मन्नार की खाड़ी और अरब सागर"],"explanationHi":"कन्याकुमारी वह स्थान है जहाँ अरब सागर, बंगाल की खाड़ी और हिंद महासागर मिलते हैं। पूरे देश का दक्षिणतम बिंदु ग्रेट निकोबार का इंदिरा प्वाइंट है।"},
  {"id":"geo-physical-india-119","question":"The Gulf of Mannar Marine National Park, with its coral reefs and islands, lies off the coast of:","options":["Kerala","Andhra Pradesh","Gujarat","Tamil Nadu"],"answer":3,"explanation":"The Gulf of Mannar lies between south-east Tamil Nadu and Sri Lanka, south of Rameswaram. The Gulf of Kachchh Marine National Park is the one in Gujarat.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"मन्नार की खाड़ी समुद्री राष्ट्रीय उद्यान, जिसमें प्रवाल भित्तियाँ और द्वीप हैं, किसके तट के पास स्थित है?","optionsHi":["केरल","आंध्र प्रदेश","गुजरात","तमिलनाडु"],"explanationHi":"मन्नार की खाड़ी दक्षिण-पूर्वी तमिलनाडु और श्रीलंका के बीच, रामेश्वरम के दक्षिण में है। गुजरात में कच्छ की खाड़ी समुद्री राष्ट्रीय उद्यान है।"},
  {"id":"geo-physical-india-120","question":"Which of these states does NOT share a border with Bangladesh?","options":["Meghalaya","Tripura","Manipur","Mizoram"],"answer":2,"explanation":"Bangladesh borders West Bengal, Assam, Meghalaya, Tripura and Mizoram. Manipur borders Myanmar but not Bangladesh.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कौन-सा राज्य बांग्लादेश के साथ सीमा साझा नहीं करता?","optionsHi":["मेघालय","त्रिपुरा","मणिपुर","मिज़ोरम"],"explanationHi":"बांग्लादेश की सीमा पश्चिम बंगाल, असम, मेघालय, त्रिपुरा और मिज़ोरम से लगती है। मणिपुर की सीमा म्यांमार से लगती है, बांग्लादेश से नहीं।"},
  {"id":"geo-physical-india-121","question":"Which of these states has no coastline?","options":["Telangana","Odisha","Goa","Karnataka"],"answer":0,"explanation":"Telangana, carved out of Andhra Pradesh in 2014, is landlocked; the coast stayed with Andhra Pradesh. Odisha, Goa and Karnataka all face the sea.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से किस राज्य की कोई तटरेखा नहीं है?","optionsHi":["तेलंगाना","ओडिशा","गोवा","कर्नाटक"],"explanationHi":"2014 में आंध्र प्रदेश से अलग बना तेलंगाना स्थल-रुद्ध है; तट आंध्र प्रदेश के पास रहा। ओडिशा, गोवा और कर्नाटक तीनों समुद्र से लगे हैं।"},
  {"id":"geo-physical-india-122","question":"Which state shares international borders with Nepal, Bhutan and China?","options":["Arunachal Pradesh","West Bengal","Assam","Sikkim"],"answer":3,"explanation":"Sikkim touches Nepal to the west, Tibet (China) to the north and east, and Bhutan to the south-east. West Bengal borders Nepal, Bhutan and Bangladesh but not China.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"कौन-सा राज्य नेपाल, भूटान और चीन के साथ अंतरराष्ट्रीय सीमाएँ साझा करता है?","optionsHi":["अरुणाचल प्रदेश","पश्चिम बंगाल","असम","सिक्किम"],"explanationHi":"सिक्किम पश्चिम में नेपाल, उत्तर और पूर्व में तिब्बत (चीन) और दक्षिण-पूर्व में भूटान से लगा है। पश्चिम बंगाल की सीमा नेपाल, भूटान और बांग्लादेश से लगती है, चीन से नहीं।"},
  {"id":"geo-physical-india-123","question":"Which state borders both Myanmar and Bangladesh?","options":["Manipur","Mizoram","Tripura","Nagaland"],"answer":1,"explanation":"Mizoram is wedged between Myanmar to the east and south and Bangladesh to the west. Manipur and Nagaland touch only Myanmar, Tripura only Bangladesh.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"कौन-सा राज्य म्यांमार और बांग्लादेश दोनों से सीमा साझा करता है?","optionsHi":["मणिपुर","मिज़ोरम","त्रिपुरा","नागालैंड"],"explanationHi":"मिज़ोरम पूर्व और दक्षिण में म्यांमार और पश्चिम में बांग्लादेश के बीच स्थित है। मणिपुर और नागालैंड केवल म्यांमार से और त्रिपुरा केवल बांग्लादेश से लगे हैं।"},
  {"id":"geo-physical-india-124","question":"The Andaman and Nicobar Islands are the elevated portion of a submarine mountain chain that continues the:","options":["Western Ghats and Nilgiris","Aravalli range","Arakan Yoma of Myanmar","Eastern Ghats of Odisha"],"answer":2,"explanation":"The Andaman–Nicobar arc is a southward extension of the Arakan Yoma fold mountains, running on to Sumatra. The Lakshadweep, by contrast, are coral islands.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अंडमान और निकोबार द्वीप समूह एक जलमग्न पर्वत शृंखला का उभरा हुआ भाग हैं जो किसका विस्तार है?","optionsHi":["पश्चिमी घाट और नीलगिरि","अरावली श्रेणी","म्यांमार की अराकान योमा","ओडिशा का पूर्वी घाट"],"explanationHi":"अंडमान-निकोबार चाप अराकान योमा वलित पर्वतों का दक्षिण की ओर विस्तार है, जो आगे सुमात्रा तक जाता है। इसके विपरीत, लक्षद्वीप प्रवाल द्वीप हैं।"},
  {"id":"geo-physical-india-125","question":"Bum La, a pass on the Line of Actual Control used for border personnel meetings, connects Tibet with which district?","options":["Tawang, Arunachal Pradesh","North Sikkim","Kinnaur, Himachal Pradesh","Leh, Ladakh"],"answer":0,"explanation":"Bum La lies north of Tawang in Arunachal Pradesh. Nathu La links Sikkim with Tibet and Shipki La links Kinnaur with Tibet.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"बुम ला, वास्तविक नियंत्रण रेखा पर एक दर्रा जो सीमा कर्मियों की बैठकों के लिए प्रयुक्त होता है, तिब्बत को किस ज़िले से जोड़ता है?","optionsHi":["तवांग, अरुणाचल प्रदेश","उत्तरी सिक्किम","किन्नौर, हिमाचल प्रदेश","लेह, लद्दाख"],"explanationHi":"बुम ला अरुणाचल प्रदेश में तवांग के उत्तर में है। नाथू ला सिक्किम को तिब्बत से और शिपकी ला किन्नौर को तिब्बत से जोड़ता है।"},
  {"id":"geo-physical-india-126","question":"The Dafla, Miri, Abor and Mishmi hills, named after local communities, lie in:","options":["Nagaland and Manipur","Meghalaya plateau","Sikkim and Darjeeling","Arunachal Pradesh"],"answer":3,"explanation":"These are the eastern Himalayan hills of Arunachal Pradesh, from the Dafla hills in the west to the Mishmi hills in the east, where the Himalaya bends south.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"स्थानीय समुदायों के नाम पर रखी गई दफला, मिरी, अबोर और मिश्मी पहाड़ियाँ कहाँ स्थित हैं?","optionsHi":["नागालैंड और मणिपुर","मेघालय पठार","सिक्किम और दार्जिलिंग","अरुणाचल प्रदेश"],"explanationHi":"ये अरुणाचल प्रदेश की पूर्वी हिमालयी पहाड़ियाँ हैं, पश्चिम में दफला पहाड़ियों से पूर्व में मिश्मी पहाड़ियों तक, जहाँ हिमालय दक्षिण की ओर मुड़ता है।"},
  {"id":"geo-physical-india-127","question":"Kuttanad in Kerala is notable because:","options":["It is India's driest region","Farming there is carried out below sea level","It is the highest plateau of the Western Ghats","It is a coral island"],"answer":1,"explanation":"Kuttanad, south of Vembanad lake, grows rice on land lying about 1–2 m below sea level, protected by dykes; its system is recognised by the FAO as a globally important agricultural heritage system.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"केरल का कुट्टनाड किस कारण उल्लेखनीय है?","optionsHi":["यह भारत का सबसे शुष्क क्षेत्र है","वहाँ समुद्र तल से नीचे खेती की जाती है","यह पश्चिमी घाट का सबसे ऊँचा पठार है","यह एक प्रवाल द्वीप है"],"explanationHi":"वेम्बनाड झील के दक्षिण में स्थित कुट्टनाड में समुद्र तल से लगभग 1-2 मीटर नीचे, तटबंधों से सुरक्षित भूमि पर धान उगाया जाता है; इसकी प्रणाली को FAO ने विश्व स्तर पर महत्वपूर्ण कृषि विरासत प्रणाली के रूप में मान्यता दी है।"},
  {"id":"geo-physical-india-128","question":"Assertion (A): The Himalayan region is highly prone to earthquakes. Reason (R): It lies along an active convergent boundary where the Indian plate is pushing against the Eurasian plate.","options":["A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"The ongoing collision builds stress along thrust faults beneath the Himalaya, so the whole belt lies in the highest seismic zones; stable peninsular India sees far fewer large quakes.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): हिमालयी क्षेत्र भूकंप के प्रति अत्यधिक संवेदनशील है। कारण (R): यह एक सक्रिय अभिसारी सीमा पर स्थित है जहाँ भारतीय प्लेट यूरेशियाई प्लेट को धकेल रही है।","optionsHi":["A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"चल रही टक्कर हिमालय के नीचे क्षेप भ्रंशों पर तनाव बनाती है, इसलिए पूरी पट्टी सर्वाधिक भूकंपीय क्षेत्रों में आती है; स्थिर प्रायद्वीपीय भारत में बड़े भूकंप बहुत कम आते हैं।"},
  {"id":"geo-physical-india-129","question":"Arrange these states in the order in which the Tropic of Cancer passes through them from west to east: 1. Jharkhand  2. Mizoram  3. Madhya Pradesh  4. Tripura","options":["3-4-1-2","1-3-4-2","3-1-2-4","3-1-4-2"],"answer":3,"explanation":"The Tropic runs through Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram, in that order from west to east.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन राज्यों को उस क्रम में व्यवस्थित कीजिए जिसमें कर्क रेखा उनसे पश्चिम से पूर्व की ओर गुज़रती है: 1. झारखंड  2. मिज़ोरम  3. मध्य प्रदेश  4. त्रिपुरा","optionsHi":["3-4-1-2","1-3-4-2","3-1-2-4","3-1-4-2"],"explanationHi":"कर्क रेखा पश्चिम से पूर्व इसी क्रम में गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिज़ोरम से होकर गुज़रती है।"},
  {"id":"geo-physical-india-130","question":"Match the hill range with its state. A. Nallamala hills  B. Mahadeo hills  C. Rajmahal hills  D. Lushai hills; 1. Jharkhand  2. Mizoram  3. Andhra Pradesh  4. Madhya Pradesh","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"The Nallamala are part of the Eastern Ghats in Andhra Pradesh; the Mahadeo hills (with Pachmarhi) are in the Satpura of Madhya Pradesh; the Rajmahal hills are in north-east Jharkhand; the Lushai or Mizo hills form Mizoram.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पहाड़ी श्रेणी का मिलान उसके राज्य से कीजिए। A. नल्लामलाई पहाड़ियाँ  B. महादेव पहाड़ियाँ  C. राजमहल पहाड़ियाँ  D. लुशाई पहाड़ियाँ; 1. झारखंड  2. मिज़ोरम  3. आंध्र प्रदेश  4. मध्य प्रदेश","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"नल्लामलाई आंध्र प्रदेश में पूर्वी घाट का भाग हैं; महादेव पहाड़ियाँ (पचमढ़ी सहित) मध्य प्रदेश के सतपुड़ा में हैं; राजमहल पहाड़ियाँ उत्तर-पूर्वी झारखंड में हैं; लुशाई या मिज़ो पहाड़ियाँ मिज़ोरम बनाती हैं।"},
  {"id":"geo-physical-india-131","question":"How many of these statements are correct? I. The Himalaya rose as the Indian plate collided with the Eurasian plate. II. The Indian plate is still moving northward by a few centimetres a year. III. The Himadri are the youngest of the Himalayan ranges. IV. The Aravallis were formed in the same mountain-building phase as the Himalaya.","options":["Only one","Only three","Only two","All four"],"answer":2,"explanation":"I and II are correct. The Shiwaliks, not the Himadri, are the youngest Himalayan range, and the Aravallis are among the oldest fold mountains in the world, far older than the Tertiary Himalaya, so III and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. हिमालय तब उठा जब भारतीय प्लेट यूरेशियाई प्लेट से टकराई। II. भारतीय प्लेट अब भी प्रति वर्ष कुछ सेंटीमीटर उत्तर की ओर खिसक रही है। III. हिमाद्रि हिमालयी श्रेणियों में सबसे नई है। IV. अरावली का निर्माण हिमालय के समान पर्वत-निर्माण चरण में हुआ।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"I और II सही हैं। हिमालयी श्रेणियों में सबसे नई शिवालिक है, हिमाद्रि नहीं, और अरावली विश्व की सबसे पुरानी वलित पर्वत श्रेणियों में से है, टर्शियरी हिमालय से कहीं अधिक पुरानी, इसलिए III और IV गलत हैं।"},
  {"id":"geo-physical-india-132","question":"Assertion (A): The eastern coastal plain is generally broader than the western coastal plain. Reason (R): The large east-flowing rivers have built extensive deltas along the east coast.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The Mahanadi, Godavari, Krishna and Kaveri have spread wide alluvial deltas, widening the eastern plain; on the west the Ghats crowd close to the sea, leaving a narrow strip.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): पूर्वी तटीय मैदान सामान्यतः पश्चिमी तटीय मैदान से अधिक चौड़ा है। कारण (R): पूर्व की ओर बहने वाली बड़ी नदियों ने पूर्वी तट पर विस्तृत डेल्टा बनाए हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"महानदी, गोदावरी, कृष्णा और कावेरी ने चौड़े जलोढ़ डेल्टा फैलाए हैं, जिससे पूर्वी मैदान चौड़ा हो गया है; पश्चिम में घाट समुद्र के निकट आ जाते हैं, जिससे संकरी पट्टी बचती है।"},
  {"id":"geo-physical-india-133","question":"How many of these statements about India's land borders are correct? I. Gujarat, Rajasthan and Punjab are the only states that border Pakistan. II. Uttarakhand borders both China and Bhutan. III. Sikkim borders Bangladesh. IV. Arunachal Pradesh borders Nepal.","options":["Only one","Only two","All four","Only three"],"answer":0,"explanation":"Only I is correct (Jammu and Kashmir and Ladakh are Union Territories). Uttarakhand borders China and Nepal, not Bhutan; Sikkim borders Nepal, Bhutan and China, not Bangladesh; and Arunachal Pradesh borders Bhutan, China and Myanmar, not Nepal.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत की भू-सीमाओं के बारे में इनमें से कितने कथन सही हैं? I. गुजरात, राजस्थान और पंजाब ही पाकिस्तान से सीमा साझा करने वाले एकमात्र राज्य हैं। II. उत्तराखंड की सीमा चीन और भूटान दोनों से लगती है। III. सिक्किम की सीमा बांग्लादेश से लगती है। IV. अरुणाचल प्रदेश की सीमा नेपाल से लगती है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"केवल I सही है (जम्मू और कश्मीर तथा लद्दाख केंद्रशासित प्रदेश हैं)। उत्तराखंड की सीमा चीन और नेपाल से लगती है, भूटान से नहीं; सिक्किम की सीमा नेपाल, भूटान और चीन से लगती है, बांग्लादेश से नहीं; और अरुणाचल प्रदेश की सीमा भूटान, चीन और म्यांमार से लगती है, नेपाल से नहीं।"},
  {"id":"geo-physical-india-134","question":"Arrange these sea passages from north to south: 1. Nine Degree Channel  2. Duncan Passage  3. Eight Degree Channel  4. Ten Degree Channel","options":["2-4-3-1","4-2-1-3","2-4-1-3","2-1-4-3"],"answer":2,"explanation":"The Duncan Passage (about 11°N) lies between South and Little Andaman; the Ten Degree Channel between Little Andaman and Car Nicobar; the Nine Degree Channel near Minicoy; and the Eight Degree Channel between Minicoy and the Maldives.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन समुद्री मार्गों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए: 1. नाइन डिग्री चैनल  2. डंकन पैसेज  3. एट डिग्री चैनल  4. टेन डिग्री चैनल","optionsHi":["2-4-3-1","4-2-1-3","2-4-1-3","2-1-4-3"],"explanationHi":"डंकन पैसेज (लगभग 11°उ.) दक्षिण और लिटिल अंडमान के बीच है; टेन डिग्री चैनल लिटिल अंडमान और कार निकोबार के बीच; नाइन डिग्री चैनल मिनिकॉय के निकट; और एट डिग्री चैनल मिनिकॉय और मालदीव के बीच।"},
  {"id":"geo-physical-india-135","question":"Match the lake with its description. A. Sambhar  B. Pulicat  C. Lonar  D. Tso Moriri; 1. Lake formed in a crater made by a meteorite impact  2. Inland salt lake used for salt production in Rajasthan  3. Coastal lagoon partly cut off from the sea by the barrier island of Sriharikota  4. High-altitude lake in the Changthang region of Ladakh","options":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Sambhar is India's largest inland saline lake; Pulicat on the Andhra–Tamil Nadu border is a lagoon behind Sriharikota; Lonar in Maharashtra fills an impact crater in basalt; Tso Moriri lies at about 4,500 m in Ladakh.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"झील का मिलान उसके विवरण से कीजिए। A. सांभर  B. पुलिकट  C. लोनार  D. त्सो मोरिरी; 1. उल्कापिंड के टकराव से बने क्रेटर में बनी झील  2. राजस्थान की अंतर्देशीय खारी झील जो नमक उत्पादन के काम आती है  3. तटीय लैगून जो श्रीहरिकोटा के रोधी द्वीप द्वारा समुद्र से आंशिक रूप से कटी है  4. लद्दाख के चांगथांग क्षेत्र की उच्च-ऊँचाई वाली झील","optionsHi":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"explanationHi":"सांभर भारत की सबसे बड़ी अंतर्देशीय खारी झील है; आंध्र-तमिलनाडु सीमा पर पुलिकट श्रीहरिकोटा के पीछे की लैगून है; महाराष्ट्र की लोनार बेसाल्ट में उल्कापिंड के गड्ढे में भरी है; त्सो मोरिरी लद्दाख में लगभग 4,500 मीटर पर स्थित है।"},
  {"id":"geo-physical-india-136","question":"How many of these statements about the Western Ghats are correct? I. Their average height increases from north to south. II. The Thal Ghat, Bhor Ghat and Palghat are passes through them. III. Mahendragiri is their highest peak. IV. They are generally lower than the Eastern Ghats.","options":["Only three","Only one","Only two","All four"],"answer":2,"explanation":"I and II are correct: the Western Ghats rise southwards, and Thal Ghat, Bhor Ghat and Palghat are passes across them. III is wrong because their highest peak is Anamudi (2,695 m), while Mahendragiri is in the Eastern Ghats; IV is wrong because the Western Ghats are higher and more continuous.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिमी घाट के बारे में इनमें से कितने कथन सही हैं? I. इनकी औसत ऊँचाई उत्तर से दक्षिण की ओर बढ़ती है। II. थाल घाट, भोर घाट और पालघाट इनके दर्रे हैं। III. महेंद्रगिरि इनकी सबसे ऊँची चोटी है। IV. ये सामान्यतः पूर्वी घाट से नीचे हैं।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I और II सही हैं: पश्चिमी घाट दक्षिण की ओर ऊँचे होते जाते हैं, और थाल घाट, भोर घाट तथा पालघाट इनके पार जाने वाले दर्रे हैं। III गलत है क्योंकि इनकी सबसे ऊँची चोटी अनामुडी (2,695 मीटर) है, जबकि महेंद्रगिरि पूर्वी घाट में है; IV गलत है क्योंकि पश्चिमी घाट अधिक ऊँचे और अधिक सतत हैं।"},
  {"id":"geo-physical-india-137","question":"Flat-floored longitudinal valleys lying between the Lesser Himalaya and the Shiwaliks, such as those at Dehradun, Kotli and Patli, are known as:","options":["Duns","Doabs","Karewas","Bhabar"],"answer":0,"explanation":"Duns are structural valleys filled with gravel and alluvium behind the Shiwaliks; doabs are tracts between two rivers, karewas are lake deposits of Kashmir and the bhabar is the pebbly belt at the foot of the Shiwaliks.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"लघु हिमालय और शिवालिक के बीच स्थित समतल तल वाली अनुदैर्ध्य घाटियाँ, जैसे देहरादून, कोटली और पतली, क्या कहलाती हैं?","optionsHi":["दून","दोआब","करेवा","भाबर"],"explanationHi":"दून शिवालिक के पीछे बजरी और जलोढ़ से भरी संरचनात्मक घाटियाँ हैं; दोआब दो नदियों के बीच का क्षेत्र है, करेवा कश्मीर के झील निक्षेप हैं और भाबर शिवालिक की तलहटी की कंकड़ीली पट्टी है।"},
  {"id":"geo-physical-india-138","question":"Arrange these ranges from south to north: 1. Ladakh range  2. Pir Panjal  3. Zaskar range  4. Karakoram","options":["3, 2, 1, 4","2, 1, 3, 4","2, 3, 1, 4","2, 3, 4, 1"],"answer":2,"explanation":"The Pir Panjal belongs to the Lesser Himalaya; north of the Great Himalaya lies the Zaskar range, then the Indus valley and Ladakh range, and finally the Karakoram. Placing Ladakh south of Zaskar is the usual slip.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन श्रेणियों को दक्षिण से उत्तर के क्रम में व्यवस्थित कीजिए: 1. लद्दाख श्रेणी  2. पीर पंजाल  3. ज़ास्कर श्रेणी  4. काराकोरम","optionsHi":["3, 2, 1, 4","2, 1, 3, 4","2, 3, 1, 4","2, 3, 4, 1"],"explanationHi":"पीर पंजाल लघु हिमालय का भाग है; वृहत् हिमालय के उत्तर में ज़ास्कर श्रेणी है, फिर सिंधु घाटी और लद्दाख श्रेणी, और अंत में काराकोरम। लद्दाख को ज़ास्कर के दक्षिण में रखना आम भूल है।"},
  {"id":"geo-physical-india-139","question":"The Meghalaya plateau is separated from the main block of the peninsular plateau (Chhota Nagpur) by:","options":["the Siliguri corridor","the Garo–Rajmahal gap","the Narmada rift valley","the Palghat gap"],"answer":1,"explanation":"The Meghalaya (Shillong) plateau and Karbi Anglong are outliers of the peninsular block; the Garo–Rajmahal gap between them was down-faulted and later buried by Ganga–Brahmaputra sediments. The Siliguri corridor is a political, not a geological, break.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मेघालय पठार को प्रायद्वीपीय पठार के मुख्य खंड (छोटानागपुर) से कौन अलग करता है?","optionsHi":["सिलीगुड़ी गलियारा","गारो-राजमहल गैप","नर्मदा भ्रंश घाटी","पालघाट दर्रा"],"explanationHi":"मेघालय (शिलांग) पठार और कार्बी आंगलोंग प्रायद्वीपीय खंड के बहिर्वेधी भाग हैं; उनके बीच का गारो-राजमहल गैप धँसकर बाद में गंगा-ब्रह्मपुत्र अवसादों से दब गया। सिलीगुड़ी गलियारा राजनीतिक है, भूवैज्ञानिक अंतराल नहीं।"},
  {"id":"geo-physical-india-140","question":"The Northern Circars coastal plain lies between the deltas of the:","options":["Krishna and Kaveri","Ganga and Mahanadi","Mahanadi and Krishna","Kaveri and Tamraparni"],"answer":2,"explanation":"The eastern coastal plain is divided into the Northern Circars in the north, between the Mahanadi and the Krishna, and the Coromandel coast further south.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"उत्तरी सरकार तटीय मैदान किन डेल्टाओं के बीच स्थित है?","optionsHi":["कृष्णा और कावेरी","गंगा और महानदी","महानदी और कृष्णा","कावेरी और तामिरभरणी"],"explanationHi":"पूर्वी तटीय मैदान उत्तर में महानदी और कृष्णा के बीच के उत्तरी सरकार तथा और दक्षिण में कोरोमंडल तट में विभाजित है।"},
  {"id":"geo-physical-india-141","question":"The backwaters of the Kerala coast, such as Vembanad and Ashtamudi, are locally called:","options":["Teris","Karewas","Duns","Kayals"],"answer":3,"explanation":"Kayals are lagoons separated from the sea by sand bars; they are used for fishing, inland navigation and tourism, and host the Nehru Trophy boat race.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"केरल तट के पश्चजल (बैकवाटर), जैसे वेम्बनाड और अष्टमुडी, स्थानीय रूप से क्या कहलाते हैं?","optionsHi":["तेरी","करेवा","दून","कयाल"],"explanationHi":"कयाल रेत की रोधिकाओं से समुद्र से अलग हुई लैगून हैं; इनका उपयोग मछली पकड़ने, अंतर्देशीय नौवहन और पर्यटन में होता है, और यहाँ नेहरू ट्रॉफ़ी नौका दौड़ होती है।"},
  {"id":"geo-physical-india-142","question":"The Bist (Jalandhar) Doab of Punjab lies between the rivers:","options":["Ravi and Beas","Beas and Sutlej","Chenab and Jhelum","Ravi and Chenab"],"answer":1,"explanation":"Bist Doab is the Beas–Sutlej interfluve; the Bari Doab lies between the Beas and Ravi, the Rechna between the Ravi and Chenab and the Chaj between the Chenab and Jhelum.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"पंजाब का बिस्त (जालंधर) दोआब किन नदियों के बीच स्थित है?","optionsHi":["रावी और ब्यास","ब्यास और सतलुज","चिनाब और झेलम","रावी और चिनाब"],"explanationHi":"बिस्त दोआब ब्यास-सतलुज के बीच का क्षेत्र है; बारी दोआब ब्यास और रावी के बीच, रचना रावी और चिनाब के बीच और चाज चिनाब और झेलम के बीच है।"},
  {"id":"geo-physical-india-143","question":"The 'teris' found along the coast of Tamil Nadu near Thoothukudi and Tirunelveli are:","options":["red sand dunes","coral islands","salt pans","tidal lagoons"],"answer":0,"explanation":"Teris are dunes of red sand coloured by iron oxide, found inland from the coast of southern Tamil Nadu; they are not related to the coral islands of the Gulf of Mannar.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"तमिलनाडु में थूथुकुडी और तिरुनेलवेली के पास तट पर पाए जाने वाले ‘तेरी’ क्या हैं?","optionsHi":["लाल रेत के टीले","प्रवाल द्वीप","नमक की क्यारियाँ","ज्वारीय लैगून"],"explanationHi":"तेरी आयरन ऑक्साइड से रंगे लाल रेत के टीले हैं, जो दक्षिणी तमिलनाडु के तट से अंदर की ओर मिलते हैं; इनका मन्नार की खाड़ी के प्रवाल द्वीपों से कोई संबंध नहीं है।"},
  {"id":"geo-physical-india-144","question":"India's mainland extends from about 68°7′ E to 97°25′ E. Taking 1° of longitude as 4 minutes of time, the difference in local time between its two extreme longitudes is nearest to:","options":["1 h 57 min","1 h 44 min","2 h 29 min","2 h 12 min"],"answer":0,"explanation":"The extent is 97°25′ - 68°7′ = 29°18′ = 29.3°, and 29.3 x 4 = 117.2 minutes, about 1 h 57 min. Rounding to 30° gives 2 h, and 2 h 12 min comes from wrongly multiplying by 4.5.","difficulty":"hard","questionHi":"भारत की मुख्य भूमि लगभग 68°7′ पूर्व से 97°25′ पूर्व तक फैली है। देशांतर के 1° को 4 मिनट के समय के बराबर मानकर, इसके दोनों चरम देशांतरों के स्थानीय समय का अंतर लगभग कितना है?","optionsHi":["1 घंटा 57 मिनट","1 घंटा 44 मिनट","2 घंटे 29 मिनट","2 घंटे 12 मिनट"],"explanationHi":"विस्तार 97°25′ - 68°7′ = 29°18′ = 29.3° है, और 29.3 x 4 = 117.2 मिनट, यानी लगभग 1 घंटा 57 मिनट। 30° पर पूर्णांक करने से 2 घंटे आते हैं, और 4.5 से गलत गुणा करने पर 2 घंटे 12 मिनट आता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-145","question":"The mainland of India extends from about 8°4′ N to 37°6′ N. Taking 1° of latitude as 111 km, its north-south extent is nearest to:","options":["2,400 km","3,200 km","2,900 km","3,700 km"],"answer":1,"explanation":"The span is 37°6′ - 8°4′ = 29°2′, about 29.03° x 111 = roughly 3,220 km. The east-west extent is shorter, about 2,930 km, which is the trap option.","difficulty":"moderate","questionHi":"भारत की मुख्य भूमि लगभग 8°4′ उत्तर से 37°6′ उत्तर तक फैली है। अक्षांश के 1° को 111 km मानकर इसका उत्तर-दक्षिण विस्तार लगभग कितना है?","optionsHi":["2,400 km","3,200 km","2,900 km","3,700 km"],"explanationHi":"विस्तार 37°6′ - 8°4′ = 29°2′ है, यानी लगभग 29.03° x 111 = लगभग 3,220 km। पूर्व-पश्चिम विस्तार छोटा है, लगभग 2,930 km, जो भ्रम वाला विकल्प है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-physical-india-146","question":"A hill station stands at 3,000 m while a station at sea level on the same latitude records 30 °C. Taking the normal lapse rate of 6.5 °C per km, the temperature at the hill station is about:","options":["19.5 °C","23.5 °C","10.5 °C","49.5 °C"],"answer":2,"explanation":"Fall in temperature = 3 x 6.5 = 19.5 °C, so 30 - 19.5 = 10.5 °C. The 19.5 °C option is just the drop, and 49.5 °C adds it by mistake.","difficulty":"moderate","questionHi":"एक पर्वतीय स्थल 3,000 m की ऊँचाई पर है, जबकि उसी अक्षांश पर समुद्र तल के स्थान का तापमान 30 °C है। सामान्य ह्रास दर 6.5 °C प्रति km मानकर पर्वतीय स्थल का तापमान लगभग है:","optionsHi":["19.5 °C","23.5 °C","10.5 °C","49.5 °C"],"explanationHi":"तापमान में गिरावट = 3 x 6.5 = 19.5 °C, इसलिए 30 - 19.5 = 10.5 °C। 19.5 °C वाला विकल्प केवल गिरावट है, और 49.5 °C गलती से जोड़ने पर आता है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-physical-india-147","question":"India's Exclusive Economic Zone extends 200 nautical miles from the baseline. Taking 1 nautical mile as 1.852 km, this is about:","options":["222 km","200 km","320 km","370 km"],"answer":3,"explanation":"200 x 1.852 = 370.4 km. The 320 km figure uses the land mile (1.609 km), 200 km ignores the unit conversion, and 222 km is 120 nautical miles.","difficulty":"hard","questionHi":"भारत का विशेष आर्थिक क्षेत्र आधार रेखा से 200 समुद्री मील तक फैला है। 1 समुद्री मील को 1.852 km मानकर यह लगभग कितना है?","optionsHi":["222 km","200 km","320 km","370 km"],"explanationHi":"200 x 1.852 = 370.4 km। 320 km का आँकड़ा स्थल मील (1.609 km) से आता है, 200 km इकाई परिवर्तन छोड़ देता है और 222 km 120 समुद्री मील है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-148","question":"Arrange these maritime zones of India in order of increasing distance from the baseline limit: 1. Exclusive Economic Zone  2. Territorial waters  3. Contiguous zone","options":["2, 3, 1","2, 1, 3","3, 2, 1","1, 3, 2"],"answer":0,"explanation":"Under the Maritime Zones Act, 1976, territorial waters extend 12 nautical miles, the contiguous zone to 24 nautical miles and the exclusive economic zone to 200 nautical miles from the baseline.","difficulty":"moderate","questionHi":"भारत के इन समुद्री क्षेत्रों को आधार रेखा से सीमा की बढ़ती दूरी के क्रम में व्यवस्थित कीजिए: 1. विशेष आर्थिक क्षेत्र  2. प्रादेशिक जल  3. सन्निहित क्षेत्र","optionsHi":["2, 3, 1","2, 1, 3","3, 2, 1","1, 3, 2"],"explanationHi":"समुद्री क्षेत्र अधिनियम, 1976 के अनुसार प्रादेशिक जल आधार रेखा से 12 समुद्री मील, सन्निहित क्षेत्र 24 समुद्री मील और विशेष आर्थिक क्षेत्र 200 समुद्री मील तक फैला है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-149","question":"At the eastern end of the Himalaya, the range bends sharply southward around a peak where the Brahmaputra cuts a deep gorge and makes a U-turn. This peak is:","options":["Gyala Peri","Namcha Barwa","Kangchenjunga","Nanga Parbat"],"answer":1,"explanation":"Namcha Barwa marks the eastern syntaxial bend, where the Tsangpo turns into the Dihang gorge. Nanga Parbat is the matching western bend beside the Indus. Gyala Peri faces it across the gorge.","difficulty":"hard","questionHi":"हिमालय के पूर्वी छोर पर पर्वत श्रेणी एक शिखर के चारों ओर तेज़ी से दक्षिण की ओर मुड़ती है, जहाँ ब्रह्मपुत्र गहरी घाटी काटकर U-आकार का मोड़ लेती है। यह शिखर है:","optionsHi":["ग्याला पेरी","नामचा बरवा","कंचनजंगा","नंगा पर्वत"],"explanationHi":"नामचा बरवा पूर्वी संधि-मोड़ को चिह्नित करता है, जहाँ सांगपो नदी दिहांग घाटी में मुड़ती है। नंगा पर्वत सिंधु के पास संगत पश्चिमी मोड़ है। ग्याला पेरी घाटी के दूसरी ओर उसके सामने है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-150","question":"The Indus, Sutlej and Brahmaputra rivers cut deep gorges across the Himalaya and are older than the range. Their courses are examples of:","options":["Trellis drainage","Dendritic drainage","Antecedent drainage","Superimposed drainage"],"answer":2,"explanation":"Antecedent rivers kept their courses while the mountain rose across them, cutting gorges as the land lifted. Superimposed rivers are let down from a cover rock on to a buried structure, as with the Chambal across the old Vindhyan folds.","difficulty":"hard","questionHi":"सिंधु, सतलुज और ब्रह्मपुत्र नदियाँ हिमालय को काटती गहरी घाटियाँ बनाती हैं और पर्वत से पुरानी हैं। इनके प्रवाह मार्ग किसके उदाहरण हैं?","optionsHi":["जालीदार अपवाह","वृक्षाकार अपवाह","पूर्ववर्ती अपवाह","अध्यारोपित अपवाह"],"explanationHi":"पूर्ववर्ती नदियाँ अपना मार्ग बनाए रखती हैं जबकि पर्वत उनके आर-पार उठता है, और भूमि के उठने के साथ घाटियाँ काटती हैं। अध्यारोपित नदियाँ किसी आवरण चट्टान से नीचे दबी संरचना पर उतर आती हैं, जैसे प्राचीन विंध्य वलनों के आर-पार चंबल।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-151","question":"Which of the following pairs of valley and river is NOT correct?","options":["Kashmir valley: Jhelum","Kullu valley: Beas","Nubra valley: Shyok","Kangra valley: Ravi"],"answer":3,"explanation":"The Kangra valley lies along the Beas, below the Dhauladhar range, while the Chamba valley is on the Ravi. Kullu is on the Beas, Nubra on the Shyok and the Kashmir valley on the Jhelum.","difficulty":"very-hard","questionHi":"घाटी और नदी के निम्नलिखित युग्मों में से कौन-सा सही नहीं है?","optionsHi":["कश्मीर घाटी: झेलम","कुल्लू घाटी: ब्यास","नुब्रा घाटी: श्योक","कांगड़ा घाटी: रावी"],"explanationHi":"कांगड़ा घाटी धौलाधार श्रेणी के नीचे ब्यास के किनारे है, जबकि चंबा घाटी रावी पर है। कुल्लू ब्यास पर, नुब्रा श्योक पर और कश्मीर घाटी झेलम पर है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-152","question":"Match the glacier with its location. A. Zemu  B. Pindari  C. Milam  D. Siachen. 1. Kumaon, in the Pindar basin  2. Kumaon, in the Gori Ganga basin  3. Karakoram  4. Sikkim, below Kangchenjunga","options":["A-4, B-1, C-2, D-3","A-4, B-2, C-1, D-3","A-4, B-1, C-3, D-2","A-1, B-4, C-2, D-3"],"answer":0,"explanation":"The Zemu glacier flows from Kangchenjunga in Sikkim, Pindari feeds the Pindar river, Milam the Gori Ganga, both in Kumaon, and Siachen lies in the Karakoram. Pindari and Milam are easily swapped.","difficulty":"very-hard","questionHi":"हिमनद का उसके स्थान से मिलान कीजिए। A. ज़ेमू  B. पिंडारी  C. मिलम  D. सियाचिन। 1. कुमाऊँ, पिंडर बेसिन में  2. कुमाऊँ, गोरी गंगा बेसिन में  3. काराकोरम  4. सिक्किम, कंचनजंगा के नीचे","optionsHi":["A-4, B-1, C-2, D-3","A-4, B-2, C-1, D-3","A-4, B-1, C-3, D-2","A-1, B-4, C-2, D-3"],"explanationHi":"ज़ेमू हिमनद सिक्किम में कंचनजंगा से निकलता है, पिंडारी पिंडर नदी को और मिलम गोरी गंगा को जल देता है, दोनों कुमाऊँ में हैं, और सियाचिन काराकोरम में है। पिंडारी और मिलम की अदला-बदली आसान है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-153","question":"Along the Manali-Leh road, travelling from Manali northwards, which is the correct order of these passes? 1. Tanglang La  2. Rohtang La  3. Baralacha La  4. Lachulung La","options":["2, 3, 1, 4","2, 3, 4, 1","3, 2, 4, 1","2, 4, 3, 1"],"answer":1,"explanation":"Going from Manali one crosses Rohtang La, then Baralacha La, Nakee La, Lachulung La and finally Tanglang La, before descending to the Indus at Upshi. Baralacha lies before Lachulung.","difficulty":"very-hard","questionHi":"मनाली–लेह मार्ग पर मनाली से उत्तर की ओर चलते हुए इन दर्रों का सही क्रम क्या है? 1. तंगलांग ला  2. रोहतांग ला  3. बारालाचा ला  4. लाचुलुंग ला","optionsHi":["2, 3, 1, 4","2, 3, 4, 1","3, 2, 4, 1","2, 4, 3, 1"],"explanationHi":"मनाली से चलने पर पहले रोहतांग ला, फिर बारालाचा ला, नकी ला, लाचुलुंग ला और अंत में तंगलांग ला आता है, जिसके बाद उपशी में सिंधु तक उतराई है। बारालाचा, लाचुलुंग से पहले आता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-154","question":"In the Karnataka plateau, the hilly, forested western region with heavy rainfall near the Western Ghats is called the:","options":["Bayalu Seeme","Maidan","Malnad","Mahabaleshwar"],"answer":2,"explanation":"Malnad is the rugged western part of the Karnataka plateau, with dense forest and coffee estates. The eastern part, with low rolling hills and a drier climate, is the Maidan or Bayalu Seeme.","difficulty":"moderate","questionHi":"कर्नाटक पठार में पश्चिमी घाट के निकट का पहाड़ी, वनाच्छादित और भारी वर्षा वाला पश्चिमी क्षेत्र क्या कहलाता है?","optionsHi":["बयालु सीमे","मैदान","मलनाड","महाबलेश्वर"],"explanationHi":"मलनाड कर्नाटक पठार का ऊबड़-खाबड़ पश्चिमी भाग है, जहाँ घने वन और कॉफी बागान हैं। नीची लहरदार पहाड़ियों और शुष्क जलवायु वाला पूर्वी भाग मैदान या बयालु सीमे है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-physical-india-155","question":"The highest peak of the Eastern Ghats, Arma Konda (Jindhagada), is in:","options":["Odisha, Mahendragiri range","Tamil Nadu, Shevaroy hills","Telangana, near Khammam","Andhra Pradesh"],"answer":3,"explanation":"Arma Konda in the Visakhapatnam region of Andhra Pradesh is the highest point of the Eastern Ghats, at about 1,680 m. Mahendragiri in Odisha is another high peak, but lower.","difficulty":"very-hard","questionHi":"पूर्वी घाट की सबसे ऊँची चोटी, अरमा कोंडा (जिंधागड़ा), कहाँ स्थित है?","optionsHi":["ओडिशा, महेंद्रगिरि श्रेणी","तमिलनाडु, शेवरॉय पहाड़ियाँ","तेलंगाना, खम्मम के निकट","आंध्र प्रदेश"],"explanationHi":"आंध्र प्रदेश के विशाखापत्तनम क्षेत्र का अरमा कोंडा पूर्वी घाट का सबसे ऊँचा बिंदु है, जो लगभग 1,680 m है। ओडिशा का महेंद्रगिरि एक अन्य ऊँची चोटी है, पर कम ऊँची।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-156","question":"Saddle Peak, the highest point of the Andaman and Nicobar Islands, is in:","options":["North Andaman","South Andaman","Middle Andaman","Great Nicobar"],"answer":0,"explanation":"Saddle Peak (about 737 m) is in North Andaman. Mount Thullier on Great Nicobar, at about 642 m, is the highest point of the Nicobar group.","difficulty":"hard","questionHi":"अंडमान और निकोबार द्वीपसमूह का सर्वोच्च बिंदु, सैडल पीक, कहाँ स्थित है?","optionsHi":["उत्तरी अंडमान","दक्षिणी अंडमान","मध्य अंडमान","ग्रेट निकोबार"],"explanationHi":"सैडल पीक (लगभग 737 m) उत्तरी अंडमान में है। ग्रेट निकोबार का माउंट थुलियर, लगभग 642 m, निकोबार समूह का सर्वोच्च बिंदु है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-157","question":"The onset of the south-west monsoon over Kerala is closely linked to which change in the upper air circulation?","options":["The Tibetan plateau cools sharply in early summer and a large cold anticyclone spreads over the whole peninsula","The westerly jet stream shifts north of the Himalaya and the tropical easterly jet sets in over the peninsula","The easterly jet stream shifts south over the Indian Ocean and the westerly jet strengthens over Kerala","The subtropical westerly jet stream moves south of the Himalaya and weakens over the Tibetan plateau"],"answer":1,"explanation":"In early summer the westerly jet withdraws north of the Himalaya and the Tibetan plateau heats up, which sets up the tropical easterly jet over peninsular India and helps the monsoon burst. The plateau becomes a heat source, not a cold one.","difficulty":"very-hard","questionHi":"केरल पर दक्षिण-पश्चिम मानसून का आगमन ऊपरी वायु परिसंचरण के किस परिवर्तन से निकट रूप से जुड़ा है?","optionsHi":["तिब्बती पठार तेज़ी से ठंडा हो जाता है और प्रायद्वीप पर ठंडा प्रतिचक्रवात फैल जाता है","पछुआ जेट धारा हिमालय के उत्तर में खिसक जाती है और प्रायद्वीप पर उष्णकटिबंधीय पूर्वी जेट धारा स्थापित होती है","पूर्वी जेट धारा हिंद महासागर के ऊपर दक्षिण की ओर खिसक जाती है और केरल पर पछुआ जेट धारा प्रबल होती है","उपोष्णकटिबंधीय पछुआ जेट धारा हिमालय के दक्षिण में आ जाती है और तिब्बती पठार पर कमज़ोर पड़ती है"],"explanationHi":"गर्मी के आरंभ में पछुआ जेट धारा हिमालय के उत्तर में हट जाती है और तिब्बती पठार गर्म हो जाता है, जिससे प्रायद्वीपीय भारत पर उष्णकटिबंधीय पूर्वी जेट धारा बनती है और मानसून का प्रस्फोट होता है। पठार गर्मी का स्रोत बनता है, ठंडा नहीं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-158","question":"The Southern Oscillation Index, used to track El Nino and its link to the Indian monsoon, is based on the difference in sea-level pressure between:","options":["Santiago and Perth","Cape Town and Colombo","Tahiti and Darwin","Honolulu and Manila"],"answer":2,"explanation":"The SOI compares the pressure at Tahiti in the east Pacific with Darwin in northern Australia. A persistent negative SOI accompanies El Nino, when the weaker Walker circulation tends to give a poorer Indian monsoon.","difficulty":"hard","questionHi":"दक्षिणी दोलन सूचकांक, जिससे अल नीनो और भारतीय मानसून से उसके संबंध का पता लगाया जाता है, किन दो स्थानों के समुद्र तल दाब के अंतर पर आधारित है?","optionsHi":["सैंटियागो और पर्थ","केप टाउन और कोलंबो","ताहिती और डार्विन","होनोलूलू और मनीला"],"explanationHi":"SOI पूर्वी प्रशांत के ताहिती और उत्तरी ऑस्ट्रेलिया के डार्विन के दाब की तुलना करता है। लगातार ऋणात्मक SOI अल नीनो के साथ आता है, जब कमज़ोर वॉकर परिसंचरण से भारतीय मानसून प्रायः कमज़ोर रहता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-159","question":"A 'positive' Indian Ocean Dipole is usually favourable to the Indian monsoon because during it:","options":["The Bay of Bengal cools while the Arabian Sea warms sharply near Sri Lanka","The whole Indian Ocean cools evenly, strengthening the pressure gradient","The eastern Indian Ocean is warmer than the western, pushing moist air towards Africa","The western Indian Ocean is warmer than the eastern, drawing more moist air towards India"],"answer":3,"explanation":"A positive IOD has warmer water in the west near Africa and cooler water off Sumatra, which strengthens the cross-equatorial flow towards India. A negative IOD reverses this and can reduce rain.","difficulty":"very-hard","questionHi":"'धनात्मक' हिंद महासागर द्विध्रुव सामान्यतः भारतीय मानसून के लिए अनुकूल होता है क्योंकि उस समय:","optionsHi":["बंगाल की खाड़ी ठंडी होती है जबकि श्रीलंका के निकट अरब सागर तेज़ी से गर्म होता है","पूरा हिंद महासागर समान रूप से ठंडा होता है, जिससे दाब प्रवणता मज़बूत होती है","पूर्वी हिंद महासागर पश्चिमी की अपेक्षा अधिक गर्म होता है, जिससे आर्द्र हवा अफ्रीका की ओर धकेली जाती है","पश्चिमी हिंद महासागर पूर्वी की अपेक्षा अधिक गर्म होता है, जिससे भारत की ओर अधिक आर्द्र हवा खिंचती है"],"explanationHi":"धनात्मक IOD में अफ्रीका के निकट पश्चिम का जल गर्म और सुमात्रा के पास ठंडा होता है, जिससे भारत की ओर विषुवतीय पार प्रवाह मज़बूत होता है। ऋणात्मक IOD इसे उलट देता है और वर्षा घटा सकता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-160","question":"Match the Koeppen climate type with the region of India where NCERT places it. A. Amw  B. As  C. Cwg  D. BWhw. 1. Western Rajasthan  2. Coromandel coast  3. Ganga plain  4. West coast south of Mumbai","options":["A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":0,"explanation":"Amw (monsoon with a short dry season) fits the west coast south of Mumbai, As (dry summer, winter rain) the Coromandel coast, Cwg (monsoon with a dry winter) the Ganga plain, and BWhw (hot desert) western Rajasthan.","difficulty":"very-hard","questionHi":"कोपेन के जलवायु प्रकार का उस भारतीय क्षेत्र से मिलान कीजिए जहाँ NCERT उसे रखता है। A. Amw  B. As  C. Cwg  D. BWhw। 1. पश्चिमी राजस्थान  2. कोरोमंडल तट  3. गंगा का मैदान  4. मुंबई के दक्षिण का पश्चिमी तट","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"Amw (छोटी शुष्क ऋतु वाला मानसून) मुंबई के दक्षिण के पश्चिमी तट के लिए, As (शुष्क ग्रीष्म, शीत वर्षा) कोरोमंडल तट के लिए, Cwg (शुष्क शीत वाला मानसून) गंगा के मैदान के लिए और BWhw (गर्म मरुस्थल) पश्चिमी राजस्थान के लिए उपयुक्त है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-161","question":"Arrange these natural vegetation types of India in decreasing order of the annual rainfall they need: 1. Tropical thorn forest  2. Tropical evergreen forest  3. Tropical dry deciduous forest  4. Tropical moist deciduous forest","options":["2, 3, 4, 1","2, 4, 3, 1","4, 2, 3, 1","2, 4, 1, 3"],"answer":1,"explanation":"NCERT gives evergreen forests above 200 cm, moist deciduous 100-200 cm, dry deciduous 70-100 cm, and thorn forest below 70 cm of rain.","difficulty":"hard","questionHi":"भारत की इन प्राकृतिक वनस्पति प्रकारों को उनके लिए आवश्यक वार्षिक वर्षा के घटते क्रम में व्यवस्थित कीजिए: 1. उष्णकटिबंधीय कंटीले वन  2. उष्णकटिबंधीय सदाबहार वन  3. उष्णकटिबंधीय शुष्क पर्णपाती वन  4. उष्णकटिबंधीय आर्द्र पर्णपाती वन","optionsHi":["2, 3, 4, 1","2, 4, 3, 1","4, 2, 3, 1","2, 4, 1, 3"],"explanationHi":"NCERT के अनुसार सदाबहार वनों को 200 cm से अधिक, आर्द्र पर्णपाती को 100-200 cm, शुष्क पर्णपाती को 70-100 cm और कंटीले वनों को 70 cm से कम वर्षा चाहिए।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-162","question":"The Narmada and Tapi flow westwards in long, straight courses and form estuaries rather than deltas mainly because they:","options":["Drain a region of heavy monsoon rainfall that washes the sediment far out to deep water beyond the shelf","Flow over soft alluvium that is eroded away almost as fast as it is deposited by the river","Flow through rift valleys formed by faulting and have little sediment left to build deltas","Flow down the steep western slope of the Western Ghats directly into the sea"],"answer":2,"explanation":"These two rivers occupy fault-guided troughs (grabens) between the Vindhyas and Satpuras and the Satpuras and Ajanta, so their courses are straight and, with their load already dropped in their long trough, they enter the sea in estuaries.","difficulty":"very-hard","questionHi":"नर्मदा और तापी लंबे, सीधे मार्गों में पश्चिम की ओर बहती हैं और डेल्टा की जगह ज्वारनदमुख बनाती हैं, मुख्यतः क्योंकि वे:","optionsHi":["भारी मानसूनी वर्षा वाले क्षेत्र का जल ले जाती हैं जो अवसाद को गहरे जल में बहा देता है","मुलायम जलोढ़ पर बहती हैं जो जमा होने जितनी ही तेज़ी से कटता है","भ्रंश से बनी भ्रंश घाटियों में बहती हैं और डेल्टा बनाने के लिए उनमें कम अवसाद बचता है","पश्चिमी घाट की तीव्र पश्चिमी ढाल से सीधे समुद्र में उतरती हैं"],"explanationHi":"ये दोनों नदियाँ विंध्य–सतपुड़ा और सतपुड़ा–अजंता के बीच भ्रंश-निर्देशित द्रोणियों (ग्रेबेन) में हैं, इसलिए इनके मार्ग सीधे हैं और अपनी लंबी द्रोणी में अवसाद छोड़ देने के कारण ये ज्वारनदमुख के रूप में समुद्र में मिलती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-163","question":"The seismic zoning map of India, as revised by the Bureau of Indian Standards in 2002, divides the country into:","options":["Six zones, I to VI, with VI the most severe","Five zones, I to V, with I the most severe","Four zones, I to IV, with IV the most severe","Four zones, II to V, with V the most severe"],"answer":3,"explanation":"The 2002 revision merged the old Zone I into Zone II, leaving four zones: II, III, IV and V. Zone V, with the Kashmir valley, parts of the Himalaya and north-east, Kachchh and the Andaman and Nicobar Islands, is the highest-risk zone.","difficulty":"hard","questionHi":"भारतीय मानक ब्यूरो द्वारा 2002 में संशोधित भारत का भूकंपीय क्षेत्रण मानचित्र देश को किन क्षेत्रों में बाँटता है?","optionsHi":["छह क्षेत्र, I से VI, जिनमें VI सर्वाधिक गंभीर है","पाँच क्षेत्र, I से V, जिनमें I सर्वाधिक गंभीर है","चार क्षेत्र, I से IV, जिनमें IV सर्वाधिक गंभीर है","चार क्षेत्र, II से V, जिनमें V सर्वाधिक गंभीर है"],"explanationHi":"2002 के संशोधन में पुराने क्षेत्र I को क्षेत्र II में मिला दिया गया, जिससे चार क्षेत्र बचे: II, III, IV और V। कश्मीर घाटी, हिमालय और पूर्वोत्तर के भागों, कच्छ और अंडमान-निकोबार वाला क्षेत्र V सर्वाधिक जोखिम वाला है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-164","question":"The Latur (Killari) earthquake of 30 September 1993 surprised scientists mainly because it:","options":["Struck the stable peninsular shield, far from any active plate boundary","Was caused by the subduction of the Indian plate beneath Burma along the Arakan arc","Was triggered by the filling of a large dam in the Western Ghats","Occurred along the Himalayan thrust belt at shallow depth"],"answer":0,"explanation":"Latur lies in the Deccan shield, a stable continental region far from the Himalayan plate boundary, so a damaging intraplate earthquake of about magnitude 6.2 was unexpected. Old rift structures there may have been reactivated.","difficulty":"hard","questionHi":"30 सितंबर 1993 का लातूर (किल्लारी) भूकंप वैज्ञानिकों के लिए मुख्यतः क्यों आश्चर्यजनक था?","optionsHi":["यह किसी सक्रिय प्लेट सीमा से दूर स्थिर प्रायद्वीपीय कवच पर आया","यह भारतीय प्लेट के बर्मा के नीचे क्षेपण से उत्पन्न हुआ","यह पश्चिमी घाट के एक बड़े बाँध के भरने से प्रेरित हुआ","यह हिमालयी क्षेप पट्टी पर उथली गहराई में आया"],"explanationHi":"लातूर दक्कन कवच में है, जो हिमालयी प्लेट सीमा से दूर स्थिर महाद्वीपीय क्षेत्र है, इसलिए लगभग 6.2 परिमाण का विनाशकारी अंतःप्लेट भूकंप अप्रत्याशित था। वहाँ की पुरानी भ्रंश संरचनाएँ पुनः सक्रिय हुई हो सकती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-165","question":"Arrange these Indian earthquakes in chronological order: 1. Latur  2. Bhuj (Gujarat)  3. Chamoli  4. Uttarkashi","options":["4, 1, 2, 3","4, 1, 3, 2","4, 3, 1, 2","1, 4, 3, 2"],"answer":1,"explanation":"Uttarkashi struck in October 1991, Latur in September 1993, Chamoli in March 1999 and Bhuj on 26 January 2001. The Garhwal events (Uttarkashi, Chamoli) are often confused in order.","difficulty":"hard","questionHi":"इन भारतीय भूकंपों को कालक्रम में व्यवस्थित कीजिए: 1. लातूर  2. भुज (गुजरात)  3. चमोली  4. उत्तरकाशी","optionsHi":["4, 1, 2, 3","4, 1, 3, 2","4, 3, 1, 2","1, 4, 3, 2"],"explanationHi":"उत्तरकाशी अक्टूबर 1991 में, लातूर सितंबर 1993 में, चमोली मार्च 1999 में और भुज 26 जनवरी 2001 को आया। गढ़वाल की घटनाओं (उत्तरकाशी, चमोली) का क्रम प्रायः भ्रमित किया जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-166","question":"In India Meteorological Department usage, a 'cloudburst' is generally taken as rainfall of about:","options":["100 mm per day or more over a district","50 mm per hour or more over a large area of 500 sq km","100 mm per hour or more over a small area of 20-30 sq km","25 mm per hour or more for two continuous hours"],"answer":2,"explanation":"IMD describes a cloudburst as sudden, intense rain of 100 mm or more per hour over a small area of roughly 20-30 sq km. Such events in the Himalaya cause flash floods and landslides.","difficulty":"hard","questionHi":"भारत मौसम विज्ञान विभाग के प्रयोग में 'बादल फटना' सामान्यतः लगभग किस वर्षा को माना जाता है?","optionsHi":["एक जिले में प्रतिदिन 100 mm या अधिक","500 वर्ग km के बड़े क्षेत्र में प्रति घंटे 50 mm या अधिक","20-30 वर्ग km के छोटे क्षेत्र में प्रति घंटे 100 mm या अधिक","लगातार दो घंटे तक प्रति घंटे 25 mm या अधिक"],"explanationHi":"IMD बादल फटने को लगभग 20-30 वर्ग km के छोटे क्षेत्र में प्रति घंटे 100 mm या अधिक की अचानक तीव्र वर्षा बताता है। हिमालय में ऐसी घटनाएँ अचानक बाढ़ और भूस्खलन लाती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-167","question":"For a 'heat wave' to be declared in the plains, the India Meteorological Department requires the actual maximum temperature to reach at least:","options":["45 °C in the plains, with a rise of 2 °C above normal","35 °C in the plains, with a rise of 8 °C above normal","40 °C in the plains, with a rise of 10 °C above normal","40 °C in the plains, with a rise of 4.5-6.4 °C above normal"],"answer":3,"explanation":"IMD's criterion for a heat wave is a maximum of 40 °C or more in the plains (30 °C in the hills), plus a departure from normal of 4.5-6.4 °C; a departure above 6.4 °C marks a severe heat wave.","difficulty":"very-hard","questionHi":"मैदानी क्षेत्रों में 'लू (ऊष्ण लहर)' घोषित करने के लिए भारत मौसम विज्ञान विभाग के अनुसार वास्तविक अधिकतम तापमान कम से कम कितना होना चाहिए?","optionsHi":["मैदानों में 45 °C, सामान्य से 2 °C की वृद्धि के साथ","मैदानों में 35 °C, सामान्य से 8 °C की वृद्धि के साथ","मैदानों में 40 °C, सामान्य से 10 °C की वृद्धि के साथ","मैदानों में 40 °C, सामान्य से 4.5-6.4 °C की वृद्धि के साथ"],"explanationHi":"IMD का लू का मानदंड मैदानों में 40 °C या अधिक (पहाड़ियों में 30 °C) का अधिकतम तापमान और सामान्य से 4.5-6.4 °C का विचलन है; 6.4 °C से अधिक विचलन गंभीर लू दर्शाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-168","question":"In India Meteorological Department terms, the south-west monsoon season rainfall is called 'normal' when it is within what range of the long period average (LPA)?","options":["96 to 104 per cent","100 to 110 per cent","75 to 125 per cent","90 to 110 per cent"],"answer":0,"explanation":"IMD treats 96-104% of the LPA as normal, 90-96% as below normal, under 90% as deficient, 104-110% as above normal and over 110% as excess.","difficulty":"hard","questionHi":"भारत मौसम विज्ञान विभाग के शब्दों में, दक्षिण-पश्चिम मानसून ऋतु की वर्षा दीर्घ अवधि औसत (LPA) के किस परास में होने पर 'सामान्य' कहलाती है?","optionsHi":["96 से 104 प्रतिशत","100 से 110 प्रतिशत","75 से 125 प्रतिशत","90 से 110 प्रतिशत"],"explanationHi":"IMD LPA के 96-104% को सामान्य, 90-96% को सामान्य से कम, 90% से कम को अपर्याप्त, 104-110% को सामान्य से अधिक और 110% से अधिक को अत्यधिक मानता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-169","question":"The withdrawal of the south-west monsoon from India normally begins from which region?","options":["The Ganga delta in the east","West Rajasthan and the north-west","Kerala and the south-west coast","Assam and the north-east"],"answer":1,"explanation":"The monsoon arrives last in west Rajasthan and leaves it first, around mid-September, then retreats southwards as the pressure over north India rises. The south-west coast is the last to be left.","difficulty":"moderate","questionHi":"भारत से दक्षिण-पश्चिम मानसून की वापसी सामान्यतः किस क्षेत्र से शुरू होती है?","optionsHi":["पूर्व में गंगा डेल्टा","पश्चिमी राजस्थान और उत्तर-पश्चिम","केरल और दक्षिण-पश्चिमी तट","असम और पूर्वोत्तर"],"explanationHi":"मानसून पश्चिमी राजस्थान में सबसे अंत में पहुँचता है और वहाँ से सबसे पहले, लगभग मध्य सितंबर में, लौटता है, फिर उत्तर भारत में दाब बढ़ने से दक्षिण की ओर हटता है। दक्षिण-पश्चिमी तट को वह सबसे अंत में छोड़ता है।","source":"SSC CGL · State PCS"},
  {"id":"geo-physical-india-170","question":"In the northern Indian Ocean the Somali current:","options":["Flows south-west all year round along the African coast, bringing cold water to Arabia","Flows north-west in summer, bringing warm water to the Arabian Sea","Flows north-east in the south-west monsoon and reverses to south-west in winter","Flows north-east in the winter monsoon and reverses to south-west in the summer monsoon"],"answer":2,"explanation":"The currents of the northern Indian Ocean reverse with the monsoon wind. The Somali current runs strongly north-east off Africa in summer, causing upwelling of cold water, and runs south-west in the winter north-east monsoon.","difficulty":"very-hard","questionHi":"उत्तरी हिंद महासागर में सोमाली धारा:","optionsHi":["पूरे वर्ष अफ्रीकी तट के साथ दक्षिण-पश्चिम की ओर बहती है","ग्रीष्म में उत्तर-पश्चिम की ओर बहती है और अरब सागर में गर्म जल लाती है","दक्षिण-पश्चिम मानसून में उत्तर-पूर्व की ओर बहती है और शीत ऋतु में उलटकर दक्षिण-पश्चिम की ओर बहती है","शीत ऋतु में उत्तर-पूर्व की ओर बहती है और ग्रीष्म में उलटकर दक्षिण-पश्चिम की ओर बहती है"],"explanationHi":"उत्तरी हिंद महासागर की धाराएँ मानसूनी पवन के साथ उलट जाती हैं। सोमाली धारा ग्रीष्म में अफ्रीका के तट से तेज़ी से उत्तर-पूर्व बहती है और ठंडे जल का उत्क्षेपण करती है, तथा शीतकालीन उत्तर-पूर्वी मानसून में दक्षिण-पश्चिम बहती है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-171","question":"Arrange these rock systems of India from oldest to youngest: 1. Gondwana  2. Vindhyan  3. Dharwar  4. Deccan Trap","options":["3, 2, 4, 1","2, 3, 1, 4","3, 1, 2, 4","3, 2, 1, 4"],"answer":3,"explanation":"The Dharwar rocks are among the oldest metamorphic systems, followed by the Vindhyan sediments, the Gondwana beds of coal (Carboniferous to Jurassic), and the Deccan Trap lavas at the end of the Cretaceous.","difficulty":"hard","questionHi":"भारत की इन शैल प्रणालियों को सबसे पुरानी से सबसे नई के क्रम में व्यवस्थित कीजिए: 1. गोंडवाना  2. विंध्यन  3. धारवाड़  4. दक्कन ट्रैप","optionsHi":["3, 2, 4, 1","2, 3, 1, 4","3, 1, 2, 4","3, 2, 1, 4"],"explanationHi":"धारवाड़ चट्टानें सबसे प्राचीन कायांतरित प्रणालियों में हैं, उसके बाद विंध्यन अवसाद, कोयले वाली गोंडवाना परतें (कार्बोनीफेरस से जुरासिक) और क्रिटेशियस के अंत में दक्कन ट्रैप के लावा आते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-172","question":"Which of these correctly describes the Vindhyan system of rocks?","options":["Horizontal sandstones, limestones and shales that give building stone and the diamonds of Panna","Coal-bearing sandstones and shales laid down in river valleys of the peninsula","Tightly folded metamorphic schists and gneisses, rich in iron ore, that also hold the gold of Kolar and Hutti","Black basalt lava flows that weather into regur soil"],"answer":0,"explanation":"The Vindhyan system is made of nearly horizontal, unmetamorphosed sandstones, limestones and shales, widely used as building stone (Sanchi, Red Fort) and hosting the diamond-bearing conglomerates of Panna. Gold schists are Dharwar, coal is Gondwana, and basalt is Deccan Trap.","difficulty":"hard","questionHi":"इनमें से कौन-सा विंध्यन शैल प्रणाली का सही वर्णन करता है?","optionsHi":["क्षैतिज बलुआ पत्थर, चूना पत्थर और शेल, जो निर्माण पत्थर और पन्ना के हीरे देते हैं","प्रायद्वीप की नदी घाटियों में जमे कोयला-धारक बलुआ पत्थर और शेल","वलित कायांतरित शिस्ट, जिनमें कोलार और हुट्टी का सोना है","काला बेसाल्ट लावा प्रवाह जो अपक्षयित होकर रेगुर मिट्टी बनाता है"],"explanationHi":"विंध्यन प्रणाली लगभग क्षैतिज, अकायांतरित बलुआ पत्थर, चूना पत्थर और शेल की है, जो निर्माण पत्थर (साँची, लाल किला) के रूप में व्यापक प्रयुक्त है और पन्ना के हीरा-धारक संगुटिकाश्म रखती है। स्वर्ण शिस्ट धारवाड़ है, कोयला गोंडवाना और बेसाल्ट दक्कन ट्रैप।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-173","question":"The Deccan Traps are linked to a mantle plume that is now beneath Réunion island, and their main eruptions occurred around the time of the:","options":["Carboniferous period, about 330 million years ago","Cretaceous-Palaeogene boundary, about 66 million years ago","Collision of India with Eurasia, about 50 million years ago","Beginning of the Pleistocene, about 2.5 million years ago"],"answer":1,"explanation":"As the Indian plate drifted north over the Réunion hotspot, huge basalt floods covered large parts of the peninsula about 66 million years ago, close to the end-Cretaceous mass extinction. The Himalayan collision came some 15 million years later.","difficulty":"very-hard","questionHi":"दक्कन ट्रैप का संबंध उस मैंटल प्लूम से है जो अब रीयूनियन द्वीप के नीचे है, और उनके मुख्य उद्गार किस समय के आसपास हुए?","optionsHi":["कार्बोनीफेरस काल, लगभग 33 करोड़ वर्ष पहले","क्रिटेशियस–पैलियोजीन सीमा, लगभग 6.6 करोड़ वर्ष पहले","भारत की यूरेशिया से टक्कर, लगभग 5 करोड़ वर्ष पहले","प्लीस्टोसीन का आरंभ, लगभग 25 लाख वर्ष पहले"],"explanationHi":"जैसे ही भारतीय प्लेट रीयूनियन तप्त स्थल के ऊपर से उत्तर की ओर खिसकी, लगभग 6.6 करोड़ वर्ष पहले विशाल बेसाल्ट प्रवाहों ने प्रायद्वीप के बड़े भाग को ढक दिया, जो क्रिटेशियस के अंत के सामूहिक विलोपन के निकट था। हिमालयी टक्कर लगभग 1.5 करोड़ वर्ष बाद आई।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-174","question":"Which of these landmasses was NOT part of the ancient supercontinent Gondwana?","options":["Africa","Peninsular India","North America","Antarctica"],"answer":2,"explanation":"Gondwana comprised South America, Africa, Antarctica, Australia, Peninsular India and Arabia. North America, with Europe and most of Asia, belonged to the northern supercontinent Laurasia.","difficulty":"moderate","questionHi":"इनमें से कौन-सा भूखंड प्राचीन महाद्वीप गोंडवाना का भाग नहीं था?","optionsHi":["अफ्रीका","प्रायद्वीपीय भारत","उत्तरी अमेरिका","अंटार्कटिका"],"explanationHi":"गोंडवाना में दक्षिण अमेरिका, अफ्रीका, अंटार्कटिका, ऑस्ट्रेलिया, प्रायद्वीपीय भारत और अरब शामिल थे। यूरोप और अधिकांश एशिया के साथ उत्तरी अमेरिका उत्तरी महाद्वीप लॉरेशिया का भाग था।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-physical-india-175","question":"Although the Himalaya lie along a plate boundary, they have no active volcanoes because:","options":["The cold water of the old Tethys sea cooled the magma before it could reach the surface","The Indian plate is moving too slowly to generate enough frictional heat to melt crust at depth","The Himalaya are made of folded sedimentary rocks, and sedimentary rocks cannot melt at any depth","Two continental plates collided, and the buoyant continental crust could not sink deep enough to melt"],"answer":3,"explanation":"At ocean-continent boundaries the sinking oceanic slab melts to feed volcanoes. At a continent-continent collision both plates are too light to subduct far, so the crust crumples upwards into fold mountains instead.","difficulty":"hard","questionHi":"यद्यपि हिमालय एक प्लेट सीमा पर है, फिर भी उसमें कोई सक्रिय ज्वालामुखी नहीं है, क्योंकि:","optionsHi":["टेथिस सागर के जल ने मैग्मा को सतह पर पहुँचने से पहले ठंडा कर दिया","भारतीय प्लेट इतनी धीमी गति से चल रही है कि ताप उत्पन्न नहीं होता","हिमालय अवसादी चट्टानों का बना है जो पिघल नहीं सकतीं","दो महाद्वीपीय प्लेटें टकराईं और हल्की महाद्वीपीय भूपर्पटी इतनी गहरी नहीं धँस सकी कि पिघले"],"explanationHi":"महासागर–महाद्वीप सीमाओं पर धँसती महासागरीय पट्टी पिघलकर ज्वालामुखियों को पोषित करती है। महाद्वीप–महाद्वीप टक्कर में दोनों प्लेटें इतनी हल्की हैं कि गहरी नहीं धँस पातीं, इसलिए भूपर्पटी ऊपर की ओर सिकुड़कर वलित पर्वत बनाती है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-176","question":"The Shiwalik range is made mostly of:","options":["Unconsolidated sands, gravels and clays washed down from the rising Himalaya","Hard crystalline granite and gneiss forming the elevated core of the Himalaya","Basaltic lava that flowed north from the Deccan Traps over the plains","Marine limestones of the Tethys sea, tightly folded into overturned nappes"],"answer":0,"explanation":"The Shiwaliks are the youngest and outermost range, built of molasse: loose sand, gravel and clay eroded from the higher ranges. This is why they are fragile, prone to erosion and cut by seasonal streams (chos).","difficulty":"hard","questionHi":"शिवालिक श्रेणी मुख्यतः किससे बनी है?","optionsHi":["उठते हुए हिमालय से बहकर आई असंपिंडित रेत, बजरी और चिकनी मिट्टी","हिमालय के केंद्रीय भाग का कठोर ग्रेनाइट और नाइस","दक्कन ट्रैप का बेसाल्टी लावा","टेथिस सागर के समुद्री चूना पत्थर, कसकर वलित"],"explanationHi":"शिवालिक सबसे नई और सबसे बाहरी श्रेणी है, जो मोलास से बनी है: ऊँची श्रेणियों से कटकर आई ढीली रेत, बजरी और चिकनी मिट्टी। इसीलिए वह भंगुर है, अपरदन की शिकार है और मौसमी धाराओं (चो) से कटी है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-177","question":"Consider these statements about the Himalaya. I. The arc is about 2,400 km long. II. It is about 400 km wide in Kashmir and about 150 km wide in Arunachal Pradesh. III. The altitudinal variations are greater in the western half than in the eastern half. IV. The arc is convex towards the north. How many of these are correct?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is wrong, since altitudinal variations are greater in the eastern half, and IV is wrong, since the arc bulges southwards, towards the plains.","difficulty":"hard","questionHi":"हिमालय के बारे में इन कथनों पर विचार कीजिए। I. चाप लगभग 2,400 km लंबा है। II. यह कश्मीर में लगभग 400 km चौड़ा और अरुणाचल प्रदेश में लगभग 150 km चौड़ा है। III. ऊँचाई संबंधी भिन्नताएँ पश्चिमी भाग में पूर्वी भाग से अधिक हैं। IV. चाप उत्तर की ओर उत्तल है। इनमें से कितने सही हैं?","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है, क्योंकि ऊँचाई संबंधी भिन्नताएँ पूर्वी भाग में अधिक हैं, और IV गलत है, क्योंकि चाप दक्षिण की ओर, मैदानों की ओर, उभरा हुआ है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-178","question":"Crescent-shaped dunes with their horns pointing downwind, which migrate across the open sand plains of the Thar, are called:","options":["Star dunes","Barchans","Transverse ridges","Seifs"],"answer":1,"explanation":"Barchans form where sand is limited and wind direction is steady, giving a crescent with horns pointing the way the wind blows. Seifs are long, sharp-crested dunes parallel to the wind, and star dunes form under shifting winds.","difficulty":"hard","questionHi":"अर्धचंद्राकार टिब्बे, जिनके सिरे पवन की दिशा में होते हैं और जो थार के खुले रेतीले मैदानों में खिसकते हैं, क्या कहलाते हैं?","optionsHi":["तारा टिब्बे","बरखान","अनुप्रस्थ कटक","सीफ"],"explanationHi":"बरखान वहाँ बनते हैं जहाँ रेत सीमित और पवन दिशा स्थिर हो, जिससे अर्धचंद्र बनता है जिसके सिरे पवन के बहने की दिशा में होते हैं। सीफ पवन के समानांतर लंबे, तीखे शिखर वाले टिब्बे हैं और तारा टिब्बे बदलती पवनों में बनते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-179","question":"Pulicat lake, a large coastal lagoon, is shared between which two States?","options":["Tamil Nadu and Kerala","Odisha and Andhra Pradesh","Andhra Pradesh and Tamil Nadu","Karnataka and Tamil Nadu together"],"answer":2,"explanation":"Pulicat, the second-largest brackish lagoon in India after Chilika, straddles the border of Andhra Pradesh (Tirupati and Nellore districts) and Tamil Nadu (Tiruvallur), separated from the sea by the Sriharikota barrier island.","difficulty":"hard","questionHi":"पुलिकट झील, जो एक बड़ी तटीय लैगून है, किन दो राज्यों में साझा है?","optionsHi":["तमिलनाडु और केरल","ओडिशा और आंध्र प्रदेश","आंध्र प्रदेश और तमिलनाडु","कर्नाटक और तमिलनाडु दोनों"],"explanationHi":"चिल्का के बाद भारत की दूसरी सबसे बड़ी खारे जल की लैगून पुलिकट आंध्र प्रदेश (तिरुपति और नेल्लोर जिले) तथा तमिलनाडु (तिरुवल्लूर) की सीमा पर फैली है और श्रीहरिकोटा अवरोधी द्वीप से समुद्र से अलग है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-180","question":"The McMahon Line, which most Indian maps follow as the boundary with China in the eastern sector, was drawn at the:","options":["Simla Convention of 1914","Panchsheel Agreement of 1954","Treaty of Amritsar of 1809","Treaty of Sugauli of 1816"],"answer":0,"explanation":"The McMahon Line was negotiated by Sir Henry McMahon at the Simla Convention (1913-14) between Britain, Tibet and China. The Treaty of Sugauli concerned Nepal, and Panchsheel was the 1954 India-China agreement on Tibet trade.","difficulty":"hard","questionHi":"मैकमोहन रेखा, जिसे अधिकांश भारतीय मानचित्र पूर्वी क्षेत्र में चीन के साथ सीमा मानते हैं, किस सम्मेलन में खींची गई थी?","optionsHi":["1914 का शिमला सम्मेलन","1954 का पंचशील समझौता","1809 की अमृतसर संधि","1816 की सुगौली संधि"],"explanationHi":"मैकमोहन रेखा पर सर हेनरी मैकमोहन ने ब्रिटेन, तिब्बत और चीन के बीच शिमला सम्मेलन (1913-14) में बातचीत की थी। सुगौली संधि नेपाल से संबंधित थी और पंचशील तिब्बत व्यापार पर 1954 का भारत-चीन समझौता था।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-181","question":"The boundary between India and China is described in three sectors. Which two States or Union Territories form the middle sector?","options":["Uttarakhand and Sikkim","Himachal Pradesh and Uttarakhand","Sikkim and Arunachal Pradesh together","Ladakh and Himachal Pradesh"],"answer":1,"explanation":"The western sector lies in Ladakh, the middle sector along Himachal Pradesh and Uttarakhand, and the eastern sector along Sikkim and Arunachal Pradesh up to the McMahon Line.","difficulty":"hard","questionHi":"भारत और चीन के बीच की सीमा का वर्णन तीन क्षेत्रों में किया जाता है। मध्य क्षेत्र किन दो राज्यों या संघ राज्यक्षेत्रों से बनता है?","optionsHi":["उत्तराखंड और सिक्किम","हिमाचल प्रदेश और उत्तराखंड","सिक्किम और अरुणाचल प्रदेश दोनों","लद्दाख और हिमाचल प्रदेश"],"explanationHi":"पश्चिमी क्षेत्र लद्दाख में, मध्य क्षेत्र हिमाचल प्रदेश और उत्तराखंड के साथ, और पूर्वी क्षेत्र सिक्किम तथा अरुणाचल प्रदेश के साथ मैकमोहन रेखा तक है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-182","question":"With which neighbouring country does India share its longest land border?","options":["China, along Tibet","Nepal, along the Himalaya","Bangladesh","Pakistan, along Punjab"],"answer":2,"explanation":"The India-Bangladesh border, about 4,100 km, is the longest, running through West Bengal, Assam, Meghalaya, Tripura and Mizoram. China (about 3,500 km) and Pakistan (about 3,300 km) follow.","difficulty":"moderate","questionHi":"भारत अपनी सबसे लंबी स्थल सीमा किस पड़ोसी देश के साथ साझा करता है?","optionsHi":["चीन, तिब्बत के साथ","नेपाल, हिमालय के साथ","बांग्लादेश","पाकिस्तान, पंजाब के साथ"],"explanationHi":"भारत–बांग्लादेश सीमा, लगभग 4,100 km, सबसे लंबी है, जो पश्चिम बंगाल, असम, मेघालय, त्रिपुरा और मिज़ोरम से होकर जाती है। चीन (लगभग 3,500 km) और पाकिस्तान (लगभग 3,300 km) उसके बाद आते हैं।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-physical-india-183","question":"The narrow Siliguri Corridor in West Bengal, which links the north-eastern States with the rest of India, is flanked at its narrowest part by:","options":["Bhutan on the east and Myanmar on the south","Nepal on the west and China on the north","Bhutan on the west and Bangladesh on the south","Nepal on the west and Bangladesh on the south"],"answer":3,"explanation":"The corridor, only about 20-22 km wide at its narrowest, has Nepal to the west and Bangladesh to the south, with Bhutan farther to the north-east. Neither China nor Myanmar touches it.","difficulty":"very-hard","questionHi":"पश्चिम बंगाल का संकरा सिलीगुड़ी गलियारा, जो पूर्वोत्तर राज्यों को शेष भारत से जोड़ता है, अपने सबसे संकरे भाग में किनसे घिरा है?","optionsHi":["पूर्व में भूटान और दक्षिण में म्यांमार","पश्चिम में नेपाल और उत्तर में चीन","पश्चिम में भूटान और दक्षिण में बांग्लादेश","पश्चिम में नेपाल और दक्षिण में बांग्लादेश"],"explanationHi":"यह गलियारा अपने सबसे संकरे भाग में केवल लगभग 20-22 km चौड़ा है, जिसके पश्चिम में नेपाल और दक्षिण में बांग्लादेश है, और भूटान उत्तर-पूर्व में आगे है। चीन या म्यांमार इसे नहीं छूते।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-184","question":"Which is the highest peak lying wholly within India's borders?","options":["Nanda Devi","Kamet","Kangchenjunga","Saser Kangri"],"answer":0,"explanation":"Nanda Devi (7,816 m) in Uttarakhand is the highest peak wholly within India. Kangchenjunga lies on the Sikkim-Nepal border, so it is not entirely Indian, while Kamet (7,756 m) is lower.","difficulty":"very-hard","questionHi":"भारत की सीमाओं के पूर्णतः भीतर स्थित सबसे ऊँची चोटी कौन-सी है?","optionsHi":["नंदा देवी","कामेट","कंचनजंगा","सासेर कांगड़ी"],"explanationHi":"उत्तराखंड की नंदा देवी (7,816 m) पूर्णतः भारत के भीतर की सबसे ऊँची चोटी है। कंचनजंगा सिक्किम–नेपाल सीमा पर है, इसलिए पूर्णतः भारतीय नहीं है, जबकि कामेट (7,756 m) कम ऊँची है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-185","question":"Which of these is NOT a feature of the retreating monsoon season (October-November) in India?","options":["Clear skies and a rise in day temperature, the 'October heat'","Heavy showers over western Rajasthan and Punjab","Cyclonic storms that form over the Bay of Bengal","Rain over the Coromandel coast of Tamil Nadu"],"answer":1,"explanation":"As the monsoon retreats, north India has clear skies, higher day temperatures and humid heat. The Bay of Bengal produces cyclones and the Coromandel coast gets rain. The north-west is turning dry, not wet.","difficulty":"hard","questionHi":"इनमें से कौन-सा भारत में लौटते मानसून की ऋतु (अक्टूबर-नवंबर) की विशेषता नहीं है?","optionsHi":["साफ़ आकाश और दिन के तापमान में वृद्धि, 'क्वार की उमस'","पश्चिमी राजस्थान और पंजाब में भारी वर्षा","बंगाल की खाड़ी में बनने वाले चक्रवाती तूफान","तमिलनाडु के कोरोमंडल तट पर वर्षा"],"explanationHi":"मानसून के लौटने पर उत्तर भारत में साफ़ आकाश, दिन का ऊँचा तापमान और उमस भरी गर्मी रहती है। बंगाल की खाड़ी चक्रवात देती है और कोरोमंडल तट पर वर्षा होती है। उत्तर-पश्चिम सूख रहा होता है, भीग नहीं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-186","question":"Which of these pairs of map line and quantity is NOT correct?","options":["Isobath: depth of water","Isohaline: salinity","Isohyet: relative humidity","Isohel: duration of sunshine"],"answer":2,"explanation":"An isohyet joins places of equal rainfall; relative humidity is shown by isohumes. Isohels show equal sunshine, isobaths equal depth below sea level, and isohalines equal salinity.","difficulty":"hard","questionHi":"मानचित्र रेखा और राशि के इन युग्मों में से कौन-सा सही नहीं है?","optionsHi":["समगहराई रेखा (आइसोबाथ): जल की गहराई","समलवणता रेखा (आइसोहेलाइन): लवणता","समवर्षा रेखा (आइसोहाइट): सापेक्ष आर्द्रता","समसूर्यातप रेखा (आइसोहेल): धूप की अवधि"],"explanationHi":"समवर्षा रेखा समान वर्षा वाले स्थानों को जोड़ती है; सापेक्ष आर्द्रता आइसोह्यूम दर्शाती हैं। आइसोहेल समान धूप, आइसोबाथ समुद्र तल से नीचे समान गहराई और आइसोहेलाइन समान लवणता दर्शाती हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-187","question":"Who, working with the Great Trigonometrical Survey, first identified Peak XV (Everest) as the world's highest peak in 1852?","options":["Andrew Waugh","William Lambton","George Everest","Radhanath Sikdar"],"answer":3,"explanation":"Radhanath Sikdar, the Survey's chief computer, calculated in 1852 that Peak XV was the highest. Waugh announced it in 1856 and named it after his predecessor Everest, while Lambton started the Great Arc in 1802.","difficulty":"very-hard","questionHi":"महान त्रिकोणमितीय सर्वेक्षण में कार्यरत किस व्यक्ति ने 1852 में सबसे पहले शिखर XV (एवरेस्ट) को विश्व का सर्वोच्च शिखर पहचाना?","optionsHi":["एंड्रयू वॉ","विलियम लैम्बटन","जॉर्ज एवरेस्ट","राधानाथ सिकदर"],"explanationHi":"सर्वेक्षण के मुख्य गणनाकार राधानाथ सिकदर ने 1852 में गणना की कि शिखर XV सर्वोच्च है। वॉ ने 1856 में इसकी घोषणा की और अपने पूर्ववर्ती एवरेस्ट के नाम पर इसका नाम रखा, जबकि लैम्बटन ने 1802 में महान चाप शुरू किया था।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-188","question":"A Survey of India topographical sheet at the scale of 1:50,000 covers an area of:","options":["15′ of latitude by 15′ of longitude","30′ of latitude by 30′ of longitude","5′ of latitude by 5′ of longitude","1° of latitude by 1° of longitude"],"answer":0,"explanation":"The 1:1,000,000 sheet covers 4° x 4°, the 1:250,000 sheet 1° x 1°, and each 1:50,000 sheet 15′ x 15′, sixteen of which make up a 1:250,000 sheet.","difficulty":"very-hard","questionHi":"1:50,000 पैमाने की भारतीय सर्वेक्षण विभाग की स्थलाकृतिक शीट कितने क्षेत्र को ढकती है?","optionsHi":["अक्षांश के 15′ x देशांतर के 15′","अक्षांश के 30′ x देशांतर के 30′","अक्षांश के 5′ x देशांतर के 5′","अक्षांश के 1° x देशांतर के 1°"],"explanationHi":"1:1,000,000 की शीट 4° x 4°, 1:250,000 की शीट 1° x 1° और प्रत्येक 1:50,000 की शीट 15′ x 15′ को ढकती है, जिनमें से सोलह मिलकर एक 1:250,000 की शीट बनाती हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-189","question":"Phawngpui, also called the Blue Mountain, is the highest peak of which State?","options":["Tripura","Mizoram","Nagaland","Manipur"],"answer":1,"explanation":"Phawngpui (about 2,157 m) in the Lushai hills of south Mizoram is the State's highest peak. Manipur's high point is in the Naga hills, Nagaland's is Saramati, and Tripura's hills are much lower.","difficulty":"hard","questionHi":"फॉन्गपुई, जिसे नीला पर्वत भी कहते हैं, किस राज्य की सबसे ऊँची चोटी है?","optionsHi":["त्रिपुरा","मिज़ोरम","नागालैंड","मणिपुर"],"explanationHi":"दक्षिणी मिज़ोरम की लुशाई पहाड़ियों में फॉन्गपुई (लगभग 2,157 m) राज्य की सबसे ऊँची चोटी है। मणिपुर का ऊँचा बिंदु नागा पहाड़ियों में है, नागालैंड का सारामती है और त्रिपुरा की पहाड़ियाँ बहुत नीची हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-physical-india-190","question":"Reo Purgyil, the highest peak of Himachal Pradesh, lies in which district, close to the Tibet border?","options":["Chamba","Kullu","Kinnaur","Lahaul and Spiti"],"answer":2,"explanation":"Reo Purgyil (about 6,816 m) is in the Kinnaur district, on the Tibet border, near the Sutlej's entry at Shipki La. Lahaul and Spiti, Kullu and Chamba have lofty peaks too, but lower.","difficulty":"very-hard","questionHi":"हिमाचल प्रदेश की सबसे ऊँची चोटी रियो पुर्गिल, तिब्बत सीमा के निकट किस जिले में स्थित है?","optionsHi":["चंबा","कुल्लू","किन्नौर","लाहौल और स्पीति"],"explanationHi":"रियो पुर्गिल (लगभग 6,816 m) तिब्बत सीमा पर किन्नौर जिले में है, जहाँ सतलुज शिपकी ला से प्रवेश करती है। लाहौल और स्पीति, कुल्लू और चंबा में भी ऊँची चोटियाँ हैं, पर कम ऊँची।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-191","question":"The highest peak in the Indian-administered part of the Ladakh region, rising in the Karakoram and about 7,670 m, is:","options":["Nun, in the Zanskar","Kun, in the Zanskar","Kolahoi, in Kashmir","Saser Kangri"],"answer":3,"explanation":"Saser Kangri I (about 7,672 m) in the Saser Muztagh of the Karakoram is the highest peak in Indian-administered Ladakh. Nun (7,135 m) and Kun are in the Zanskar, and Kolahoi is in the Kashmir Himalaya.","difficulty":"very-hard","questionHi":"लद्दाख क्षेत्र के भारत-प्रशासित भाग की सर्वोच्च चोटी, जो काराकोरम में लगभग 7,670 m ऊँची है, कौन-सी है?","optionsHi":["नुन, ज़ांस्कर में","कुन, ज़ांस्कर में","कोलाहोई, कश्मीर में","सासेर कांगड़ी"],"explanationHi":"काराकोरम के सासेर मुज़ताग में सासेर कांगड़ी I (लगभग 7,672 m) भारत-प्रशासित लद्दाख की सर्वोच्च चोटी है। नुन (7,135 m) और कुन ज़ांस्कर में हैं और कोलाहोई कश्मीर हिमालय में है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-192","question":"The Barail range in Assam separates which two river valleys?","options":["The Brahmaputra valley and the Barak valley","The Brahmaputra valley and the Teesta valley","The Dihang valley and the Lohit valley","The Barak valley and the Imphal valley"],"answer":0,"explanation":"The Barail range, in the Dima Hasao hills, lies between the Brahmaputra valley in the north and the Barak valley in the south, which includes Cachar. It forms the drainage divide between them.","difficulty":"very-hard","questionHi":"असम की बराइल श्रेणी किन दो नदी घाटियों को अलग करती है?","optionsHi":["ब्रह्मपुत्र घाटी और बराक घाटी","ब्रह्मपुत्र घाटी और तीस्ता घाटी","दिहांग घाटी और लोहित घाटी","बराक घाटी और इंफाल घाटी"],"explanationHi":"दीमा हसाओ पहाड़ियों में स्थित बराइल श्रेणी उत्तर में ब्रह्मपुत्र घाटी और दक्षिण में बराक घाटी (जिसमें कछार है) के बीच है। यह उनके बीच जल विभाजक बनाती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-193","question":"The Banihal and Rohtang passes both cross which mountain range?","options":["Ladakh range","Pir Panjal range","Zanskar range","Dhauladhar range"],"answer":1,"explanation":"Both the Banihal pass (Jammu to the Kashmir valley) and Rohtang (Kullu to Lahaul) cross the Pir Panjal, the longest range of the Lesser Himalaya. The Dhauladhar is a separate range near Dharamshala.","difficulty":"hard","questionHi":"बनिहाल और रोहतांग दर्रे दोनों किस पर्वत श्रेणी को पार करते हैं?","optionsHi":["लद्दाख श्रेणी","पीर पंजाल श्रेणी","ज़ांस्कर श्रेणी","धौलाधार श्रेणी"],"explanationHi":"बनिहाल दर्रा (जम्मू से कश्मीर घाटी) और रोहतांग (कुल्लू से लाहौल) दोनों लघु हिमालय की सबसे लंबी श्रेणी पीर पंजाल को पार करते हैं। धौलाधार धर्मशाला के निकट की एक अलग श्रेणी है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-194","question":"The 'rice bowl' plain of Chhattisgarh, lying between the Maikal range in the north and the Dandakaranya plateau in the south, is drained mainly by the:","options":["Godavari and its tributary Indravati","Son and its tributary Rihand","Mahanadi and its tributary Seonath","Narmada and its tributary Hiran"],"answer":2,"explanation":"The Chhattisgarh plain is the upper basin of the Mahanadi, with the Seonath, Hasdeo and Mand as tributaries. The Indravati, flowing in Bastar to the south, belongs to the Godavari system.","difficulty":"hard","questionHi":"छत्तीसगढ़ का 'धान का कटोरा' मैदान, जो उत्तर में मैकाल श्रेणी और दक्षिण में दंडकारण्य पठार के बीच है, मुख्यतः किससे अपवाहित है?","optionsHi":["गोदावरी और उसकी सहायक इंद्रावती","सोन और उसकी सहायक रिहंद","महानदी और उसकी सहायक शिवनाथ","नर्मदा और उसकी सहायक हिरन"],"explanationHi":"छत्तीसगढ़ का मैदान महानदी का ऊपरी बेसिन है, जिसकी सहायक नदियाँ शिवनाथ, हसदेव और माँड हैं। दक्षिण में बस्तर में बहने वाली इंद्रावती गोदावरी तंत्र की है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-195","question":"The Rajmahal hills of Jharkhand are made largely of:","options":["Coal-bearing Gondwana sandstones and shales","Thick laterite capping over ancient granite and gneiss","Folded Vindhyan sandstones, limestones and shales deposited in shallow seas","Basaltic lava flows known as the Rajmahal Traps"],"answer":3,"explanation":"The Rajmahal hills carry a series of basalt lava flows (the Rajmahal Traps), erupted in the Cretaceous earlier than the Deccan Traps, with Gondwana sediments beneath them in the nearby Damodar valley.","difficulty":"hard","questionHi":"झारखंड की राजमहल पहाड़ियाँ मुख्यतः किससे बनी हैं?","optionsHi":["कोयला-धारक गोंडवाना शेल","ग्रेनाइट पर लैटेराइट की टोपी","वलित विंध्यन बलुआ पत्थर और चूना पत्थर","बेसाल्टी लावा प्रवाह, जिन्हें राजमहल ट्रैप कहते हैं"],"explanationHi":"राजमहल पहाड़ियों पर बेसाल्ट लावा प्रवाहों की श्रृंखला (राजमहल ट्रैप) है, जो क्रिटेशियस में दक्कन ट्रैप से पहले उद्गारित हुई थी, और पास की दामोदर घाटी में उसके नीचे गोंडवाना अवसाद हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-196","question":"The coral atolls of Lakshadweep rest on a submarine ridge known as the:","options":["Chagos-Laccadive ridge","Carlsberg ridge, mid Indian Ocean","Ninety East ridge, in the Bay of Bengal","Mascarene ridge, near Mauritius"],"answer":0,"explanation":"Lakshadweep's coral islands are built on the northern part of the Chagos-Laccadive ridge, a submerged volcanic ridge running north-south in the Arabian Sea. The Ninety East ridge lies in the Bay of Bengal side, and Carlsberg is a mid-ocean ridge.","difficulty":"very-hard","questionHi":"लक्षद्वीप के प्रवाल एटॉल किस जलमग्न कटक पर टिके हैं?","optionsHi":["चागोस–लक्कादीव कटक","कार्ल्सबर्ग कटक, हिंद महासागर के मध्य","90° पूर्व कटक, बंगाल की खाड़ी में","मैस्करीन कटक, मॉरीशस के निकट"],"explanationHi":"लक्षद्वीप के प्रवाल द्वीप चागोस–लक्कादीव कटक के उत्तरी भाग पर बने हैं, जो अरब सागर में उत्तर-दक्षिण फैला जलमग्न ज्वालामुखीय कटक है। 90° पूर्व कटक बंगाल की खाड़ी की ओर है और कार्ल्सबर्ग मध्य-महासागरीय कटक है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-197","question":"Which pair of high-altitude meadow type and region is correct?","options":["Bugyal: Kashmir Himalaya, as at Gulmarg and Sonamarg","Marg: Kashmir Himalaya, as at Gulmarg and Sonamarg","Marg: Garhwal Himalaya, as at Auli and Dayara","Bugyal: Sikkim Himalaya, as at Gurudongmar and Yumthang"],"answer":1,"explanation":"Alpine meadows are called margs in Kashmir (Gulmarg, Sonamarg, Tosamaidan) and bugyals in Garhwal and Kumaon (Auli, Dayara, Panwali Kantha). The two terms are regional, so swapping them is the trap.","difficulty":"hard","questionHi":"उच्च पर्वतीय घास के मैदान के प्रकार और क्षेत्र का कौन-सा युग्म सही है?","optionsHi":["बुग्याल: कश्मीर हिमालय, जैसे गुलमर्ग और सोनमर्ग","मर्ग: कश्मीर हिमालय, जैसे गुलमर्ग और सोनमर्ग","मर्ग: गढ़वाल हिमालय, जैसे औली और दयारा","बुग्याल: सिक्किम हिमालय, जैसे गुरुडोंगमार और युमथांग"],"explanationHi":"अल्पाइन घास के मैदान कश्मीर में मर्ग (गुलमर्ग, सोनमर्ग, तोसामैदान) और गढ़वाल तथा कुमाऊँ में बुग्याल (औली, दयारा, पंवाली कांठा) कहलाते हैं। दोनों शब्द क्षेत्रीय हैं, इसलिए उन्हें बदल देना भ्रम है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-physical-india-198","question":"Match the doab of the Punjab plain with the rivers that bound it. A. Bist  B. Bari  C. Rachna  D. Chaj. 1. Beas and Sutlej  2. Beas and Ravi  3. Ravi and Chenab  4. Chenab and Jhelum","options":["A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4"],"answer":2,"explanation":"The names of the Punjab doabs run from east to west: Bist (Beas-Sutlej), Bari (Beas-Ravi), Rachna (Ravi-Chenab), Chaj (Chenab-Jhelum), then Sind Sagar between the Indus and the Jhelum-Chenab.","difficulty":"very-hard","questionHi":"पंजाब के मैदान के दोआब का उसे घेरने वाली नदियों से मिलान कीजिए। A. बिस्त  B. बारी  C. रचना  D. चाज। 1. ब्यास और सतलुज  2. ब्यास और रावी  3. रावी और चिनाब  4. चिनाब और झेलम","optionsHi":["A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4"],"explanationHi":"पंजाब के दोआबों के नाम पूर्व से पश्चिम इस क्रम में हैं: बिस्त (ब्यास–सतलुज), बारी (ब्यास–रावी), रचना (रावी–चिनाब), चाज (चिनाब–झेलम), फिर सिंधु और झेलम–चिनाब के बीच सिंध सागर।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-199","question":"Which of these States is crossed by the standard meridian of India, 82°30′ E?","options":["Bihar","Jharkhand","Telangana","Odisha"],"answer":3,"explanation":"The 82°30′ E meridian crosses Uttar Pradesh, Madhya Pradesh, Chhattisgarh, Odisha and Andhra Pradesh. Jharkhand and Bihar lie east of it and Telangana lies west of it, entirely between about 77°E and 81°48′E.","difficulty":"very-hard","questionHi":"इनमें से कौन-सा राज्य भारत के मानक याम्योत्तर, 82°30′ पूर्व, द्वारा पार किया जाता है?","optionsHi":["बिहार","झारखंड","तेलंगाना","ओडिशा"],"explanationHi":"82°30′ पूर्व याम्योत्तर उत्तर प्रदेश, मध्य प्रदेश, छत्तीसगढ़, ओडिशा और आंध्र प्रदेश को पार करता है। झारखंड और बिहार उसके पूर्व में हैं और तेलंगाना उसके पश्चिम में, लगभग 77°पूर्व और 81°48′पूर्व के बीच पूरी तरह स्थित है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-200","question":"Which statement best describes the Western Ghats?","options":["An escarpment along the western edge of the Deccan plateau, steep towards the sea and gentle inland","A young fold range formed by the collision of the Indian and Arabian plates, and still being slowly uplifted today","A series of residual hills left behind by long erosion of the old Aravalli folds","A chain of extinct volcanic cones built up by the repeated Deccan lava eruptions"],"answer":0,"explanation":"The Western Ghats are the faulted western edge of the peninsular plateau, with a steep scarp facing the Arabian Sea and a gentle eastern slope. They are not fold mountains, and they are cut through the Deccan basalt in the north.","difficulty":"hard","questionHi":"पश्चिमी घाट का सर्वोत्तम वर्णन कौन-सा कथन करता है?","optionsHi":["दक्कन पठार के पश्चिमी किनारे पर एक कगार, जो समुद्र की ओर तीव्र और अंदर की ओर मंद ढाल वाली है","भारतीय और अरब प्लेटों की टक्कर से बनी नवीन वलित श्रेणी","प्राचीन अरावली वलनों के अपरदन से बची अवशिष्ट पहाड़ियों की शृंखला","दक्कन लावा उद्गारों से बने विलुप्त ज्वालामुखियों की शृंखला"],"explanationHi":"पश्चिमी घाट प्रायद्वीपीय पठार का भ्रंशित पश्चिमी किनारा है, जिसकी अरब सागर की ओर तीव्र कगार और पूर्व में मंद ढाल है। ये वलित पर्वत नहीं हैं और उत्तर में दक्कन बेसाल्ट को काटकर बने हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-201","question":"The Satpura range is best described as:","options":["A plateau scarp formed by wind erosion in the Thar","A block (horst) mountain between the Narmada and Tapi rift valleys","A volcanic cone built by the Deccan eruptions","A fold mountain formed by the same collision that raised the Himalaya"],"answer":1,"explanation":"The Satpura lies between the down-faulted Narmada and Tapi troughs, and so is a horst, a block that stands up between two fault valleys. Its old crystalline rocks are capped by Deccan basalt in the west.","difficulty":"hard","questionHi":"सतपुड़ा श्रेणी का सर्वोत्तम वर्णन है:","optionsHi":["थार में पवन अपरदन से बना पठारी कगार","नर्मदा और तापी की भ्रंश घाटियों के बीच एक ब्लॉक (होर्स्ट) पर्वत","दक्कन उद्गारों से बना ज्वालामुखी शंकु","उसी टक्कर से बना वलित पर्वत जिसने हिमालय को उठाया"],"explanationHi":"सतपुड़ा नीचे धँसी नर्मदा और तापी द्रोणियों के बीच है, इसलिए वह होर्स्ट है, यानी दो भ्रंश घाटियों के बीच उठा हुआ ब्लॉक। इसकी प्राचीन क्रिस्टलीय चट्टानें पश्चिम में दक्कन बेसाल्ट से ढकी हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-202","question":"A 'break' in the monsoon, with a dry spell over the plains lasting several days in July or August, occurs mainly when:","options":["The Bay of Bengal branch of the monsoon fails to form a low-pressure system","The axis of the monsoon trough shifts south over the Deccan plateau","The axis of the monsoon trough shifts northwards to the foothills of the Himalaya","Western disturbances push in from the Mediterranean across north India"],"answer":2,"explanation":"The monsoon trough normally lies over the Ganga plain. When it moves to the Himalayan foothills, the plains lose their rain, which now falls heavily in the Himalayan foothills, while a break begins in central India.","difficulty":"very-hard","questionHi":"जुलाई या अगस्त में मैदानों पर कई दिन के शुष्क दौर वाला मानसून का 'विराम' मुख्यतः तब होता है जब:","optionsHi":["मानसून की बंगाल की खाड़ी की शाखा निम्न दाब प्रणाली नहीं बना पाती","मानसून द्रोणी की धुरी दक्कन पठार के ऊपर दक्षिण में खिसक जाती है","मानसून द्रोणी की धुरी हिमालय की तलहटी की ओर उत्तर में खिसक जाती है","पश्चिमी विक्षोभ भूमध्य सागर से उत्तर भारत में घुस आते हैं"],"explanationHi":"मानसून द्रोणी सामान्यतः गंगा के मैदान के ऊपर रहती है। जब वह हिमालय की तलहटी में चली जाती है, तो मैदानों की वर्षा रुक जाती है, जो अब तलहटी में भारी रूप से बरसती है, और मध्य भारत में विराम शुरू होता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-203","question":"The variability of annual rainfall, measured by its coefficient of variation, is highest in:","options":["The windward slopes of the Western Ghats","The Meghalaya hills and Cherrapunji","The Brahmaputra valley of Assam","Western Rajasthan and Kachchh"],"answer":3,"explanation":"Rainfall is least reliable where it is scanty: western Rajasthan, Kachchh and parts of Ladakh show coefficients above 50%. Regions of heavy rain, such as the windward Ghats and the north-east, show low variability, below about 15-25%.","difficulty":"hard","questionHi":"वार्षिक वर्षा की परिवर्तनशीलता, जिसे उसके विचरण गुणांक से मापा जाता है, कहाँ सबसे अधिक है?","optionsHi":["पश्चिमी घाट","मेघालय की पहाड़ियाँ","ब्रह्मपुत्र घाटी","पश्चिमी राजस्थान और कच्छ"],"explanationHi":"वर्षा वहाँ सबसे अविश्वसनीय होती है जहाँ वह कम है: पश्चिमी राजस्थान, कच्छ और लद्दाख के कुछ भागों में गुणांक 50% से अधिक है। भारी वर्षा वाले क्षेत्रों, जैसे पवनाभिमुख घाट और पूर्वोत्तर, में परिवर्तनशीलता कम, लगभग 15-25% से नीचे, है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-204","question":"The annual range of temperature is much greater at Delhi than at Mumbai mainly because Delhi:","options":["Lies far from the moderating influence of the sea","Is at a higher altitude above sea level","Is shielded by the Aravalli from monsoon winds","Is at a higher latitude with a longer summer day"],"answer":0,"explanation":"Mumbai's coastal location gives a maritime climate with small seasonal swings, whereas Delhi's continental position heats up fast in summer and cools sharply in winter. Delhi's altitude (about 216 m) is too small to explain the difference.","difficulty":"moderate","questionHi":"दिल्ली में तापमान का वार्षिक परास मुंबई की अपेक्षा बहुत अधिक है, मुख्यतः क्योंकि दिल्ली:","optionsHi":["समुद्र के संतुलनकारी प्रभाव से बहुत दूर स्थित है","समुद्र तल से अधिक ऊँचाई पर है","अरावली से मानसूनी पवनों से सुरक्षित है","उच्च अक्षांश पर है जहाँ ग्रीष्म का दिन लंबा होता है"],"explanationHi":"मुंबई की तटीय स्थिति से समुद्री जलवायु मिलती है जिसमें ऋतुओं का अंतर कम है, जबकि दिल्ली की महाद्वीपीय स्थिति में गर्मी में वह तेज़ी से तपती और सर्दी में तेज़ी से ठंडी होती है। दिल्ली की ऊँचाई (लगभग 216 m) अंतर समझाने के लिए बहुत कम है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-physical-india-205","question":"The Amarkantak plateau, from which the Narmada, Son and Johila rise and flow in different directions, shows which drainage pattern?","options":["Rectangular","Radial","Trellis","Dendritic"],"answer":1,"explanation":"In radial drainage, streams flow outwards in all directions from a central high point, like the spokes of a wheel. Trellis patterns occur on alternating hard and soft folded rocks, and dendritic on uniform rock, like the Ganga plain.","difficulty":"hard","questionHi":"अमरकंटक पठार, जहाँ से नर्मदा, सोन और जोहिला निकलकर अलग-अलग दिशाओं में बहती हैं, कौन-सा अपवाह प्रतिरूप दर्शाता है?","optionsHi":["आयताकार","अरीय","जालीदार","वृक्षाकार"],"explanationHi":"अरीय अपवाह में धाराएँ किसी केंद्रीय ऊँचे बिंदु से पहिये की तीलियों की तरह सभी दिशाओं में बाहर बहती हैं। जालीदार प्रतिरूप एकांतर कठोर और मुलायम वलित चट्टानों पर और वृक्षाकार एकसमान चट्टान पर, जैसे गंगा के मैदान में, मिलता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-206","question":"Which statement correctly contrasts the west and east coasts of peninsular India?","options":["The west coast is an emergent coast with deltas, and the east coast a submerged coast with estuaries","Both coasts are emergent coasts, but the west coast is wider because of the Western Ghats","The west coast is a submerged coast with estuaries, and the east coast an emergent coast with deltas","Both coasts are submerged coasts, but the east coast is wider because of heavier rain"],"answer":2,"explanation":"The western coast has sunk (faulting along the Ghats), giving a narrow plain, rias and estuaries. The eastern coast has risen, with a broad plain built by large deltas of the Mahanadi, Godavari, Krishna and Kaveri.","difficulty":"very-hard","questionHi":"कौन-सा कथन प्रायद्वीपीय भारत के पश्चिमी और पूर्वी तटों की सही तुलना करता है?","optionsHi":["पश्चिमी तट डेल्टाओं वाला उन्मज्जित तट है और पूर्वी तट ज्वारनदमुखों वाला निमज्जित तट है","दोनों तट उन्मज्जित हैं, पर पश्चिमी तट पश्चिमी घाट के कारण चौड़ा है","पश्चिमी तट ज्वारनदमुखों वाला निमज्जित तट है और पूर्वी तट डेल्टाओं वाला उन्मज्जित तट है","दोनों तट निमज्जित हैं, पर पूर्वी तट अधिक वर्षा के कारण चौड़ा है"],"explanationHi":"पश्चिमी तट धँसा है (घाट के साथ भ्रंशन), जिससे संकरा मैदान, रिया और ज्वारनदमुख बने हैं। पूर्वी तट उठा है, जहाँ महानदी, गोदावरी, कृष्णा और कावेरी के बड़े डेल्टाओं से चौड़ा मैदान बना है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-207","question":"Karakoram Pass, historically on the Leh-Yarkand trade route, lies on the border of which two regions?","options":["Kashmir valley and Gilgit","Sikkim and Tibet","Himachal Pradesh and Tibet","Ladakh and Xinjiang"],"answer":3,"explanation":"At about 5,540 m, Karakoram Pass lies north of Leh and links Ladakh with Xinjiang, on the old Silk Route. Himachal's Shipki La and Sikkim's Nathu La are the passes on the Tibetan side.","difficulty":"hard","questionHi":"काराकोरम दर्रा, जो ऐतिहासिक रूप से लेह–यारकंद व्यापार मार्ग पर है, किन दो क्षेत्रों की सीमा पर स्थित है?","optionsHi":["कश्मीर घाटी और गिलगित","सिक्किम और तिब्बत","हिमाचल प्रदेश और तिब्बत","लद्दाख और शिनजियांग"],"explanationHi":"लगभग 5,540 m पर काराकोरम दर्रा लेह के उत्तर में है और प्राचीन रेशम मार्ग पर लद्दाख को शिनजियांग से जोड़ता है। हिमाचल का शिपकी ला और सिक्किम का नाथू ला तिब्बत की ओर के दर्रे हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-208","question":"Which statement about the sea areas on either side of Adam's Bridge (Rama's Bridge) is correct?","options":["Palk Bay lies to its north and the Gulf of Mannar to its south","Palk Bay and the Gulf of Mannar both lie to its north","Palk Bay lies to its south and the Gulf of Mannar to its north","Palk Bay lies to its east and the Gulf of Mannar to its west"],"answer":0,"explanation":"The chain of shoals runs from Pamban (Rameswaram) to Mannar island. The shallow Palk Bay lies to the north, and the deeper Gulf of Mannar to the south, with the Palk Strait further north still.","difficulty":"hard","questionHi":"आदम पुल (राम सेतु) के दोनों ओर के समुद्री क्षेत्रों के बारे में कौन-सा कथन सही है?","optionsHi":["पाक खाड़ी उसके उत्तर में और मन्नार की खाड़ी उसके दक्षिण में है","पाक खाड़ी और मन्नार की खाड़ी दोनों उसके उत्तर में हैं","पाक खाड़ी उसके दक्षिण में और मन्नार की खाड़ी उसके उत्तर में है","पाक खाड़ी उसके पूर्व में और मन्नार की खाड़ी उसके पश्चिम में है"],"explanationHi":"शोलों की यह शृंखला पंबन (रामेश्वरम) से मन्नार द्वीप तक है। उथली पाक खाड़ी उत्तर में और गहरी मन्नार की खाड़ी दक्षिण में है, जबकि पाक जलडमरूमध्य उससे भी उत्तर में है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-physical-india-209","question":"The devastating tsunami of 26 December 2004, which struck the Andaman and Nicobar Islands and the coast of Tamil Nadu, was triggered by an earthquake at the:","options":["Himalayan frontal thrust at the Indo-Gangetic plain","Sunda trench subduction zone off Sumatra","Carlsberg ridge, in the western Indian Ocean","Makran subduction zone off Pakistan"],"answer":1,"explanation":"A magnitude 9.1 megathrust earthquake on the Sunda trench, where the Indian plate subducts under the Burma microplate off Sumatra, displaced the sea floor and sent waves across the Indian Ocean. The Makran zone lies far to the west.","difficulty":"hard","questionHi":"26 दिसंबर 2004 की विनाशकारी सुनामी, जिसने अंडमान-निकोबार द्वीपसमूह और तमिलनाडु तट पर प्रहार किया, किस स्थान के भूकंप से उत्पन्न हुई थी?","optionsHi":["इंडो-गंगा मैदान पर हिमालयी अग्र क्षेप","सुमात्रा के पास सुंडा खाई क्षेपण क्षेत्र","पश्चिमी हिंद महासागर में कार्ल्सबर्ग कटक","पाकिस्तान के पास मकरान क्षेपण क्षेत्र"],"explanationHi":"सुंडा खाई पर 9.1 परिमाण के महाक्षेपी भूकंप ने, जहाँ भारतीय प्लेट सुमात्रा के पास बर्मा सूक्ष्म प्लेट के नीचे धँसती है, समुद्र तल को विस्थापित किया और लहरें हिंद महासागर में फैल गईं। मकरान क्षेत्र बहुत पश्चिम में है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-210","question":"Chilika lagoon was formed mainly by:","options":["Tectonic subsidence along a long fault line at the foot of the Eastern Ghats hills","A large river meander that was cut off and slowly filled with sea water in time","A sand bar built across a shallow bay by longshore drift and river-borne sediment","A meteor impact crater that was later flooded by the sea over many thousands of years"],"answer":2,"explanation":"A long barrier spit, built up by longshore currents and the sediment of the Mahanadi's distributaries, has closed off the shallow bay, leaving Chilika joined to the Bay of Bengal by a narrow channel. Lonar, not Chilika, is the meteor crater.","difficulty":"hard","questionHi":"चिल्का लैगून मुख्यतः किससे बनी?","optionsHi":["पूर्वी घाट में एक भ्रंश के साथ विवर्तनिक अवतलन से","नदी के छोड़े गए विसर्प से, जो समुद्री जल से भर गया","तटीय धारा और नदी द्वारा लाए अवसाद से उथली खाड़ी के आर-पार बनी रेत की रोधिका से","उल्कापिंड के गड्ढे से, जो बाद में समुद्र से भर गया"],"explanationHi":"तटीय धाराओं और महानदी की वितरिकाओं के अवसाद से बनी लंबी रोधिका ने उथली खाड़ी को घेर लिया, जिससे चिल्का संकरे मार्ग से बंगाल की खाड़ी से जुड़ी है। उल्कापिंड का गड्ढा चिल्का नहीं, लोनार है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-physical-india-211","question":"The Bundelkhand upland of Uttar Pradesh and Madhya Pradesh is mainly made of:","options":["Limestone, drained by the Mahi and Luni","Deccan basalt, drained by the Narmada and Tapi","Alluvium, drained by the Ganga and Yamuna","Granite and gneiss, drained by the Betwa and Ken"],"answer":3,"explanation":"Bundelkhand is an undulating upland of ancient granite and gneiss with thin soils, drained by the Betwa, Ken and Dhasan. Deccan basalt lies farther south and west, and alluvium covers the Ganga plain to its north.","difficulty":"hard","questionHi":"उत्तर प्रदेश और मध्य प्रदेश का बुंदेलखंड उच्चभूमि मुख्यतः किससे बनी है?","optionsHi":["चूना पत्थर, जो माही और लूनी से अपवाहित है","दक्कन बेसाल्ट, जो नर्मदा और तापी से अपवाहित है","जलोढ़, जो गंगा और यमुना से अपवाहित है","ग्रेनाइट और नाइस, जो बेतवा और केन से अपवाहित है"],"explanationHi":"बुंदेलखंड प्राचीन ग्रेनाइट और नाइस की ऊबड़-खाबड़ उच्चभूमि है जिसकी मिट्टी पतली है और जो बेतवा, केन और धसान से अपवाहित है। दक्कन बेसाल्ट और दक्षिण-पश्चिम में है तथा गंगा का मैदान जलोढ़ से ढका उसके उत्तर में है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-physical-india-212","question":"Gurudongmar, one of the highest lakes in India, lying at over 5,000 m close to the Tibetan border, is in:","options":["North Sikkim","Ladakh","Arunachal Pradesh","Uttarakhand"],"answer":0,"explanation":"Gurudongmar lake lies in the Lachen valley of North Sikkim at about 5,100-5,400 m. The lakes of Ladakh, such as Tso Moriri and Pangong, are lower, and the lake is held sacred by Buddhists and Sikhs.","difficulty":"hard","questionHi":"गुरुडोंगमार, जो भारत की सबसे ऊँची झीलों में से एक है और तिब्बती सीमा के निकट 5,000 m से अधिक ऊँचाई पर है, कहाँ स्थित है?","optionsHi":["उत्तरी सिक्किम","लद्दाख","अरुणाचल प्रदेश","उत्तराखंड"],"explanationHi":"गुरुडोंगमार झील उत्तरी सिक्किम की लाचेन घाटी में लगभग 5,100-5,400 m पर है। लद्दाख की झीलें, जैसे त्सो मोरीरी और पैंगोंग, कम ऊँची हैं, और बौद्धों तथा सिखों के लिए यह झील पवित्र है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-physical-india-213","question":"The super cyclone that devastated the Odisha coast in October 1999 made landfall near:","options":["Balasore","Paradip","Gopalpur","Puri"],"answer":1,"explanation":"The super cyclone of 29 October 1999, among the strongest ever recorded in the Bay of Bengal, crossed the coast near Paradip in Jagatsinghpur district, with a storm surge that carried far inland.","difficulty":"hard","questionHi":"अक्टूबर 1999 का महाचक्रवात, जिसने ओडिशा तट को तहस-नहस किया, किसके निकट तट पर पहुँचा?","optionsHi":["बालासोर","पारादीप","गोपालपुर","पुरी"],"explanationHi":"29 अक्टूबर 1999 का महाचक्रवात, जो बंगाल की खाड़ी में अब तक दर्ज सबसे प्रबल चक्रवातों में है, जगतसिंहपुर जिले के पारादीप के निकट तट पार कर गया, और उसकी तूफानी लहर भीतर दूर तक पहुँची।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-physical-india-214","question":"At which of these places will the midday Sun NEVER be directly overhead at any time of the year?","options":["Kolkata","Ahmedabad","Delhi","Chennai"],"answer":2,"explanation":"The overhead Sun reaches only up to the Tropic of Cancer (23.5° N). Delhi (about 28.6° N) lies north of it, while Ahmedabad (about 23° N), Kolkata (about 22.6° N) and Chennai (about 13° N) all lie south of it and get a vertical Sun.","difficulty":"hard","questionHi":"इनमें से किस स्थान पर वर्ष में कभी भी दोपहर का सूर्य ठीक सिर के ऊपर नहीं होता?","optionsHi":["कोलकाता","अहमदाबाद","दिल्ली","चेन्नई"],"explanationHi":"सिर के ऊपर का सूर्य केवल कर्क रेखा (23.5° उत्तर) तक पहुँचता है। दिल्ली (लगभग 28.6° उत्तर) उसके उत्तर में है, जबकि अहमदाबाद (लगभग 23° उत्तर), कोलकाता (लगभग 22.6° उत्तर) और चेन्नई (लगभग 13° उत्तर) सभी उसके दक्षिण में हैं और उन्हें ऊर्ध्वाधर सूर्य मिलता है।","source":"UPSC Prelims · SSC CGL"},
];

export default questions;
